window.kbParts["entries-ee9d07510edee030"] = {"nodes":{"k-51cdd4a5233b6c21":{"review":{"definition":"习近平在《加快建设农业强国 推进农业农村现代化》中提出，建设农业强国要依靠科技和改革双轮驱动，协同推进科技创新和制度创新。","explanation":"文章以核心种源、关键农机装备等技术攻关说明科技怎样提升农业生产能力，以深化农村土地制度改革说明改革怎样激活资源要素。B项准确对应了“利器在科技，关键靠改革”，属于本题选非时应排除的正确表述。","references":[{"source":"web-49f2df3cce6ee928","location":"第四部分“依靠科技和改革双轮驱动加快建设农业强国”","quote":"必须协同推进科技创新和制度创新"}],"evidence":"建设农业强国，利器在科技，关键靠改革。","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-2508a8c3d2b8ffe2":{"review":{"definition":"习近平在《促进民营经济健康发展、高质量发展》中指出，企业是经营主体，从根本上说，企业发展内生动力是第一位的。","explanation":"文章把务实创新、克难奋进的要求落到民营企业和民营企业家身上，同时明确党和政府有责任创造良好发展环境。③保留了创造良好环境的表述，却把首要因素换成了政府扶持，因此不成立。","references":[],"evidence":"企业发展内生动力是第一位的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7918765de46b9f7d":{"review":{"definition":"习近平总书记在十四届全国人大三次会议江苏代表团审议时指出，科技创新和产业创新是发展新质生产力的基本路径。","explanation":"这项论述把形成科技成果和将成果转化为现实生产力连在一起，并提出着眼建设现代化产业体系，把教育、科技、人才一起抓。第14题B项保留了科技创新和产业创新两方面，符合讲话原意，因此在选非题中排除。","references":[],"evidence":"科技创新和产业创新，是发展新质生产力的基本路径","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-890ab1c528d1f9b1":{"review":{"definition":"习近平总书记在2024年全国科技大会、国家科学技术奖励大会、两院院士大会上指出，强化企业科技创新主体地位是推动科技创新和产业创新深度融合的关键。","explanation":"讲话提出发挥科技领军企业的龙头作用，鼓励中小企业和民营企业创新，并支持企业牵头或参与国家重大科技项目。第14题D项把讲话明确的主体由企业换成国有科研机构，改变了政策表述，因此是该选非题的答案。","references":[],"evidence":"融合的关键是强化企业科技创新主体地位。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-26ccecdf8d085d78":{"review":{"definition":"2022年11月4日，习近平在第五届中国国际进口博览会开幕式上指出，进博会是中国构建新发展格局的窗口、推动高水平开放的平台、全球共享的国际公共产品。","explanation":"致辞把三重定位联系到举办进博会的初衷，即扩大开放，让各国共享中国大市场的机遇。C项同时准确复述了三重定位和“开放是世界繁荣发展的必由之路”的判断。","references":[{"source":"web-a66c43f9c012ba22","location":"第五届中国国际进口博览会开幕式致辞，“5年前，我宣布举办进博会”段","quote":"全球共享的国际公共产品"}],"evidence":"全球共享的国际公共产品","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-78ef3a7d043c5233":{"review":{"definition":"习近平总书记在十八届中央政治局第十九次集体学习时指出，不断扩大对外开放、提高对外开放水平，以开放促改革、促发展，是我国发展不断取得新成就的重要法宝。","explanation":"在这段讲话中，扩大开放和提高开放水平是推动改革与发展的途径。第17题B项把“以开放促改革”改为“以改革促开放”，调换了这段论述中的作用方向，因此排除。","references":[],"evidence":"以开放促改革、促发展","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3f3ffa4c93024fcd":{"review":{"definition":"习近平在2017年视察海军机关时指出，建设强大的现代化海军是建设世界一流军队的重要标志，也是建设海洋强国的战略支撑。","explanation":"“战略支撑”明确了现代化海军在海洋强国建设中的地位。D项保留了“建设世界一流军队的重要标志”的表述，却把“战略支撑”改成“唯一支撑”。A项也明确指出发达的海洋经济是重要支撑，因此本题选D。","references":[],"evidence":"是建设海洋强国的战略支撑","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8f6d28a0bb449b34":{"review":{"definition":"习近平在2013年主持研究建设海洋强国的中央政治局集体学习时指出，发达的海洋经济是建设海洋强国的重要支撑。","explanation":"讲话提出提高海洋开发能力、扩大海洋开发领域，让海洋经济成为新的增长点。A项所用的“重要支撑”符合这一定位，也说明海洋强国建设有多方面支撑，D项把现代化海军称为“唯一支撑”有误。","references":[],"evidence":"发达的海洋经济是建设海洋强国的重要支撑","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-212f4f35ce3e909e":{"review":{"definition":"习近平在2024年听取海南省委和省政府工作汇报后提出，海南要坚持陆海统筹、山海联动、资源融通，抓好海洋开发，建设海洋强省。","explanation":"讲话把统筹陆地与海洋、推动山区与沿海地区联动、促进资源融通同培育海洋经济增长点联系起来。B项保留了这三项要求及“向海洋要生产力、求新增长点”的目标，符合题中所引讲话。","references":[],"evidence":"坚持陆海统筹、山海联动、资源融通","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8fa1518453a1a10a":{"review":{"definition":"习近平在2013年主持研究建设海洋强国的中央政治局集体学习时提出，要把海洋生态文明建设纳入海洋开发总布局，科学合理开发利用海洋资源。","explanation":"把生态文明建设纳入总布局，具体体现为开发和保护并重、污染防治和生态修复并举，目的是维护海洋自然再生产能力。C项把生态文明建设与资源开发利用放在同一布局中，符合讲话要求。","references":[],"evidence":"要把海洋生态文明建设纳入海洋开发总布局之中","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3dc1d8fb7e0b8bf8":{"review":{"definition":"习近平在《朝着建成科技强国的宏伟目标奋勇前进》中指出，必须充分认识科技的战略先导地位和根本支撑作用。科技现代化支撑中国式现代化，科技创新为高质量发展培育新动能。","explanation":"文章据此提出锚定2035年建成科技强国的战略目标，加强顶层设计和统筹谋划。A项沿用了原文对科技地位和作用的判断，符合文章表述。","references":[],"evidence":"必须充分认识科技的战略先导地位和根本支撑作用","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-34526f421cea6390":{"review":{"definition":"习近平在《朝着建成科技强国的宏伟目标奋勇前进》中提出，要深入践行国际科技合作倡议，积极融入全球创新网络。","explanation":"文章把国际科技合作纳入建设科技强国的部署。B项同时保留了“践行国际科技合作倡议”和“融入全球创新网络”两项要求。文章也提出加快推进高水平科技自立自强，并把发挥“新型举国体制”优势列为相应举措，C项将其换成了“传统举国体制”。","references":[],"evidence":"深入践行国际科技合作倡议，积极融入全球创新网络","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-360180bb9549ef86":{"review":{"definition":"习近平在《朝着建成科技强国的宏伟目标奋勇前进》中提出，要坚持以科技创新需求为牵引，突出加强青年科技人才培养。","explanation":"文章以科技创新需求指引科技人才培养，把加快建设国家战略人才力量作为重中之重，并把青年科技人才列为重点培养对象。D项概括了这一部署中的需求导向和培养重点，符合文章表述。","references":[],"evidence":"坚持以科技创新需求为牵引，突出加强青年科技人才培养","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e914c8dec1bd977f":{"review":{"definition":"习近平在2015年主持召开中央全面深化改革领导小组第十六次会议时指出，改革和开放相辅相成、相互促进，改革必然要求开放，开放也必然要求改革。","explanation":"讲话以我国以开放促改革、促发展的成功实践说明开放对改革的推动作用，同时指出改革也要求开放。第21题②完整保留了这两个方向，与同样正确的①组成B项。","references":[],"evidence":"改革和开放相辅相成、相互促进，改革必然要求开放，开放也必然要求改革","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2ea2771de8e2be27":{"review":{"definition":"习近平在2023年二十届中央政治局第十次集体学习时指出，法治是最好的营商环境，涉外法治建设要跟上对外开放的步伐。","explanation":"讲话把公开透明的涉外法律规则、知识产权保护和外资企业合法权益保障作为营造一流营商环境的具体支撑。第21题③保留了“市场化、法治化、国际化”的目标，却把“法治是最好的营商环境”改成了“改革开放是最好的营商环境”，因此③错误。","references":[],"evidence":"法治是最好的营商环境","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-42292c7e2f346d14":{"review":{"definition":"求是网《如何进一步激发做强国内大循环的动力活力》提出，在文章讨论的外部冲击下，外贸企业首当其冲，应精准有效帮扶外贸企业，帮助其解决实际困难。","explanation":"文章在说明企业是经济活力的基础后，把当前帮扶对象具体指向外贸企业。第26题A将受冲击和帮扶的对象都换成了“小微企业”，与文章表述不符。题干要求选错误项，因此选A。","references":[],"evidence":"外部冲击下外贸企业首当其冲，要精准有效帮扶外","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-321e778afde7b8d8":{"review":{"definition":"求是网《如何进一步激发做强国内大循环的动力活力》认为，就业事关经济稳定和社会安定，应支持企业稳岗，扩大各领域特别是服务业就业。","explanation":"支持企业稳岗着眼于稳住现有岗位，扩大各领域就业着眼于增加就业机会。文章点出服务业，并提出突出解决高校毕业生、农民工等群体的就业问题。第26题B与文章的稳就业部署一致，选非时应排除。","references":[],"evidence":"支持企业稳岗，扩大各领域特别是服务业就业","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e1ccdf6b39e1ca7f":{"review":{"definition":"求是网《如何进一步激发做强国内大循环的动力活力》提出，针对供需结构错配，要完善扩大消费长效机制，形成市场主导的有效投资内生增长机制。","explanation":"两项举措分别着眼于持续扩大消费和促进有效投资，共同服务于培育完整内需体系。文章还提出以自主可控、高质量的供给满足现有需求、创造引领新的需求。第26题C准确保留了消费和投资两项举措，选非时应排除。","references":[],"evidence":"形成市场主导的有效投资内生增长机制，加快培育完整内需体系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bf8075abdddcd377":{"review":{"definition":"习近平总书记2025年在河南考察时指出，制造业是国民经济的重要支柱，推进中国式现代化必须保持制造业合理比重。","explanation":"制造业在国民经济中的支柱地位，是保持其合理比重的依据。讲话还提出，现代制造业离不开科技赋能，要加强技术攻关、走自主创新的发展路子。第28题④准确对应了支柱地位和保持合理比重这层关系。","references":[],"evidence":"制造业是国民经济的重要支柱，推进中国式现代化必须保持制造业合理比重","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2c6db5aa7569d12a":{"review":{"definition":"习近平在2025年3月28日会见国际工商界代表时，将中国长期保持政局稳定、社会安定列为外资企业来华投资兴业的有利条件，并称中国是世界公认的最安全国家之一。","explanation":"讲话用政局稳定和社会安定说明外商来华投资以及在华工作、生活的安全环境。④复述了讲话的表述，与同样正确的①组成B项。","references":[],"evidence":"中国长期保持政局稳定、社会安定","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-6502eef7382b8c03":{"review":{"definition":"习近平在二十届中央政治局第二十次集体学习时提出，要以人工智能推动科学研究方式变革，加速各领域科技创新突破。","explanation":"讲话把加强基础研究、攻克高端芯片和基础软件等核心技术、构建自主可控的人工智能基础软硬件系统，与发挥人工智能对科研的引领作用一并部署。题中①保留了以人工智能推动科研方式变革、加速科技创新突破的表述，应计入正确项。","references":[],"evidence":"以人工智能引领科研范式变革，加速各领域科技创新突破","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f0370a94504e52ff":{"review":{"definition":"习近平在河南考察时指出，现代制造业要依靠科技赋能，通过加强技术攻关，把关键核心技术掌握在自己手中，走自主创新的发展路子。","explanation":"材料将掌握关键核心技术作为推动制造业高质量发展的支撑。题中②把科技赋能、技术攻关和自主创新落到现代制造业这一具体领域，符合讲话要求，应计入正确项。","references":[],"evidence":"现代制造业离不开科技赋能，要大力加强技术攻关，走自主创新的发展路子","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-efd4f4c5d2684f07":{"review":{"definition":"习近平在《朝着建成科技强国的宏伟目标奋勇前进》中指出，科技创新和产业创新深度融合的基础是增加高质量科技供给，关键是强化企业科技创新主体地位，途径是促进科技成果转化应用。","explanation":"三项分别说明融合需要怎样的科技供给、应强化谁的主体地位，以及科技成果怎样进入产业应用。题中③把属于途径的成果转化应用填到“关键”的位置，因此错误。","references":[],"evidence":"融合的途径是促进科技成果转化应用","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9eee624cb5addd30":{"review":{"definition":"习近平在全国政协十四届三次会议有关界别委员联组会上指出，为实现科技自主创新和人才自主培养良性互动，教育要进一步发挥先导性、基础性支撑作用。","explanation":"这项要求把教育放在支撑自主培养人才和科技自主创新相互促进的位置，强调人才培养对创新的基础支撑。题中④将承担这一作用的主体由“教育”换成“科技”，因此错误。","references":[],"evidence":"教育要进一步发挥先导性、基础性支撑作用","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ff3a3a6fc272c1b3":{"review":{"definition":"习近平在新时代推动西部大开发座谈会上提出，要坚持以大开放促进大开发，提高西部地区对内对外开放水平。","explanation":"讲话以推进西部陆海新通道建设、带动沿线地区开发开放、深度融入共建“一带一路”为具体举措。A项写成“以大开发促进大开放”，颠倒了讲话中开放带动开发的方向，因此是本题应选的错误项。","references":[],"evidence":"要坚持以大开放促进大开发，提高西部地区对内对外开放水平","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-462149626c4782a6":{"review":{"definition":"习近平在二十届中央政治局第十次集体学习时提出，要对标国际先进水平，把自由贸易试验区等高水平对外开放的有效举措和成熟经验及时上升为法律。","explanation":"讲话提出把开放实践中已经有效、成熟的做法上升为法律，以打造开放层次更高、营商环境更优、辐射作用更强的对外开放新高地。C项保留了“有效举措和成熟经验”以及“及时上升为法律”的要求，选非时应排除。","references":[],"evidence":"把自由贸易试验区等高水平对外开放的有效举措和成\n\n熟经验及时上升为法律","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-de1dc123a6c275d0":{"review":{"definition":"习近平在省部级主要领导干部学习贯彻党的十九届五中全会精神专题研讨班上指出，构建新发展格局、实行高水平对外开放，必须具备强大的国内经济循环体系和稳固的基本盘。","explanation":"讲话指出，国内经济循环和稳固的基本盘能够增强对全球要素资源的吸引力、国际竞争力和全球资源配置中的推动力。D项用“必须具备”准确表述了这两项国内条件，选非时应排除。","references":[],"evidence":"必须具备强大的国内经济循环体系和稳固的基本盘","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b50e99a74832ba6d":{"review":{"definition":"习近平在2025年4月30日召开的部分省区市“十五五”时期经济社会发展座谈会上提出，要前瞻性把握国际形势发展变化对我国的影响，因势利导对经济布局进行调整优化。","explanation":"讲话将研判国际形势对我国的影响作为调整经济布局的依据。B项同时保留了“前瞻性把握”和“因势利导”两层要求，符合讲话内容，在本题中应排除。","references":[],"evidence":"前瞻性把握国际形势发展变化对我国的影响，因势利导对经济布局进行调整优化","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-550df2ebbc9b86bc":{"review":{"definition":"习近平在2025年4月30日召开的部分省区市“十五五”时期经济社会发展座谈会上提出，各地区要在全国大局中精准定位、加强规划衔接，并在确定发展思路和战略举措时体现自身特色、发挥比较优势。","explanation":"全国大局为地方规划提供定位，深入调查研究为各地区结合自身条件确定发展思路和战略举措提供依据。D项准确转述了讲话对调查研究、体现特色和发挥比较优势的要求，因此在选非题中排除。","references":[],"evidence":"在确定发展思路\n\n和战略举措时注重体现自身特色、发挥比较优势","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cd27115c75d73688":{"review":{"title":"统筹发展和安全","type":"观点与论证","definition":"统筹发展和安全，是指在谋划和推进发展时兼顾风险防范和安全保障，使高质量发展与高水平安全相互促进。","explanation":"2025年4月30日关于谋划“十五五”的座谈会要求通盘考虑内外部风险挑战，健全国家安全体系、增强维护安全能力，以高效能治理促进发展和安全良性互动。2024年4月23日新时代推动西部大开发座谈会把这一要求落实到提升能源资源等重点领域的安全保障能力。","basis":"据关联原题及所列出处编释。","references":[{"source":"run","location":"统筹发展和安全"}],"examFocus":{"政治理论必刷100题#50":"根据谋划“十五五”时期经济社会发展的座谈会讲话，区分发展与安全的关系、价值取向、战略重点和产业布局。","国考 2025 行政执法 行测#20":"对照新时代西部大开发的部署，核对产业转型、对内对外开放、安全保障和城乡融合的要求。"}},"aspects":[{"title":"“十五五”谋划中的高效能治理","uses":[{"unit":"Q1","role":"直接考查","use":"本题为选非题。A项所述高效能治理要求符合座谈会讲话。C项误将应摆在更加突出战略位置的“因地制宜发展新质生产力”表述为“推动高质量发展”，故选C。","evidence":"要更加注重统筹发展和安全，以高效能治理促进高质量发展和高水平安全良性互动","qids":["政治理论必刷100题#50"]}]},{"title":"西部大开发中的能源资源安全","uses":[{"unit":"Q2","role":"直接考查","use":"本题为选非题。C项所述重点领域安全保障要求表述正确。西部地区产业转型升级应以发展特色优势产业为主攻方向，A项将主攻方向写成全面发展新兴产业，故选A。","evidence":"要坚持统筹发展和安全，提升能源资源等重点领域安全保障能力","qids":["国考 2025 行政执法 行测#20"]}]}],"sources":[{"id":"9317b72d8b159e70","label":"统筹发展和安全","topic":"党政制度与理论","category":"非时政","text":"2.统筹发展和安全\n“坚持统筹发展和安全”，是党的二十届四中全会提出“十五五”时期我国经济社\n会发展必须遵循的六条原则之一，凸显新形势下将安全发展贯穿国家发展各领域、全过程\n的重要性、迫切性。\n发展和安全犹如一体之两翼、驱动之双轮，相辅相成、互为条件，任何时候都不能偏\n废。一方面，发展是解决我国一切问题的基础和关键，不发展是最大的不安全；另一方面，\n安全是发展的前提，没有高水平安全就没有高质量发展。筑牢治国安邦的根基、增强攻坚\n克难的底气，发展是硬道理，安全也是硬道理。","source":{"doc":"41195a191a57c1c36332","first":22,"last":22,"page":22,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-3fa2d4cacc6129bc":{"review":{"definition":"习近平总书记在2025年4月30日召开的部分省区市“十五五”时期经济社会发展座谈会上提出，谋划“十五五”时期经济社会发展，要把造福人民作为根本价值取向。","explanation":"讲话从中国式现代化是全体人民共同富裕的社会主义现代化出发，把造福人民落实为在发展中保障和改善民生、稳步推动共同富裕。B项准确表述了这一价值取向，因此本题要求选出不正确的表述时，B项应排除。","references":[],"evidence":"把造福人民作为根本价值取向","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4c3f651ed30d4662":{"review":{"definition":"习近平在《进一步全面深化改革中的几个重大理论和实践问题》中指出，改革是利益格局调整的过程，不可能同时满足所有人的利益诉求。","explanation":"改革会改变不同群体之间的利益关系，各方诉求可能彼此冲突。A项把文章对改革现实约束的判断改成了“应力争同时满足所有人的利益诉求”，因此是本题要求选出的错误表述。","references":[],"evidence":"改革是利益格局调整的过程，不可能同时满足所有人","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f4204304ba934d04":{"review":{"definition":"习近平在《进一步全面深化改革中的几个重大理论和实践问题》中提出，改革要坚持以人为本，以实绩实效和人民群众满意度检验改革。","explanation":"实绩实效看改革取得了什么实际成效，人民群众满意度看群众如何评价这些成效。文章把两方面的检验同增强群众的获得感、幸福感、安全感联系起来。B项保留了两方面标准，属于正确表述。","references":[],"evidence":"坚持以人为本，以实绩实效和人民群众满意度检验改革","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9bf29c07d7ac740f":{"review":{"definition":"中共中央统战部在《画好团结奋斗的最大同心圆》中指出，团结奋斗是中国共产党和中国人民最显著的精神标识。","explanation":"文章以中国共产党百余年来领导人民团结拼搏的奋斗史为依据，把团结奋斗概括为贯穿这一历程的精神特征。第53题①沿用了这一判断，其中“最显著”的表述与文章一致，计入正确项。","references":[],"evidence":"团结奋斗是中国共产党和中国人民最显著的精神标识","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-fd799f951e5f2260":{"review":{"definition":"中共中央统战部在《画好团结奋斗的最大同心圆》中指出，党的领导是统一战线团结人、凝聚人的根本保证。","explanation":"文章从统一战线是党领导的统一战线出发，说明党的领导为团结各方面力量提供政治保证。第53题②将“根本保证”对应到党的领导，③则将“思想基础”对应到深化党的创新理论武装，两项分别符合文章表述。","references":[],"evidence":"党的领导是统一战线团结人凝聚人的根本保证","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-748d71754df565c8":{"review":{"definition":"中共中央统战部在《画好团结奋斗的最大同心圆》中提出，把深化党的创新理论武装作为团结奋斗的思想基础。","explanation":"文章把这一要求具体落实到用习近平新时代中国特色社会主义思想统一意志和行动，说明理论武装如何为共同奋斗提供思想基础。第53题③保留了“深化党的创新理论武装”与“思想基础”的对应关系，计入正确项。","references":[],"evidence":"把深化党的创新理论武装作为团结奋斗的思想基础","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-84406bbb9cb88354":{"review":{"definition":"“团结—批评—团结”是从团结的愿望出发，通过批评解决分歧、纠正错误，并在此基础上增进团结的做法。","explanation":"中共中央统战部在《画好团结奋斗的最大同心圆》中把发扬这一传统与统一团结和斗争联系起来，要求在凝聚人心的同时，在大是大非的原则问题上立场坚定，对破坏团结统一的错误言行开展斗争。第53题④同时保留了这两层要求，计入正确项。","references":[],"evidence":"把团结和斗争统一起来，发扬“团结—批评—团结”的优良传统","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e7232480a573137c":{"review":{"definition":"中共中央统战部在《画好团结奋斗的最大同心圆》中指出，统一战线是团结海内外全体中华儿女实现中华民族伟大复兴的重要法宝。","explanation":"文章把促进中华儿女大团结作为新征程上统一战线承担的历史责任，说明统一战线通过团结海内外力量为民族复兴汇聚合力。第53题⑤中的团结对象和奋斗目标均与文章一致，计入正确项。","references":[],"evidence":"统一战线是团结海内外全体中华儿女实现中华民族伟大复兴的重要法宝","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-677ff089a4d50bd2":{"review":{"definition":"习近平在《以中国式现代化全面推进强国建设、民族复兴伟业》中指出，中国式现代化深深植根于中华优秀传统文化，体现科学社会主义的先进本质。","explanation":"“植根于”说明中国式现代化的文化根基，“体现”说明其社会主义属性。文章还指出，中国式现代化借鉴吸收一切人类优秀文明成果。A项准确概括了文化根基和社会主义属性，在本题选非时应排除。","references":[],"evidence":"中国式现代化深深植根于中华优秀传统文化，体现科学社会主义的先进本质","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-07dbbc0396f95575":{"review":{"definition":"习近平在《以中国式现代化全面推进强国建设、民族复兴伟业》中指出，中国式现代化是一种全新的人类文明形态，是对西方式现代化理论和实践的重大超越。","explanation":"文章以中国式现代化蕴含的独特世界观、价值观、历史观、文明观、民主观、生态观及其伟大实践说明，这条道路展现了不同于西方现代化模式的新图景。B项同时保留了“全新的人类文明形态”和“对西方式现代化理论和实践的重大超越”两层判断，在本题选非时应排除。","references":[{"source":"web-d2198cd0cbd7c53d","location":"关于中国式现代化文明意义的论述","quote":"是一种全新的人类文明形态"},{"source":"web-965a7dae4e52348f","location":"标题","quote":"中国式现代化创造了人类文明新形态"}],"evidence":"中国式现代化是一种全新的人类文明形态，是对西方式现代化理论和实践的重大超越","disposition":"独立词条","basis":"据原题和解析编释。","title":"中国式现代化与人类文明新形态","related":[],"examFocus":{"政治理论必刷100题#55":"辨析中国式现代化的文化根基、理论属性、文明意义、与民族复兴的关系及其对其他国家的借鉴意义。","江苏 2024 A类 行测#1":"结合各国现代化的共同特征和中国国情，逐条辨析有关现代化任务、推进难度、发展道路和文明形态的表述。"}},"readings":[{"origin":"k-07dbbc0396f95575","title":"中国式现代化与人类文明新形态","qs":["政治理论必刷100题#55"],"definition":"习近平在《以中国式现代化全面推进强国建设、民族复兴伟业》中指出，中国式现代化是一种全新的人类文明形态，是对西方式现代化理论和实践的重大超越。","explanation":"文章以中国式现代化蕴含的独特世界观、价值观、历史观、文明观、民主观、生态观及其伟大实践说明，这条道路展现了不同于西方现代化模式的新图景。B项同时保留了“全新的人类文明形态”和“对西方式现代化理论和实践的重大超越”两层判断，在本题选非时应排除。","evidence":"中国式现代化是一种全新的人类文明形态，是对西方式现代化理论和实践的重大超越","doubt":"","references":[]},{"origin":"k-9780b3e9021223ab","title":"中国式现代化与人类文明新形态","qs":["江苏 2024 B类 行测#1"],"definition":"党的二十大报告把创造人类文明新形态列为中国式现代化的本质要求之一。习近平在2023年2月7日的讲话中指出，中国式现代化是一种全新的人类文明形态。","explanation":"二十大报告写的是本质要求。题中④用“创造了”表述实践成果，2023年研讨班讲话对中国式现代化的文明形态作了明确判断，同期《人民日报》评论员文章也直接使用了“中国式现代化创造了人类文明新形态”的表述。因此④可以纳入正确组合。","evidence":"创造了一种全新的人类文明形态","doubt":"","references":[{"source":"web-d2198cd0cbd7c53d","location":"关于中国式现代化文明意义的论述","quote":"是一种全新的人类文明形态"},{"source":"web-965a7dae4e52348f","location":"标题","quote":"中国式现代化创造了人类文明新形态"}]},{"origin":"k-9d9c8edd23b40aa9","title":"中国式现代化与人类文明新形态","qs":["江苏 2024 A类 行测#1"],"definition":"党的二十大报告把“创造人类文明新形态”列为中国式现代化的本质要求之一。","explanation":"题干同时问中国式现代化的内涵和意义，④的“创造了一种全新的人类文明形态”对应报告中的这一表述，体现其文明意义。记忆报告原文时可采用“创造人类文明新形态”。","evidence":"推动构建人类命运共同体，创造人类文明新形态。","doubt":"","references":[]}]},"k-1654a31f6370d6b4":{"review":{"title":"中国式现代化与民族复兴","type":"观点与论证","definition":"党的二十大报告把以中国式现代化全面推进中华民族伟大复兴列入新时代新征程中国共产党的中心任务。中华民族伟大复兴是目标，中国式现代化是推进这一目标的道路。","explanation":"2025年第1期《求是》刊载的《以中国式现代化全面推进强国建设、民族复兴伟业》把中国式现代化阐释为中国自主选择发展道路、回答民族复兴历史课题的实践。文章指出，中国式现代化为广大发展中国家独立自主迈向现代化树立了典范。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"新时代新征程中国共产党的使命任务"}],"related":["k-fb1ce1e7a6289679"],"examFocus":{"政治理论必刷100题#55":"区分中国式现代化的文化根基、历史使命与对其他国家的借鉴意义。","政治理论必刷100题#56":"区分各项表述谈的是党的建设要求、政党特征，还是新时代的政治任务。"}},"aspects":[{"title":"自主选择道路与国际借鉴","uses":[{"unit":"Q1","role":"直接考查","use":"本题为选非题。C项符合文章对中国式现代化与民族复兴关系的阐释。文章谈的是发展中国家自主借鉴，D项写成中国积极输出模式并作出必然造福的判断，故选D。","evidence":"实现民族复兴这个重大历史课题所给出的答案，是选择自己的道路、做自己的事情。","qids":["政治理论必刷100题#55"]}]},{"title":"新时代最大的政治","uses":[{"unit":"Q2","role":"解题依据","use":"本题为选非题。2023年12月29日全国政协新年茶话会讲话把以中国式现代化全面推进强国建设、民族复兴伟业称为新时代最大的政治，D项将这一定位套用于巩固和发展爱国统一战线，故选D。","evidence":"以中国式现代化全面推进强国建设、民族复兴伟业，是新时代新征程党和国家的中\n\n心任务，是新时代最大的政治。","qids":["政治理论必刷100题#56"]}]}],"sources":[{"id":"a527cafd4023765d","label":"以中国式现代化全面推进中华民族伟大复兴","topic":"党政制度与理论","category":"非时政","text":"2.以中国式现代化全面推进中华民族伟大复兴\n党的二十大报告明确提出，新时代新征程中国共产党的中心任务就是“团结带领全\n国各族人民全面建成社会主义现代化强国、实现第二个百年奋斗目标，以中国式现代化全\n面推进中华民族伟大复兴”。","source":{"doc":"41195a191a57c1c36332","first":23,"last":23,"page":23,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-ffae7f6fdc4683e5":{"review":{"definition":"习近平在《以中国式现代化全面推进强国建设、民族复兴伟业》中指出，中国式现代化为广大发展中国家独立自主迈向现代化树立了典范，必然会为一些发展中国家所借鉴。","explanation":"文章认为，中国式现代化的初步成功实践和显著成就让面临道路选择的发展中国家看到了新的选择。原文说中国“无意也没有输出”自身模式，“必然”所指的是一些发展中国家会借鉴。D项用“积极输出”和“必然会造福”改换了行动主体和结果，因此是选非题的答案。","references":[],"evidence":"自主迈向现代化树立了典范，必然会为一些发展中国家所借鉴","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-526664b140c06248":{"review":{"definition":"《人民日报》2024年2月22日刊发的《加强党的政治建设 推动全面从严治党向纵深发展》指出，政治上的先进性是马克思主义政党区别于其他政党的一个显著特征。","explanation":"文章把政治上的先进性同加强党的政治建设联系起来，具体目标包括坚定政治信仰、强化政治领导、提高政治能力、净化政治生态，最终实现全党团结统一、行动一致。B项准确表述了政党的显著特征，在本题选非时应排除。","references":[],"evidence":"政治上的先进性，是马克思主义政党区别于其他政党的一个显著特征","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cb8a75e17fe6c2b4":{"review":{"definition":"《光明日报》2022年10月12日刊发的《新时代党的政治建设取得重大历史性成就》指出，旗帜鲜明讲政治是中国共产党的政治优势，也是党永葆生机活力的根本保证。","explanation":"文章把讲政治同培养自我革命勇气、增强自我净化能力联系起来，说明了它对保持党的生机活力的作用。C项同时准确表述了“政治优势”和“永葆生机活力的根本保证”，在本题选非时应排除。","references":[],"evidence":"旗帜鲜明讲政治是我们党的政治优势、是我们党永葆生机活力的根本保证","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bc6fe8ff593a50fa":{"review":{"definition":"2025年中央周边工作会议提出，以睦邻、安邻、富邻、亲诚惠容、命运与共为周边工作的理念方针。","explanation":"会议在统筹国内国际两个大局、发展安全两件大事的总体部署中，把这一组表述定位为“理念方针”。B项的内容与定位均与会议部署一致，是本题正确选项。","references":[],"evidence":"以睦邻、安邻、富邻、亲诚惠容、命运与共为理念方针","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8167806ac7f256dc":{"review":{"definition":"2025年中央周边工作会议提出，以建设和平、安宁、繁荣、美丽、友好“五大家园”为周边工作的共同愿景。","explanation":"“五大家园”描述我国与周边国家共同建设所要达到的目标。D项把“共同愿景”配给了高质量共建“一带一路”，而会议将其定位为推进周边合作的主要平台，因此D项错误。","references":[],"evidence":"以建设和平、安宁、繁荣、美丽、友好“五大家园”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-264d3ff2a3543720":{"review":{"definition":"2025年中央周边工作会议提出，以和平、合作、开放、包容的亚洲价值观为周边工作的基本遵循。","explanation":"“基本遵循”对应开展周边工作所秉持的亚洲价值观。A项将这一定位配给了安危与共、求同存异、对话协商的亚洲安全模式，该模式在会议部署中的定位是战略支撑，因此A项错误。","references":[],"evidence":"包容的亚洲价值观为基本遵循","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b11f5757baa9e36c":{"review":{"definition":"2025年中央周边工作会议提出，以高质量共建“一带一路”为周边工作的主要平台。","explanation":"“主要平台”指开展周边合作的依托，建设和平、安宁、繁荣、美丽、友好“五大家园”则是合作所指向的共同愿景。D项将高质量共建“一带一路”归入“共同愿景”，错在政策定位。","references":[],"evidence":"以高质量共建“一带一路”为主要平台","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-399c221745f3140a":{"review":{"definition":"2025年中央周边工作会议提出，以安危与共、求同存异、对话协商的亚洲安全模式为周边工作的战略支撑。","explanation":"这三项表述说明了周边安全合作如何处理共同安全和彼此分歧。A项把亚洲安全模式列为基本遵循，C项把统筹国内国际两个大局列为战略支撑。会议将亚洲价值观定位为基本遵循，将统筹国内国际两个大局列入总体部署，因此A、C两项均错误。","references":[],"evidence":"存异、对话协商的亚洲安全模式为战略支撑","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d99d03e079c229cd":{"review":{"definition":"习近平总书记在中共中央政治局第十七次集体学习时强调，文化建设要始终着眼于人、落脚于人，把满足人民群众的精神文化需求、增强人民群众的文化获得感和幸福感作为工作取向。","explanation":"这一要求体现在提升文化服务和文化产品供给能力，以满足群众多样化、多层次、多方面的精神文化需求。B项把着眼点和落脚点都换成了经济发展，改变了原表述，因此是本题选出的错误项。","references":[],"evidence":"文化建设着眼于人、落脚于人","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b7327d285ec6ad13":{"review":{"definition":"党的二十届三中全会通过的《中共中央关于进一步全面深化改革、推进中国式现代化的决定》把激发全民族文化创新创造活力列为深化文化体制机制改革的要求。","explanation":"《决定》以物质文明和精神文明相协调为背景，将这项要求与增强文化自信、发展社会主义先进文化、传承中华优秀传统文化和培育优秀文化人才队伍等部署一同提出。A项准确概括了这一改革要求，在选非题中应排除。","references":[],"evidence":"深化文化体制机制改革要激发全民族文化创新创造活力","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-546fac34f2e6a836":{"review":{"definition":"党的二十大报告提出，加强国际传播能力建设，全面提升国际传播效能，形成同我国综合国力和国际地位相匹配的国际话语权。","explanation":"这项部署属于增强中华文明传播力影响力的安排。C项保留了加强国际传播能力建设的举措，以及国际话语权应与我国综合国力和国际地位相匹配的目标，表述正确。","references":[],"evidence":"加强国际传播能力建设，形成同我国综合国力和国际地位相匹配的国际话语权","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-d40d09c540a4554b":{"review":{"definition":"习近平总书记在中共中央政治局第十七次集体学习时提出，要在创造性转化和创新性发展中赓续中华文脉，挖掘和阐发中华优秀传统文化的精神内涵，并赋予其中的优秀因子新的时代内涵。","explanation":"讲话把呵护、弘扬和发展中华文明瑰宝同发展新时代中国特色社会主义文化联系起来，并提出用马克思主义激活中华传统文化中的优秀因子。D项保留了创造性转化和创新性发展这两项要求，表述正确。","references":[],"evidence":"在创造性转化和创新性发展中赓续中华文脉","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b8287c6e4e5e6952":{"review":{"definition":"新闻舆论工作具有鲜明的意识形态属性，坚持正确的政治方向是做好新闻舆论工作的第一位要求。党性原则是党的新闻舆论工作的根本原则。","explanation":"本题用“第一位要求”来判断C项。C项将这一位置赋予“调动人民群众的积极性”，与解析明确指出的“坚持正确的政治方向”不符，因此是本题选出的错误项。","references":[],"evidence":"坚持正确的政治方向是做好新闻舆论\n\n工作的第一位要求","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2cb4d6b25892af6b":{"review":{"definition":"党的二十大报告指出，意识形态工作是为国家立心、为民族立魂的工作，并提出牢牢掌握党对意识形态工作的领导权，巩固壮大新时代主流思想舆论。","explanation":"A项的“为国家立心、为民族立魂”概括意识形态工作的作用。报告还列出全面落实意识形态工作责任制等具体要求，A项准确复述了其中的作用定位，在选非题中应排除。","references":[],"evidence":"意识形态工作是为国家立心、为民族立魂的工作","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-84e7d2fd808616ac":{"review":{"definition":"习近平总书记在2022年5月27日中共十九届中央政治局第三十九次集体学习时指出，中华优秀传统文化是中华文明的智慧结晶和精华所在，是中华民族的根和魂。","explanation":"讲话还将中华优秀传统文化称为我们在世界文化激荡中站稳脚跟的根基。B项同时准确复述了讲话对其在中华文明中的地位和对中华民族的意义的概括，表述正确。","references":[],"evidence":"中华优秀传统文化是中华文明的智慧结晶和精华所在，是中华民族的根和魂","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-79b625cb0327b9f8":{"review":{"definition":"习近平总书记在2018年4月20日全国网络安全和信息化工作会议上指出，互联网日益成为意识形态斗争的主阵地、主战场、最前沿。","explanation":"讲话从信息跨国界流通谈到网上阵地，强调能否牢牢掌握意识形态工作领导权，关键要看能否占领网上阵地、赢得网上主导权。D项保留了“日益成为”和三个阵地定位用语，表述正确。","references":[],"evidence":"互联网日益成为意识形态斗争的主阵地、主战场、最前沿","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7244092500c056a9":{"review":{"definition":"习近平指出，团结奋斗要靠目标凝心聚力。新征程上，要靠中国式现代化进一步凝心聚力、团结奋斗。","explanation":"中国式现代化在这段论述中是凝聚力量的共同目标。B项将这一目标替换为“马克思主义”，与解析所引讲话不符，因此是本题要求选出的不正确项。","references":[],"evidence":"团结奋斗要靠目标凝心聚力","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-466e66e213486cfd":{"review":{"definition":"习近平在2022年春节团拜会上指出，能团结奋斗的民族才有前途，能团结奋斗的政党才能立于不败之地。","explanation":"讲话以百年奋斗史为依据，用两个“才”强调团结奋斗的必要性。“有前途”对应民族，“立于不败之地”对应政党。A项保留了这两层对应关系，属于正确表述。","references":[],"evidence":"能团结奋斗的民族才有前途，能团结奋斗的政党才能立于不败之地","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f3d1d670216db872":{"review":{"definition":"习近平在2022年春节团拜会上指出，党和人民靠团结奋斗创造了辉煌历史，还要靠团结奋斗开辟美好未来。","explanation":"讲话以党和人民百年来取得的成就说明团结奋斗的历史作用，并据此提出面向未来仍要团结奋斗。C项同时保留了对历史成就的总结和对未来的要求，属于正确表述。","references":[],"evidence":"我们靠团结奋斗创造了辉煌历史，还要靠团结奋斗开辟美好未来","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a3e46e7df98813af":{"review":{"definition":"习近平在党的十九届六中全会第二次全体会议上指出，开展新的伟大斗争，要把握其历史特点，发扬斗争精神，把握斗争方向和主动权，坚定斗争意志，掌握斗争规律，增强斗争本领。","explanation":"这些要求服务于应对重大挑战、抵御重大风险、克服重大阻力和解决重大矛盾。D项列出的精神、方向、规律和本领均见于解析所引讲话，属于正确表述。","references":[],"evidence":"必须发扬斗争精神，把握斗争方向，掌握斗争规律，增强斗争本领","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-baf5042153f805c5":{"review":{"definition":"习近平在2013年12月30日主持十八届中央政治局第十二次集体学习时指出，中华文化是提高国家文化软实力最深厚的源泉，也是提高国家文化软实力的重要途径。","explanation":"中共中央党史和文献研究院编选的讲话节录中，“最深厚的源泉”和“重要途径”共用“中华文化”这一主语。随后讲话提出弘扬具有当代价值的文化精神、传播当代中国文化创新成果，具体说明怎样发挥这一作用。第61题C项把主语换成“马克思主义”，所以是选非题的答案。","references":[{"source":"web-f02678b804e287b1","location":"2013年12月30日十八届中央政治局第十二次集体学习讲话节录","quote":"中华文化是我们提高国家文化软实力最深厚的源泉，是我们提高国家文化软实力的重要途径"}],"evidence":"中华文化是我们提高国家文化软实力最深厚的源泉","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-481a781c59dda820":{"review":{"definition":"习近平在《加快建设文化强国》中提出，把育人才、建队伍作为重要而紧迫的战略任务，统筹各类人才培养。","explanation":"文章以“文化创造核心在人”说明人才队伍建设的战略地位。A项既写明任务的紧迫性，也列出了高水平文化人才队伍应具备的规模宏大、结构合理、锐意创新三项特点，属于正确表述。","references":[],"evidence":"把育人才、建队伍作为重要而紧迫的战略任务","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-27898b69aaacf74c":{"review":{"definition":"习近平在中共中央政治局第十七次集体学习时提出，高扬中华民族的文化主体性，把中华文明瑰宝呵护好、弘扬好、发展好。","explanation":"讲话把对中华文明瑰宝的呵护、弘扬和发展放在赓续中华文脉的要求之中，强调创造性转化和创新性发展。B项保留了对待文明瑰宝的三项要求，属于正确表述。","references":[],"evidence":"高扬中华民族的文化主体性，把历经沧桑留下的中华文明瑰宝呵护好、弘扬好、发展\n\n好","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-71cc41cc86c100ca":{"review":{"definition":"习近平在对文物工作作出的重要指示中指出，文物承载灿烂文明，传承历史文化，维系民族精神，是加强社会主义精神文明建设的深厚滋养。","explanation":"文物作为留存下来的文化遗产，使历史文化得以传承，并为维系民族精神提供载体。D项同时列出了文物的这些作用和它对精神文明建设的意义，属于正确表述。","references":[],"evidence":"是加强社会主义精神文明建设的深厚滋养","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-dd039e3fc1a6a4fa":{"review":{"definition":"习近平在十二届全国人大一次会议上指出，爱国主义是民族精神的核心，始终是把中华民族坚强团结在一起的精神力量。","explanation":"讲话从实现中国梦需要弘扬中国精神谈起，把凝聚中华民族的作用与爱国主义相联系，把推动改革开放中与时俱进的作用与改革创新相联系。第62题A项准确表述了爱国主义的凝聚作用，符合讲话原意。","references":[],"evidence":"爱国主义始终是把中华民族坚强团结在一起的精神力量","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-6ac7819d0e49b988":{"review":{"definition":"习近平在2014年文艺工作座谈会上指出，中华优秀传统文化是中华民族的精神命脉，也是涵养社会主义核心价值观的重要源泉。","explanation":"讲话把中华优秀传统文化视为中华民族的精神根基，并指出它为培育社会主义核心价值观提供文化滋养。第62题C项保留了“中华优秀传统文化”这一范围以及“重要源泉”这一关系，符合讲话原意。","references":[],"evidence":"中华优秀传统文化是涵养社会主义核心价值观的重要源泉","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-012f63d30d58022c":{"review":{"definition":"习近平指出，精神文明建设要紧紧围绕促进人民福祉来进行，通过办实事、讲实效，努力满足人民群众不断增长的精神文化需求。","explanation":"题解援引习近平2015年会见第四届全国文明城市、文明村镇、文明单位和未成年人思想道德建设工作先进代表时的讲话。“促进人民福祉”指明工作目标，“办实事、讲实效”指明工作要求。第62题D项同时保留了这两层意思，表述正确。","references":[],"evidence":"抓精神文明建设要办实事、讲实效，紧紧围绕促进人民福祉来进行","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-309315bac8d2c6a2":{"review":{"definition":"习近平在2025年致中国少年先锋队第九次全国代表大会的贺信中指出，少年儿童是推进强国建设、民族复兴伟业的未来生力军。","explanation":"贺信以“未来生力军”说明少年儿童在强国建设、民族复兴中的长远角色，并以“大学校”说明少先队在少年儿童健康成长中的作用。第63题①准确复述了对少年儿童的定位。","references":[],"evidence":"少年儿童是推进强国建设、民族复兴伟业的未来生力军","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0f5c844f4b88a9d2":{"review":{"definition":"习近平在2015年会见中国少年先锋队第七次全国代表大会代表时指出，一个人可以有很多志向，人生最重要的志向应该同祖国和人民联系在一起。","explanation":"讲话把与祖国和人民相联系的志向视为各种具体志向的基础，借此说明少年儿童从小立志应有怎样的方向。第63题②同时保留了“可以有很多志向”和“最重要的志向”两个层次，表述正确。","references":[],"evidence":"一个人可以有很多志向，但人生最重要的志向应该同祖国和人民联系在一起","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5334bfbc0dd6987b":{"review":{"definition":"习近平在2023年考察北京育英学校时指出，体育锻炼是增强少年儿童体质最有效的手段。","explanation":"讲话以孩子们要“长得壮壮的、练得棒棒的”强调体育锻炼对增强体质的作用。第63题要求判断讲话表述，③把原话中的“体育锻炼”换成“定时体检、均衡营养”，因此③不计入正确项。","references":[],"evidence":"体育锻炼是增强\n\n少年儿童体质最有效的手段","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-dbabec9fa224ee82":{"review":{"definition":"习近平在2020年教育文化卫生体育领域专家代表座谈会上指出，要帮助学生在体育锻炼中享受乐趣、增强体质、健全人格、锻炼意志。","explanation":"讲话把让孩子们参加体育锻炼与科学组织锻炼结合起来，要求做好保护和准备工作。第63题④完整保留了四项目标，既包括增强体质，也包括享受乐趣、健全人格和锻炼意志，表述正确。","references":[],"evidence":"帮助学生在体育锻炼中享受乐趣、增强体质、健全人格、锻炼意志","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9c50dfc7a5975103":{"review":{"definition":"习近平在2025年参加首都义务植树活动时指出，美好生活都是靠劳动创造出来的，广大青少年要热爱劳动、热爱大自然。","explanation":"讲话以植树造林等公益活动为例，说明青少年可以在劳动中锻炼身体、锤炼意志、增长知识，促进德智体美劳全面发展。第63题⑤保留了关于劳动价值的判断和对青少年的两项要求，表述正确。","references":[],"evidence":"美好生活都是靠劳动创造出来的，广大青少年要热爱劳动、热爱大自然","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-be95226e605647dc":{"review":{"definition":"2025年中央城市工作会议判断，我国城镇化正从快速增长期转向稳定发展期，城市发展正从大规模增量扩张阶段转向存量提质增效为主的阶段。","explanation":"“稳定发展期”描述的是城镇化进程，“存量提质增效为主”描述的是城市发展方式，重心转向提高已有城市空间和设施的质量与效益。第④项准确写出了城市发展方式的变化，但把城镇化阶段的“稳定发展期”改成“高质量发展期”，因此整项错误。","references":[],"evidence":"我国城镇化正从快速增长期转向稳定发展期","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0e3d5833ee0c27fb":{"review":{"definition":"习近平总书记指出，要把服务群众、造福群众作为基层治理的出发点和落脚点。基层治理应从群众需求出发，并以增进群众福祉为目标。","explanation":"题中解析把提供优质高效的公共服务作为落实这一要求的途径。基层通过服务回应群众需求，有助于形成既有活力又有良好秩序的社会环境，因此第66题②把治理目标和公共服务联系起来是正确的。","references":[],"evidence":"造福群众作为基层治理的出发点和落脚点","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a055caf0484c20ab":{"review":{"definition":"党的十八届三中全会《决定》提出，要让发展成果更多更公平惠及全体人民，必须加快社会事业改革，解决好人民最关心最直接最现实的利益问题。","explanation":"《决定》把提供多样化服务、更好满足人民需求作为社会事业改革促进发展成果共享的途径。第68题B项准确写出了加快社会事业改革和解决群众切身利益问题这两项要求，在选非题中应排除。","references":[],"evidence":"必须加快社会事业改革，解决好人民最关心最直接最现实的利益问题","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a05d0ae16801c166":{"review":{"definition":"习近平在2025年4月30日召开的部分省区市“十五五”时期经济社会发展座谈会上提出，谋划“十五五”时期经济社会发展，要深入分析论证各方面的目标任务，确保科学精准、能够如期实现。","explanation":"讲话把分析论证与准确把握阶段性要求、抓住关键性和决定性因素以及把握实施节奏联系起来。A项准确保留了科学精准和能够如期实现这两项要求，在本题中属于正确表述。","references":[],"evidence":"要深入分析论证，确保科学精准、能够如期实现","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8be9882f382414de":{"review":{"definition":"习近平在2025年4月30日召开的部分省区市“十五五”时期经济社会发展座谈会上提出，要增强维护安全能力，以高效能治理促进高质量发展和高水平安全良性互动。","explanation":"讲话将这一要求放在研判国际形势变化、因势调整优化经济布局的背景下，并提出以新安全格局保障新发展格局。B项准确表述了维护安全的能力要求以及治理效能在统筹发展和安全中的作用，在本题中属于正确表述。","references":[],"evidence":"增强维护安全能力，以高效能治理促进高质量发展和高水平安全良性互动","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-db21bc47f4a87c60":{"review":{"definition":"习近平在2025年4月30日召开的部分省区市“十五五”时期经济社会发展座谈会上提出，统筹推进教育科技人才一体发展，筑牢新质生产力发展的基础性、战略性支撑。","explanation":"讲话要求以科技创新为引领、以实体经济为根基发展新质生产力，并将教育、科技、人才纳入统筹部署。C项保留了支撑新质生产力的目标，却将「统筹推进……一体发展」改成「分别推进……独立发展」，因此是本题要求选出的不正确表述。","references":[],"evidence":"要统筹推进教育科技人才一体发展","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f9fddb9bab41e56d":{"review":{"definition":"习近平在2025年4月30日召开的部分省区市“十五五”时期经济社会发展座谈会上提出，要研究推出一批均衡性可及性强的民生政策举措，着力解决群众急难愁盼问题。","explanation":"均衡性侧重政策资源和服务机会的合理分布，可及性侧重群众能否实际获得政策支持。讲话还要求有关举措讲求实效、尽力而为、量力而行。D项同时写出了拟推出举措的两项要求和要解决的问题，在本题中属于正确表述。","references":[],"evidence":"要研究推出一批均衡性可及性强的民生政策举措，着力解决群众急难愁盼问题","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cacaefdbcf2c57c5":{"review":{"definition":"习近平在2018年深入推动长江经济带发展座谈会上指出，生态环境保护与经济发展是辩证统一的关系，应坚持在发展中保护、在保护中发展。","explanation":"讲话把保护要求放进发展过程，也把保护作为发展过程的一部分，并指出经济结构和经济发展方式关系到生态环境保护的成败。第76题A项准确概括了讲话对两者关系的判断。","references":[],"evidence":"生态环境保护和经济发展不是矛盾对立的关系，而是辩证统一的关系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0171d824b4e74f68":{"review":{"definition":"习近平在2025年气候和公正转型领导人视频峰会致辞中提出，绿色转型必须以人民为中心，协同推进民生福祉改善和气候治理。","explanation":"致辞把绿色转型视为应对气候变化的必由之路和经济社会发展的新引擎。第77题③所列的保护环境、发展经济、创造就业和消除贫困，正是致辞要求统筹推进的多重目标，因此③正确。","references":[],"evidence":"绿色转型必须以人民为中心，协同推进民生福祉改善和气候治理","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-aea9547c81db4312":{"review":{"definition":"党的二十大提出，推动经济社会发展绿色化、低碳化是实现高质量发展的关键环节。","explanation":"解析指出，高水平生态环境保护为生态优先、绿色低碳的高质量发展提供支撑。第79题②同时写对了论述的出处和绿色低碳转型在高质量发展中的作用。","references":[],"evidence":"推动经济社会发展绿色化、低碳化是实现高质量发展的关键环节","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b92feecb2f391090":{"review":{"definition":"习近平指出，自我革命是中国共产党跳出治乱兴衰历史周期率的第二个答案。","explanation":"2025年6月30日，习近平在主持中共中央政治局第二十一次集体学习时重申这一定位，并提出要在增强党性、规范权力运行、从严监督执纪等方面进一步落实。A项将“第二个答案”写成“第一个答案”，因此是本题应选的错误项。","references":[],"evidence":"自我革命是我们党跳出治乱兴衰历史周期率的第二个答案","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e0203352a43cb7d0":{"review":{"definition":"习近平指出，从抓作风入手推进全面从严治党，是新时代党的自我革命一条重要经验。","explanation":"党的十八大以来，党中央以八项规定开局破题，从中央政治局带头做起，聚焦纠治“四风”开展集中教育和专项整治。这些做法说明作风建设怎样成为推进全面从严治党的切入点。B项准确复述了这条经验，因此在本题选非时排除。","references":[],"evidence":"从抓作风入手推进全面从严治党是新时代党的自我革命一条重要经验","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-67cbe2addb688ac1":{"review":{"definition":"习近平指出，领导干部的作风直接关系党内风气和政治生态，关系民心向背，决定着党的群众基础。","explanation":"2018年1月5日的讲话把领导干部作风的影响从党内风气和政治生态延伸到民心向背与党的群众基础。第①项保留了这层关系，尤其是对群众基础使用了原表述中的「决定着」，因此应计入正确项。","references":[],"evidence":"关系民心向背，决定着党的群众基础","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-522c911507a1db27":{"review":{"definition":"新华社2023年7月关于新时代人民军队党的领导和党的建设的述评指出，党的力量来自组织，组织强则军队强。","explanation":"述评以人民军队各级党组织领导力、组织力、执行力不断增强为依据，说明坚强的党组织能够巩固强军兴军的优势。B项把党的力量来源写成军队，又把“组织强则军队强”的关系倒置，因此是本题要求选出的有误项。","references":[],"evidence":"党的力量来自组织，组织强则军队强。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9ebda3c13218d4b5":{"review":{"definition":"新华社2023年7月关于新时代人民军队党的领导和党的建设的述评指出，选人用人是干部队伍建设的指挥棒，也是政治生态的风向标。","explanation":"“指挥棒”指选谁、用谁会引导干部队伍的建设方向，“风向标”指用人标准和用人风气能够反映政治生态。述评列举全方位考察识别干部、深化干部工作大检查和匡正选人用人风气等做法。C项正确保留了两个比喻各自对应的对象。","references":[],"evidence":"选人用人是干部队伍建设的指挥棒，是政治生态的风向标。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cab917ca20f64c11":{"review":{"definition":"2025年中央周边工作会议指出，周边是实现发展繁荣的重要基础、维护国家安全的重点、运筹外交全局的首要、推动构建人类命运共同体的关键。","explanation":"会议在我国幅员辽阔、边界线长的背景下阐明周边的战略地位。④准确对应其中两项定位，“首要”对应运筹外交全局，“关键”对应推动构建人类命运共同体。","references":[],"evidence":"周边是运筹外交全局的首要、推动构建人类命运共同体的关键","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9bc2b77e2c27c62f":{"review":{"definition":"习近平在2022年第五届中国国际进口博览会开幕式致辞中指出，开放是人类文明进步的重要动力，是世界繁荣发展的必由之路。","explanation":"致辞针对世界经济复苏动力不足，提出通过开放汇聚合作与创新力量、推动经济全球化，让发展成果更多更公平惠及各国人民。B项符合该致辞，题目要求选出有误的表述。","references":[],"evidence":"开放是人类文明进步的重要动力，是世界繁荣发展的必由之路","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-35c89c2d30550b10":{"review":{"definition":"习近平在2020年中央全面依法治国工作会议上指出，要坚持党对全面依法治国的领导。党的领导是推进全面依法治国的根本保证。","explanation":"这一定位明确了坚持党对全面依法治国领导的依据。第96题②同时写出了坚持党的领导的要求和“根本保证”的定位。③的“重点任务和主体工程”对应法治政府建设，两项分别表述不同对象的地位，均成立。","references":[],"evidence":"党的领导是推进全面依法治国的根本保证。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a80d48336e086c3b":{"review":{"definition":"习近平关于中国式现代化的重要论述明确，中国式现代化是中国共产党领导的社会主义现代化。中国共产党的领导是中国式现代化的根本政治保证。","explanation":"中共中央党史和文献研究院的《求是》文章将这一性质界定归入根本政治保证问题。①前半句明确由谁领导以及现代化的社会主义性质，后半句指出这一定性回答的理论问题，两者对应正确。","references":[],"evidence":"中国式现代化是中国共产党领导的社会主义现代化","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ba2d59fbd6dbe36b":{"review":{"definition":"中共中央党史和文献研究院在《求是》文章中指出，习近平提出中国式现代化的中国特色、本质要求和重大原则，回答了推进中国式现代化的最高顶层设计问题。","explanation":"中国特色说明这种现代化具有哪些特征，本质要求明确建设所要体现的根本要求，重大原则明确推进过程中应把握的基本准则。②把这三方面联系到最高顶层设计，与文章的概括一致。","references":[],"evidence":"中国式现代化的中国特色、本质要求和重大原则","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c1d4398a18111b0a":{"review":{"definition":"习近平关于中国式现代化的重要论述提出，推进中国式现代化要统筹兼顾、系统谋划、整体推进。中共中央党史和文献研究院在《求是》文章中将其概括为方法论要求。","explanation":"统筹兼顾要求协调各方面工作，系统谋划要求把相互关联的任务放在全局中安排，整体推进要求各项任务相互配合。这三项要求共同回答怎样组织和推进现代化建设，③的归属正确。","references":[],"evidence":"统筹兼顾、系统谋划、整体推进中国式现代化","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f5acca26d0a145eb":{"review":{"definition":"习近平关于中国式现代化的重要论述指出，中国式现代化创造了人类文明新形态。中共中央党史和文献研究院在《求是》文章中将其概括为中国式现代化对人类文明发展的重大贡献。","explanation":"④所说的“人类文明新形态”是这一论述提出的文明层面的成果，所以它对应的是“中国式现代化对人类文明发展作出了什么贡献”这一问题。","references":[],"evidence":"中国式现代化创造了人类文明新形态","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-39587375de80a804":{"review":{"definition":"习近平关于中国式现代化的重要论述提出，推进中国式现代化必须进行伟大斗争。中共中央党史和文献研究院在《求是》文章中将其归入推进中国式现代化的策略和手段。","explanation":"⑤中的“必须”体现了这一论述对推进过程的要求。进行伟大斗争关系到推进过程中如何应对风险挑战，因此⑤与策略和手段问题对应正确。","references":[],"evidence":"推进中国式现代化必须进行伟大斗争","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-713e68763e49192b":{"review":{"definition":"材料3认为，凤凰河生态复苏能为沿河文化的传承和利用恢复条件，流域文化建设也能反哺生态环境。","explanation":"河道干涸后，沿河戏曲说唱渐渐消失，依河而兴的市镇村庄也失去了往日的生机。全线通水为恢复这些文化活动所依托的环境迈出了第一步。材料提出文化建设可以反哺生态，但没有展开具体途径。答题时可将传承保护文化遗产和反哺生态环境写入建议书的意义部分。","references":[],"evidence":"文化之河也能反哺流动的河","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-c7fdb9fb3d9a8a38":{"review":{"definition":"叶教授从凤凰河生态治理获得启发，主张在全流域统筹文化遗产保护传承，通过跨地区、跨部门协调推进系统性规划。","explanation":"凤凰河文化遗产分布于沿岸五省多个县市，各地保护和开发状况不同，过去的考古调查难以整体推进，文化部门也难以协调流域内其他部门。建议书据此借鉴生态治理的协调模式，提出由沿线城市主要领导参加文化工作领导小组，统筹相关部门并制定系统性保护传承战略规划。","references":[],"evidence":"无法统筹流域内相关部门形成保护合力","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-5f0693bbb316def1":{"review":{"definition":"叶教授认为，恢复凤凰河的自然风光和生态环境，可为沿岸历史遗迹、红色文化等资源的旅游利用提供条件，促进生态旅游与文化旅游融合。","explanation":"沿岸历史遗迹和红色文化资源提供了文化游览内容，恢复后的自然风光和生态环境则可提供游览空间与体验。全线通水是生态恢复的第一步，建议书据此把进一步恢复沿河风光和生态与发展两类旅游结合起来，作为活化利用文化资源的一项措施。","references":[],"evidence":"就可以推动生态旅游和文化旅游融合发展","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-77b440d77f8e1fc4":{"review":{"definition":"叶教授主张通过群众可以接触和参与的活动与场景，让流域文化融入生活，在使用中得到传承。","explanation":"材料提出利用沿岸历史遗迹和红色文化资源发展旅游，通过现代文化景观汇聚人气，并开发“凤河游”App，让游客沉浸式体验虚实结合的河流景观。建议书可把建设文化景观和开发数字体验写成回应文化尚未充分融入群众生活的具体措施。","references":[],"evidence":"文化的生命在于‘用’，在于融入群众生活。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-bc1e152127923236":{"review":{"definition":"《流动与新生》范文主张，有序、规范的流动能够催生新的发展活力，而发展中形成的新活力又能带动下一轮流动。","explanation":"题干以大河奔流比喻发展中的变化，并以桥梁路网创造机遇、产业转型升级释放动能提示立意。范文把资源流通和观念更新都纳入“流动”，以路网便利商品运输和人员往来、观念更新带动商业模式探索来展开论证。新业态、新机会又可吸引人员、资金等要素进一步流动。这是范文围绕命题提出的总论点。","references":[],"evidence":"新生的活力又是促进下一轮“流动”的动力","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-457f0db1b64b2d6f":{"review":{"definition":"材料3中的叶教授认为，恢复凤凰河流域的自然风光和生态环境，可以为生态旅游与文化旅游融合创造条件，让公众在游览体验中接触流域文化。","explanation":"凤凰河全线通水是流域生态复苏的第一步。叶教授进一步设想，在生态环境和自然风光得到恢复的条件下，将沿岸历史遗迹、红色文化等资源融入旅游体验。作文可用这一设想说明，河水恢复流动如何为沿岸文化焕发新活力创造条件。","references":[],"evidence":"就可以推动生态旅游和文化旅游融合发展","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-d11448a88ebfedfd":{"review":{"definition":"材料2借小辛的叙述说明，村民重新认识窑洞的历史价值和原有建筑风格后，可以把文化认同转化为参与修复和传播的行动。","explanation":"部分村民起初嫌旧料修复费工，也觉得修好后仍然灰蒙蒙。“发现砖石之美”影像展帮助他们看见旧材料承载的村庄历史和个人记忆。此后，村民捐旧瓦、提建议、参加义务劳动，还有人成为义务宣讲员。作文可用这一变化说明，观念更新如何带动公众参与，让废弃窑洞成为仍在使用和传播的文化教育资源。","references":[],"evidence":"从旁观者变成参与者再到传承者","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-6999f4a816789d1e":{"review":{"title":"现代化建设的人民立场","type":"观点与论证","definition":"党的二十大报告提出，把实现人民对美好生活的向往作为现代化建设的出发点和落脚点。","explanation":"这一立场以人民对美好生活的需要确定建设方向，以人民生活的改善衡量建设成效。报告在论述全体人民共同富裕的现代化时，将这一立场同维护和促进社会公平正义、促进全体人民共同富裕相联系。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"前进道路上必须牢牢把握的重大原则"}],"examFocus":{"国考 2023 副省级 行测#1":"按党的二十大报告区分中国式现代化的建设宗旨、主要目标和中国特色，再核对各项表述。"}},"aspects":[{"title":"现代化建设的出发点和落脚点","uses":[{"unit":"Q1","role":"直接考查","use":"本题均要求统计对中国式现代化理解正确的陈述。①符合二十大报告关于现代化建设目标的表述，计入正确项，两卷均选B（3项）。","evidence":"坚持把实现人民对美好生活的向往作为现代化建设的出发点和落脚点","qids":["国考 2023 副省级 行测#1","国考 2023 行政执法 行测#1"]}]}]},"k-abc7a40f1ee48790":{"review":{"title":"全体人民共同富裕的现代化","type":"观点与论证","definition":"党的二十大报告将全体人民共同富裕列为中国式现代化的中国特色之一，强调现代化发展成果惠及全体人民。","explanation":"报告指出，共同富裕是中国特色社会主义的本质要求，实现共同富裕是一个长期的历史过程。报告还把实现全体人民共同富裕列为中国式现代化的本质要求，强调维护和促进社会公平正义，坚决防止两极分化。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"中国式现代化的中国特色与本质要求"}],"related":["k-a00a8fcb9d224472","k-aa052a4589f73e60","k-bea39803d34d2724"],"examFocus":{"国考 2023 副省级 行测#1":"依据党的二十大报告区分中国式现代化的建设宗旨、共同富裕的定位和发展道路。"}},"aspects":[{"title":"共同富裕的性质与地位","uses":[{"unit":"Q1","role":"直接考查","use":"本题的②用“社会主义的本质要求”和“中国式现代化的重要特征”说明共同富裕的地位。两卷均判②正确，选B（3项）。词条采用题解所引报告中的“中国特色社会主义的本质要求”。","evidence":"共同富裕是社会主义的本质要求，是中国式现代化的重要特征","qids":["国考 2023 副省级 行测#1","国考 2023 行政执法 行测#1"]}]}],"sources":[{"id":"f35814de334992f6","label":"中国式现代化是全体人民共同富裕的现代化","topic":"发展与治理","category":"非时政","text":"2.中国式现代化是全体人民共同富裕的现代化\n中国式现代化是中国共产党领导的社会主义现代化，既有各国现代化的共同特征，更有\n基于自己国情的中国特色。\n（1）中国式现代化是人口规模巨大的现代化。\n（2）中国式现代化是全体人民共同富裕的现代化。\n（3）中国式现代化是物质文明和精神文明相协调的现代化。\n（4）中国式现代化是人与自然和谐共生的现代化。\n（5）中国式现代化是走和平发展道路的现代化。","source":{"doc":"6cbfb01fe723bba64b75","first":18,"last":18,"page":18,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-bea39803d34d2724":{"review":{"title":"物质文明和精神文明相协调","type":"观点与论证","definition":"党的二十大报告将物质文明和精神文明相协调列为中国式现代化的中国特色之一，强调物质富足和精神富有都是社会主义现代化的根本要求。","explanation":"报告提出，在厚植现代化物质基础的同时发展社会主义先进文化、加强理想信念教育、传承中华文明，以促进物的全面丰富和人的全面发展。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"中国式现代化的中国特色"}],"related":["k-aa052a4589f73e60","k-abc7a40f1ee48790"],"examFocus":{"政治理论必刷100题#62":"辨析中国式现代化相关论述对物质文明与精神文明关系的表述。","国考 2023 副省级 行测#1":"依据党的二十大报告，逐条辨析各陈述对中国式现代化的建设宗旨、特征、目标和道路的概括。"}},"readings":[{"origin":"k-bea39803d34d2724","title":"物质文明和精神文明相协调","qs":["国考 2023 副省级 行测#1","国考 2023 行政执法 行测#1"],"definition":"党的二十大报告将物质文明和精神文明相协调列为中国式现代化的中国特色之一，强调物质富足和精神富有都是社会主义现代化的根本要求。","explanation":"报告提出，在厚植现代化物质基础的同时发展社会主义先进文化、加强理想信念教育、传承中华文明，以促进物的全面丰富和人的全面发展。","evidence":"","doubt":"","references":[{"source":"twenty","location":"中国式现代化的中国特色"}]},{"origin":"k-1e2b5b89e5425daa","title":"物质文明和精神文明相协调","qs":["政治理论必刷100题#62"],"definition":"习近平指出，物质文明和精神文明相协调，是中国式现代化的重要特征。这一特征强调物质发展与精神文化发展彼此协调。","explanation":"题解援引2025年全国精神文明建设表彰大会上传达的重要指示，并以社会主流价值的巩固、人民文明素养的提升说明精神文明建设的进展。B项把两种文明的协调关系写成“以精神文明引领物质文明”，改变了原表述中的关系，因此是第62题选非题的答案。","evidence":"应为“物质文明和精神文明相协\n\n调”","doubt":"","references":[]}],"aspects":[{"title":"两种文明协调发展的要求","uses":[{"unit":"Q1","role":"解题依据","use":"本题均将“在物质文明方面超越西方发达国家”列为待判断陈述③。报告强调物质文明和精神文明协调发展，据此判定③对中国式现代化主要目标的概括错误，两卷均选B（3项）。","evidence":"物质富足、精神富有是社会主义现代化的根本要求。","qids":["国考 2023 副省级 行测#1","国考 2023 行政执法 行测#1"]}]}]},"k-10613bff850024e3":{"review":{"title":"创造人类文明新形态","type":"观点与论证","definition":"创造人类文明新形态是党的二十大报告所列的中国式现代化本质要求之一。习近平在2021年庆祝中国共产党成立100周年大会上的讲话中，也将创造人类文明新形态概括为坚持和发展中国特色社会主义、推动五个方面文明协调发展所取得的成果。","explanation":"2021年讲话所说的协调发展涵盖物质文明、政治文明、精神文明、社会文明和生态文明。2023年2月7日，习近平在学习贯彻党的二十大精神研讨班开班式上进一步指出，中国式现代化植根于中华优秀传统文化，体现科学社会主义的先进本质，借鉴吸收人类优秀文明成果，是一种全新的人类文明形态。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"新时代新征程中国共产党的使命任务"},{"source":"web-c755abced8fa2f1f","location":"2021年7月1日，“以史为鉴、开创未来，必须坚持和发展中国特色社会主义”段","quote":"创造了中国式现代化新道路，创造了人类文明新形态。"},{"source":"web-c09cac2182da0c58","location":"2023年2月7日，“习近平指出，中国式现代化，深深植根于中华优秀传统文化”段","quote":"是一种全新的人类文明形态。"}],"examFocus":{"国考 2023 副省级 行测#1":"核对中国式现代化的几类表述，区分建设的出发点、道路特征和文明成果。","江苏 2024 C类 行测#1":"分清各国现代化的共同特征与中国式现代化的自身特点，核对任务难度、发展道路和文明意义的表述。"}},"aspects":[{"title":"中国式现代化的文明成果","uses":[{"unit":"Q1","role":"直接考查","use":"本题的⑤把中国式现代化新道路与创造人类文明新形态相联系。2021年7月1日讲话将两者并列为实践成果。两卷均将⑤计入正确项，选B（3项）。","evidence":"中国式现代化新道路，创造了人类文明新形态","qids":["国考 2023 副省级 行测#1","国考 2023 行政执法 行测#1"]},{"unit":"Q2","role":"直接考查","use":"本题的④用“全新”概括中国式现代化的文明成果。“创造了”有2021年讲话的成果表述作依据，“全新”对应2023年2月7日讲话对这一文明形态的定性。④正确，选D（②③④）。","evidence":"创造了一种全新的人类文明形态","qids":["江苏 2024 C类 行测#1"]}]}]},"k-c74a86ea848cf0a2":{"review":{"title":"人民民主的地位","type":"观点与论证","definition":"党的二十大报告指出，人民民主是社会主义的生命，是全面建设社会主义现代化国家的应有之义。","explanation":"报告在“发展全过程人民民主，保障人民当家作主”一节阐明这一定位，其政治基础是我国是人民民主专政的社会主义国家，国家一切权力属于人民。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"发展全过程人民民主"}],"related":["k-4f1da827daf01526","k-53a4c7ef856b2d94","k-60f2a76759a4b86f"],"examFocus":{"国考 2023 副省级 行测#3":"对照党的二十大报告，辨析人民民主的地位，以及全过程人民民主的本质属性、实践形式和重要体现。"}},"readings":[{"origin":"k-c74a86ea848cf0a2","title":"人民民主的地位","qs":["国考 2023 副省级 行测#3","国考 2023 行政执法 行测#2"],"definition":"党的二十大报告指出，人民民主是社会主义的生命，是全面建设社会主义现代化国家的应有之义。","explanation":"报告在“发展全过程人民民主，保障人民当家作主”一节阐明这一定位，其政治基础是我国是人民民主专政的社会主义国家，国家一切权力属于人民。","evidence":"","doubt":"","references":[{"source":"twenty","location":"发展全过程人民民主"}]},{"origin":"k-0511b46b2204cf5f","title":"人民民主的地位","qs":["国考 2023 地市级 行测#2"],"definition":"党的二十大报告指出，人民民主是社会主义的生命，是全面建设社会主义现代化国家的应有之义。报告将这一定位与国家一切权力属于人民相联系。","explanation":"①准确表述了人民民主的地位。②说明全过程人民民主的本质属性，③说明协商民主是实践全过程人民民主的重要形式，两项均符合报告。报告将“全过程人民民主的重要体现”用于基层民主，④将主体换成党内民主，因此应选①②③。","evidence":"人民民主是社会主义的生命，是全面建设社会主义现代化国家的应有之义","doubt":"","references":[]}],"aspects":[{"title":"社会主义和现代化建设中的地位","uses":[{"unit":"Q1","role":"直接考查","use":"陈述①准确列出人民民主的两重定位。②关于全过程人民民主本质属性的表述和③关于协商民主的表述也符合报告。④把报告所说的“基层民主”换成了“党内民主”。应选①②③，即C项。","evidence":"①人民民主是社会主义的生命，是全面建设社会主义现代化国家的应有之义","qids":["国考 2023 副省级 行测#3","国考 2023 行政执法 行测#2"]}]}]},"k-f3e59dcb3c346a1e":{"review":{"definition":"党的二十大报告将分配制度定位为促进共同富裕的基础性制度，提出构建初次分配、再分配、第三次分配协调配套的制度体系。","explanation":"分配制度通过协调三个分配环节影响收入分配。报告提出提高居民收入在国民收入分配中的比重、提高劳动报酬在初次分配中的比重，具体体现了这一制度怎样促进共同富裕。D项准确对应报告表述。","references":[],"evidence":"分配制度是促进共同富裕的基础性制度","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5fc9851639a6dab5":{"review":{"definition":"党的二十大报告将社会保障体系概括为人民生活的安全网和社会运行的稳定器，强调其保障基本生活、维护社会稳定的作用。","explanation":"报告在健全社会保障体系一节提出完善基本养老保险全国统筹制度、发展多层次多支柱养老保险体系。本题A项把“安全网和稳定器”错配给就业，报告称就业为“最基本的民生”。C项也错配了主体，“民族昌盛和国家强盛的重要标志”对应人民健康。","references":[],"evidence":"系是人民生活的安全网和社会运行的稳定器。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-5dfa658086207b9d":{"review":{"title":"就业的民生地位","type":"观点与论证","definition":"党的二十大报告将就业定位为最基本的民生。","explanation":"就业是劳动者取得劳动收入的重要途径。报告在“实施就业优先战略”一节提出强化就业优先政策、健全就业促进机制，推动实现高质量充分就业。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"实施就业优先战略"}],"related":["k-c9e54faa00997e23","k-1ee6f0c02f41907a","k-95491b6a9bb3eff5"],"examFocus":{"国考 2023 副省级 行测#4":"按党的二十大报告区分就业、人民健康、社会保障和分配制度各自的民生定位，核对选项的主语有没有调换。"}},"aspects":[{"title":"最基本的民生","uses":[{"unit":"Q1","role":"解题依据","use":"A项将社会保障体系的定位套给就业，B项将就业的定位套给人民健康。两项均错误，正确项为D。","evidence":"就业是最基\n本的民生。","qids":["国考 2023 副省级 行测#4","国考 2023 行政执法 行测#3"]}]}]},"k-abbc38c6242df627":{"review":{"title":"人民健康的战略地位","type":"观点与论证","definition":"党的二十大报告指出，人民健康是民族昌盛和国家强盛的重要标志。","explanation":"报告在“推进健康中国建设”一节提出，把保障人民健康放在优先发展的战略位置，完善人民健康促进政策。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"推进健康中国建设"}],"related":["k-a8a2fb78a556548e"],"examFocus":{"国考 2023 副省级 行测#4":"按党的二十大报告区分就业、人民健康、社会保障和分配制度在民生工作中的定位。"}},"aspects":[{"title":"民族昌盛和国家强盛的重要标志","uses":[{"unit":"Q1","role":"解题依据","use":"B项把人民健康说成“最基本的民生”，C项把人民健康的定位套给健全的社会保障体系。两项均错误，正确项为D。","evidence":"人民健康是\n民族昌盛和国家强盛的重要标志。","qids":["国考 2023 副省级 行测#4","国考 2023 行政执法 行测#3"]}]}]},"k-35fe5b4ad45579e2":{"review":{"definition":"《习近平经济思想学习纲要》将进入新发展阶段定位为我国经济发展的历史方位。新发展阶段是全面建设社会主义现代化国家、向第二个百年奋斗目标进军的阶段。","explanation":"历史方位回答我国经济发展处在哪个阶段，因此①的搭配正确。同题的②和③分别回答经济发展以什么为主题、遵循什么指导原则。","references":[],"evidence":"进入新发展阶段是我国经济发展的历史方位","disposition":"独立词条","basis":"据原题和解析编释。","title":"新发展阶段","related":[],"examFocus":{"国考 2023 副省级 行测#5":"依据《习近平经济思想学习纲要》，逐项辨析相关理念和举措在经济发展中的定位。"}},"readings":[{"origin":"k-35fe5b4ad45579e2","title":"新发展阶段","qs":["国考 2023 副省级 行测#5"],"definition":"《习近平经济思想学习纲要》将进入新发展阶段定位为我国经济发展的历史方位。新发展阶段是全面建设社会主义现代化国家、向第二个百年奋斗目标进军的阶段。","explanation":"历史方位回答我国经济发展处在哪个阶段，因此①的搭配正确。同题的②和③分别回答经济发展以什么为主题、遵循什么指导原则。","evidence":"进入新发展阶段是我国经济发展的历史方位","doubt":"","references":[]},{"origin":"k-a3c331e495358f16","title":"新发展阶段","qs":["国考 2023 地市级 行测#4"],"definition":"新发展阶段是全面建成小康社会、实现第一个百年奋斗目标后，开启全面建设社会主义现代化国家新征程、向第二个百年奋斗目标进军的阶段。进入新发展阶段是我国经济发展的历史方位。","explanation":"历史方位回答我国经济发展处于什么阶段。《习近平经济思想学习纲要》把这一定位赋予进入新发展阶段，所以①成立。题中③的指导原则则对应坚持新发展理念。","evidence":"进入新发展阶段是我国经济发展的历史方位","doubt":"","references":[]}]},"k-591ec79ea3a4a6a3":{"review":{"definition":"《习近平经济思想学习纲要》将推动高质量发展定位为我国经济发展的鲜明主题，强调提升发展的质量和效益。","explanation":"鲜明主题回答经济工作要围绕什么展开，因此②正确。⑤的“主要着力点”回答经济工作重点往哪里用力，具体指大力发展制造业和实体经济。","references":[],"evidence":"推动高质量发展是我国经济发展的鲜明主题","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-954005759cd4eef3":{"review":{"definition":"《习近平经济思想学习纲要》将大力发展制造业和实体经济定位为我国经济发展的主要着力点，明确了经济工作的重点。","explanation":"主要着力点回答经济工作重点落在哪些领域，因此⑤的搭配正确。②的“鲜明主题”对应推动高质量发展，两项分别表述工作重点和发展主题。","references":[],"evidence":"大力发展制造业和实体经济是我国经济发展的主要着力点","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-aafae58dc3dcc99d":{"review":{"title":"地理标志保护与地方品牌","type":"观点与论证","definition":"L市知识产权服务案例中，川兴米粉企业负责人认为，川兴米粉获得地理标志保护后，带动了企业品牌和行业发展。","explanation":"材料记载，L市知识产权信息服务中心指导川兴米粉获得国家地理标志产品认定，并于2022年引导出台联盟标准和地方标准，以统一标准提升产品质量。材料中的伊山山珍案例则采用“企业+地理标志商标+标准化+农户”模式推广当地主导产业。","basis":"据关联原题和解析编释。","references":[],"examFocus":{"国考 2023 地市级 申论#2":"从给定资料2的地理标志保护案例中提取服务中心的做法和成效。","国考 2023 行政执法 申论#4":"从给定资料4的地理标志保护案例中提取服务中心的做法和成效。"}},"aspects":[{"title":"川兴米粉的地理标志保护与标准化","uses":[{"unit":"Q1","role":"直接考查","use":"根据给定资料2撰写案例摘要，川兴米粉部分需交代服务中心指导其获得地理标志保护、引导制定标准的做法，以及材料所述的品牌和行业发展成效。","evidence":"‘川兴米粉’获得地理标志保护，带动了整个企业品牌乃至行业的发展。","qids":["国考 2023 地市级 申论#2"]},{"unit":"Q2","role":"直接考查","use":"根据给定资料4撰写案例摘要，川兴米粉部分需写明服务中心指导其成为国家地理标志产品所带来的品牌和行业发展，以及联盟标准和地方标准对产品质量提升的作用。","evidence":"指导其成为国家地理标志产品，带动品牌和行业发展","qids":["国考 2023 行政执法 申论#4"]}]}]},"k-327f63b6606c579e":{"review":{"definition":"“一企包一县”是指地方政府将全县屋顶光伏资源打包交给一家企业开发。S市调研组发现，采用这一模式的地区农户每块光伏板的年收益普遍约为40元，其他地区约为50元。","explanation":"独家开发压缩了其他企业的竞争机会，也限制了农户选择租金更高的企业。专家谭先生认为，部分承接项目的大企业主攻集中式光伏、对分布式市场不熟悉，这可能是收益差异的原因之一。题中可用这一地区对比说明农户收益风险，并支持向合格企业开放市场的建议。","references":[],"evidence":"而在S市已实行“一企包一县”的区域，收益则普遍降低至40元左右。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-cfce047550979796":{"review":{"definition":"参考答案建议从企业资质、设备质量和合同履约入手，规范S市户用光伏市场，保护农户的交易和售后权益。","explanation":"D县村民老宋先被告知只需提供屋顶，临安装却被要求垫资并承担杂费，拒装还要交违约金。设备不到一年就坏了，安装方也联系不上。题中可据此提出审核企业资质和设备质量、提供合同范本以明确收费和售后责任，并以投诉渠道、保证金等措施约束履约。","references":[],"evidence":"审核企业资质，确保企业合规运营及产品质量合格","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-db6e1fa93c55e94a":{"review":{"definition":"针对S市试点中的服务缺口，参考答案建议县政府设置专门的业务对接人，协助企业协调屋顶产权相关事项，并明确户用光伏备案要求。","explanation":"E县代理商开发党政机关和学校屋顶时，因缺少政府对接人，需要自行协调产权相关事项。转做户用项目后，企业又遇到逐户备案还是打包备案未明确的问题。题中应分别提出设专人协调和细化备案口径，具体备案方式由当地结合实际确定。","references":[],"evidence":"屋顶的产权开发协调需要企业单独去跑。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-f18340493fa7a33f":{"review":{"definition":"F银行黄行长所说的“金融向善”，是以服务公众需求为业务目标，让全体社会成员公平享有金融服务的机会。","explanation":"短评可以用这一主张统领F银行的事例。小微企业缺少传统审批所需的材料时，银行借助授权数据简化申请。村民出行不便时，银行把服务送进村。材料还通过“企心助农”体现银行在经营普惠业务之外对公益的带动作用。","references":[],"evidence":"让全体社会成员公平享有金融服务的机会","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-8aa6c40ec20de676":{"review":{"definition":"材料5的学者主张，面对难以预见的变化，应承受短期挫折、抵御短期诱惑，持续把时间和精力投入能够产生长期价值的事务，以增强适应变化的韧性。","explanation":"材料以“黑天鹅”和“未知的未知”说明环境变化难以预见，由此提出增强应对韧性的要求。范文以“做长期主义的践行者”为总论点，分别从个人、企业、政府和社会说明怎样把长期投入落到实处。","references":[],"evidence":"心怀信念，坚持把时间和精力投入到能够产生长期价值的事上。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-4d3454f7f078b01c":{"review":{"definition":"材料5的学者认为，个人追求长期价值，需要有一套稳定的判断依据，用来确定发展方向、应对外部干扰。","explanation":"范文用自身优势、兴趣和社会发展趋势说明如何选择适合自己的方向，再用终身学习和持续实践说明如何积累能力。这两层论述把材料所说的“清醒”落实到个人的目标选择和行动上。","references":[],"evidence":"建立理性的认知框架，不受繁杂噪声的影响。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-d814f6a0f46ef3a6":{"review":{"definition":"材料5的学者将追求长期价值视为企业应有的发展格局，主张企业随环境变化持续改进，不断创造价值。","explanation":"范文从技术和经营两方面展开。自主研发有助于掌握核心技术，优化组织架构和按市场需求调整经营模式有助于推动产品、服务升级。两条路径共同支撑企业持续创造经济效益和社会价值的分论点。","references":[],"evidence":"要求企业不断进化、不断创造价值。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-475b76e8b7a3951f":{"review":{"definition":"材料5的学者将立足长期利益、致力长远发展视为政府的担当，主张政府围绕长远公共目标持续推进工作。","explanation":"范文以建设小康社会从提出目标到逐步实现为例，说明长期构想需要跨阶段接续推进，再以全面建设社会主义现代化国家的目标说明这种担当如何延续到新的发展阶段。","references":[],"evidence":"必须立足长期利益，致力长远发展。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-4ac3bc37c7df3b81":{"review":{"definition":"材料5的学者认为，社会各方持续投入支撑人类长期发展的领域，可以形成相互促进、持续发展的正向循环。","explanation":"范文从文明传承展开这一分论点，以曾经繁荣的文明也可能衰落说明传承需要持续维护，再提出向知识、道德、艺术、教育等领域投入资源，以提高全民族的思想道德素质和科学文化素质。","references":[],"evidence":"无数力量汇聚到支撑人类长期发展的领域","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-706c0629001c340d":{"review":{"definition":"习近平在《扎实推动共同富裕》中指出，全体人民共同富裕是面向全社会的总体目标，应从全局把握。各地可以因地制宜探索实现路径。","explanation":"共同富裕需要循序渐进，地方可以先探索有效做法，待总结经验后逐步推开。第②项把地方探索路径扩大为按城乡和东中西部分别确定各自的共同富裕指标，偏离了从全局把握总体目标的要求，因此整项错误。","references":[],"evidence":"全体人民共同富裕是一个总体概念，是对全社会而言的","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f2ca64cda9069956":{"review":{"definition":"题中所引2021年中央经济工作相关表述提出，实现共同富裕，首先要通过全国人民共同奋斗把发展成果做大做好，再通过合理的制度安排把发展成果分配好。","explanation":"“蛋糕”指发展成果。“做大做好”强调共同奋斗和扩大成果，“切好分好”强调通过制度安排合理分配成果。第④项用这两个比喻说明增长和分配在共同富裕中的作用，表述正确。","references":[],"evidence":"通过合理的制度安排正确处理增长和分配关系，把“蛋糕”切好分好","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-7122b5f2f9bc2cba":{"review":{"definition":"材料中的黄教授认为，地方可以利用GEP核算报告巩固生态优势、补齐短板，推动生态优势转化为产业优势。对生产环境有严格要求的企业，优质生态环境可以成为选址的重要条件。","explanation":"A市吸引了电子仪器企业和医药公司等环境敏感型企业。一家医药公司的董事长明确说，高品质医药容器生产对环境要求严格，A市的优质生态环境是该公司选择落户的根本原因。这一事例说明核算报告所识别的生态优势如何与企业的生产条件相匹配，对应本题的产业转入要点。","references":[],"evidence":"各地可以根据报告来强优势、补短板，推动生态优势转化为产业优势。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bb11bb42a5197018":{"review":{"definition":"材料2认为，无人配送、无人便利店等业态通过无接触配送、自助购物等方式，满足消费者对安全、便利和多元生活的需求。","explanation":"材料中的快递公司负责人指出，无人配送能解决末端配送问题，并减少人际接触带来的潜在感染风险。林女士则觉得在无人便利店购物更自在。这些例子可用来交代H市发展无人经济的背景，并引出保障设备安全和服务质量的监管举措。","references":[],"evidence":"对安全、便利和多元生活的需求","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-e2bc3194c80ffd14":{"review":{"definition":"参考提纲建议市场监管部门协助企业制定设备日常养护制度并监督落实，同时推动无人经营场所设置紧急呼叫装置、建立应急机制。","explanation":"材料中的无人便利店在顾客扫码付款后开门，居民担心门控设备故障且现场无人处理，导致顾客被困。日常养护用于降低故障发生的概率，紧急呼叫和应急机制用于故障发生后及时联系人员处置，两者共同支撑提纲中的硬件安全举措。","references":[],"evidence":"建议店内设置紧急呼叫开关","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-bd815f986fd80b99":{"review":{"definition":"参考提纲建议市场监管部门对无人业态的产品和服务开展高频、不定期抽检，依法处理违法行为，并畅通投诉渠道、建立限时反馈机制。","explanation":"无人面馆出现肉片未煮透的问题，另有面馆被举报在经营项目未包含冷食类食品制售的情况下销售凉菜。这些情况分别提示抽检和日常监管要关注食品质量及经营合规。顾客投诉索赔后商家回应较慢，则对应投诉渠道和反馈时限。","references":[],"evidence":"并畅通消费者投诉渠道，建立限时反馈机制","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-392aceae4d40e508":{"review":{"definition":"参考提纲建议H市征求专家、行业代表等各方意见，明确无人食品经营主体的经营范围及相关许可证的发放依据。","explanation":"无人咖啡屋的现制现售设备使用咖啡豆、茶叶、粉料、液态奶品等多种原料，当地几乎没有现成的审批标准可循。联合评审时，个别专家凭经验作出判断，却难以提供权威依据。提纲据此提出完善审批体系，明确许可覆盖哪些经营项目以及依据什么条件发证。","references":[],"evidence":"经营范围不明，相关许可证发放依据不清","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-3f74f607fcb6f0e7":{"review":{"definition":"材料2中的法学教授认为，无人宾馆采用自助入住等经营方式，仍具有旅馆业属性，应按旅馆业治安和公共场所卫生等规则管理，并由相关职能部门履行各自的监管职责。","explanation":"材料列举了无人宾馆未安装住宿登记上传系统、未取得卫生许可证以及消毒不彻底等问题，涉及治安和卫生等多个监管领域。教授据此主张先明确监管主体和职责，参考提纲将这条思路概括为参照相应传统行业明确适用规则并开展联合监管。","references":[],"evidence":"但本质上还是酒店、旅馆","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-5e340cd224cb1436":{"review":{"definition":"材料3中的王社长主张，符合语言文字演变规律的网络新表达可在使用中逐步规范，极不规范或错误、扰乱交流的网络用语应当整治。","explanation":"材料同时提到迅速流行的新表达和个别平台为博眼球故意制造错别字的现象。参考提纲据此区分两种措施，对无不良导向的新表达采取包容审慎的引导，对极不规范或错误的用语加强整治。","references":[],"evidence":"对于一些极其不规范，甚至是错误的网络语言，应该坚决杜绝","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-07e91d47b894374e":{"review":{"definition":"材料3中的某网络平台认为，公开日常高频词的规范表达、讲清审核规则，可以减少用户因误以为正常词语受限而使用谐音替代。","explanation":"该平台说明，“多少钱”和“福利”在正常情况下可以直接使用，用户无需写成“多少米”和“浮力”。参考提纲据此提出鼓励平台公开表达指引、公布高频词，并持续总结和定期公布不规范用字现象，以提高规则透明度和审核水平。","references":[],"evidence":"归纳并公布了包括“多少钱”“福利”“直播间”等日常高频使用的词语","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-f0e6f4129dcfc499":{"review":{"definition":"材料3中的D市书法家协会于会长建议，出版单位应检查拟使用的字体是否符合规范用字要求，发现不合格字体应在出版前处理。","explanation":"材料指出，部分手写字体产品存在笔画多余、部件错误、偏旁混淆和繁简混杂等问题，进入出版物后会影响规范用字。提纲将出版单位自查列为大众传媒整治措施，并提出由相关行业协会遴选推荐优秀字体。","references":[],"evidence":"各出版单位应加强自查，不合格就不能出版","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-a56a9379a531b4ad":{"review":{"definition":"材料3中的丁教授认为，长期、频繁地使用不规范网络语言，容易造成文字使用混乱和表达不规范，对青少年语文素养的培养产生消极影响。","explanation":"丁教授的判断着重于长期、频繁使用带来的影响。参考提纲据此在两个月的集中整治之外，补充联合教育部门加强青少年语文教育的长远举措。","references":[],"evidence":"不规范的网络语言长期、频繁地使用，必定会对青少年语文素养的培养造成消极影响","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-c42f006dbc8b41d9":{"review":{"definition":"《追寻长期价值》的作者主张，面对持续变化和难以预见的冲击，应承受短期挫折、抵御短期诱惑，持续把时间和精力投入能产生长期价值的事。","explanation":"学者先以“黑天鹅”说明增强韧性和适应能力的必要性，再提出持续投入的行动要求。这为本题文章提供了总论点的推导路径。范文以金融危机等事件引出不确定性，继而从个人、企业、政府和社会四个层面展开长期投入的具体做法。","references":[],"evidence":"坚持把时间和精力投入到能够产生长期价值的事上。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-15c6cb5a07b0b13e":{"review":{"definition":"范文主张，个人应根据自身优势、兴趣志向和社会需求确定长远目标，并在目标领域通过实践和终身学习积累能力。","explanation":"材料5要求个人建立理性的认知框架，减少外部噪声对判断的干扰。范文把这一主张落到两步。先结合个人条件和社会发展趋势选择方向，再向有经验的人学习、跟进新知识，并通过反复实践改进。这一分论点回答了个人怎样把长期价值落实到发展选择和日常行动中。","references":[],"evidence":"在目标领域坚持深耕，终身学习，追求自我能力的综合性提升。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-dab5dec8715808c4":{"review":{"definition":"范文主张，企业应持续投入研发、掌握核心技术，并根据市场需求改进经营管理和商业模式，以长期创造经济效益和社会价值。","explanation":"材料5把企业追求长期价值概括为不断进化、不断创造价值。范文用自主研发和取得独立知识产权说明怎样积累技术能力，再用优化组织架构、调整经营模式、升级产品和服务说明怎样让技术与经营改进持续回应市场需求。这些做法支撑企业层面的分论点。","references":[],"evidence":"持续优化经营管理和商业发展模式，推动产品和服务升级","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-3acd3e849ad8ca68":{"review":{"definition":"《追寻长期价值》的作者认为，政府应立足长期利益，致力长远发展。范文把持续改善民生、满足人民对美好生活的需要作为这一担当的具体体现。","explanation":"材料5给出了政府行动的时间尺度。范文以小康社会从提出目标到建成的过程说明长远目标依靠持续推进，又把新发展理念与建设美好生活相联系。这为政府层面的分论点补充了事例和实践方向。","references":[],"evidence":"必须立足长期利益，致力长远发\n展。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-327708e52a9dd120":{"review":{"definition":"范文主张，通过持续投入文化和教育、提高公众思想道德素质和科学文化素质，促进文明传承和社会长远发展。","explanation":"材料5所说的社会层面长期价值，来自各方力量持续汇聚到支撑人类长远发展的领域。范文选择文明传承作为具体领域，以曾经繁荣的文明也会衰落说明传承需要主动维护，再提出从知识、道德、艺术和教育等方面持续投入。这构成文章的社会层面分论点。","references":[],"evidence":"切实全面提高全民族的思想道德素质和科学文化素质，才能让社会永续发展。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-a875ec80c134c064":{"review":{"definition":"材料中的网民对新民乐走红的意义和影响有不同评价。支持者看重传播、创新与传承，质疑者担心市场迎合削弱民乐的传统韵味。","explanation":"甲将走红视为文化自信和国力上升的反映，认为它有利于音乐文化多样性，也给民乐带来更多舞台和机会。丁肯定改编创新能回应时代，戊以年轻人翻奏热门作品、联结同好说明民乐的传承活力，壬期待民乐走向世界。丙认为新民乐价值有限，担心民乐失去原有味道，癸则认为它迎合市场、手法简单，少了中正平和的韵味。这些评价对应第2题的“价值评判”。","references":[],"evidence":"显得热闹张扬有余、沉静\n不足，少了传统文化的中正平和。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-f54163b4d6279ced":{"review":{"definition":"材料中的网民就民乐如何发展提出了守住传统根基、加强艺术引领、与不同文化和科技交流、允许多种道路并行等主张。","explanation":"己认为优秀传统音乐和民族民间音乐滋养当代音乐，因而把守本放在首位。乙要求从业者提高审美和艺术修养，让创新引领听众。庚主张通过与不同文化和科技碰撞来回应时代，寅从作曲家、演奏者和听众共同参与作品呈现出发，主张百花齐放、百家争鸣。第2题将这些分别提出的主张归入“发展道路”。","references":[],"evidence":"所以民乐发展的道路有很多，不必求同，而应百花齐放、百家争鸣。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-07855ddad68ea73c":{"review":{"definition":"材料将新民乐概括为以民族音乐元素为基础、用现代理念和手段创作与演绎的音乐新形式。网民对这一名称的适用范围及界定的必要性有不同看法。","explanation":"辛用早年流行歌曲已有二胡伴奏的例子，追问哪些作品算新民乐。子将新民乐兴起视为民间传统音乐复兴的标志，担心划分过细会造成音乐门类之间的排斥。丑把新民乐放在民乐持续革新的历史中理解，认为“新”体现了人们对其成长势头的关注。第2题把这些关于适用范围和命名的看法归入“概念界定”。","references":[],"evidence":"比如很多年前的流行歌曲中\n已有二胡伴奏的编配方式，算不算新民乐呢？","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-a4c47c76e91c3bbe":{"review":{"definition":"材料通过小沈和小王的经历说明，择业时要把薪酬与工作强度、工作氛围和专业兴趣一起权衡。小王认为，从事自己感兴趣的专业更有价值。","explanation":"小沈跳槽后薪酬提高，却因工作量大幅增加、难以适应工作氛围而离职。小李看重现岗位收入相对稳定、氛围宽松，也担心转岗后遇到类似压力，因此迟迟难以下决心。小王选择与内燃机专业对口的岗位，为小李按兴趣和专业方向主动择业、积累经验提供了参照。","references":[],"evidence":"搞自己感兴趣的专业更有价值","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e4331723eb1e2f93":{"review":{"definition":"材料中的小王判断，内燃机短期内仍有市场，在商用车领域可能保有更长时间的应用空间。","explanation":"小王指出，商用车普遍较重，纯电方案为保证续航需要更大的电池组，面临安全和成本压力。材料还提到氢燃料电池成本较高，国内已有商用车企业和动力总成供应商联手布局氢内燃机。这些是小王作出判断的依据，也支持小李了解细分市场的发展趋势后再作职业选择。","references":[],"evidence":"在商用车领域，内燃机存在\n的时间或许会更久","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-4170c6524068d884":{"review":{"definition":"材料中的小王认为，内燃机和电动机虽是不同的动力形式，但部分技术和理念相通，既有内燃机工作经验可能帮助从业者较快适应新能源汽车行业的相关岗位。","explanation":"小王认为，传统内燃机汽车的控制逻辑更复杂，相关工作有助于深入理解整车和传动系统。答题时可据此建议小李在现岗位吃透技术，并把已有经验视为转岗的基础，增强对自身适应能力的信心。","references":[],"evidence":"对于整车和传动\n系统的理解会更深","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-b7c045465e9e618c":{"review":{"definition":"材料5中的陈先生认为，旧物承载着使用者的情感、记忆和故事。范文据此进一步提出，旧物还可以呈现传统技艺和审美，并通过再利用获得经济价值。","explanation":"材料中，老式橱柜在村民家里已近乎废品，无钉连接的旧马车却能让观众看到传统木工技艺。陈先生也愿意保存市场接受度较低的老物件，希望下一代还能认识它们。这些细节可以用来论证题干所说的“最大挖掘”，即在旧物原有用途减弱后，继续辨认和发掘它承载的其他价值。","references":[],"evidence":"承载了主人的记忆","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-a2892e57edb4b096":{"review":{"definition":"范文主张，保护和修复旧物既要依靠专业判断和技法，减少修补造成的损伤，也需要修复者有耐心，认真对待细致而耗时的工作。","explanation":"王师傅修复无钉连接的旧马车时，担心碰坏部件，因而格外小心。他强调的是带着感情做事。范文再从不当修补可能造成不可逆损伤的角度补充专业要求，由此论证保护修复如何为旧物展示传统技艺、重新发挥价值创造条件。","references":[],"evidence":"这既需要专业的技巧，也要有情感的投入","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-e0770253109af00a":{"review":{"definition":"材料5中的陈先生认为，让老物件进入当代人的日常生活，有助于它们长期存续，因为人们可以在熟悉的生活场景中体会老手艺和旧物的审美价值。","explanation":"陈先生把老物件与新中式家具搭配陈列，让观众直观看到它们在今天的家居环境里能怎样摆放、呈现怎样的效果。这个例子可以用来论证题干的“重新焕发生机”，说明旧物在修复后还可以通过新的使用和展示场景重新进入公众生活。","references":[],"evidence":"老物件与新中式家具组成一个个生活场景陈列其中","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-edb0b53fbcc2a326":{"review":{"definition":"习近平总书记在2023年6月2日文化传承发展座谈会上指出，马克思主义同中华优秀传统文化相结合的前提是彼此契合。二者来源不同，但存在高度契合性。","explanation":"第①项把马克思主义和中华优秀传统文化的高度契合性放在“前提”上，说明二者为什么能够有机结合。该项与讲话一致，计入正确项。","references":[],"evidence":"马克思主义和中华优秀传统文化彼此存在高度契合性","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9fca32ed01c189dc":{"review":{"definition":"习近平总书记在2023年6月2日文化传承发展座谈会上指出，马克思主义同中华优秀传统文化相结合的结果是互相成就，造就一个有机统一的新的文化生命体。","explanation":"讲话用“化学反应”比喻结合产生的新变化。第②项把“互相成就”和“新的文化生命体”表述为结合的结果，与第①项所说的契合前提相区分，计入正确项。","references":[],"evidence":"结合的结果是互相成就，造就了一个有机统一的新的文化生命体","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-a7a321b8c6e5a7d7":{"review":{"definition":"习近平总书记在2023年6月2日文化传承发展座谈会上指出，马克思主义同中华优秀传统文化相结合，拓展了中国特色社会主义道路的文化根基，使这条道路有了更加宏阔深远的历史纵深。","explanation":"中华优秀传统文化为理解中国特色社会主义道路提供了更深厚的历史文化基础。第③项把“更加宏阔深远的历史纵深”归于筑牢道路根基这一作用，与讲话一致，计入正确项。","references":[],"evidence":"让中国特色社会主义道路有了更加宏阔深远的历史纵深","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3dfdbcedc7bccd76":{"review":{"definition":"习近平总书记在2023年6月2日文化传承发展座谈会上指出，马克思主义同中华优秀传统文化相结合，本身就是创新，也开启了广阔的理论和实践创新空间，使我们掌握思想和文化主动。","explanation":"讲话把这种主动体现为运用中华优秀传统文化资源，探索面向未来的理论和制度创新。第④项的前半句“结合打开了创新空间”符合讲话，后半句“在被动顺应中”与“掌握了思想和文化主动”冲突，所以整项错误。","references":[],"evidence":"让我们掌握了思想和文化主动","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-12b76ab4ead8c8ab":{"review":{"definition":"习近平总书记在2023年6月2日文化传承发展座谈会上指出，马克思主义同中华优秀传统文化相结合，巩固了文化主体性。创立新时代中国特色社会主义思想，就是这一文化主体性的最有力体现。","explanation":"第⑤项同时表述了第二个结合的作用和文化主体性的具体体现。“最有力体现”指向创立新时代中国特色社会主义思想，与讲话一致，因此①②③⑤共四项正确，选B。","references":[],"evidence":"创立新时代中国特色社会主义思想就是这一文化主体性的最有力体现","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-57ce44cf155a5f30":{"review":{"title":"调查研究的工作定位","type":"观点与论证","definition":"《习近平关于调查研究论述摘编》把调查研究定位为党的传家宝和做好各项工作的基本功。2023年《关于在全党大兴调查研究的工作方案》将调查研究用于了解实际情况、发现和解决问题。","explanation":"亲身调研有助于直接了解基层实际和群众诉求。二手材料也是了解情况的必要渠道，可以补充信息，但不能代替亲身调研。","basis":"据关联原题及所列出处编释。","references":[{"source":"research","location":"重要意义"}],"related":["k-1f3481a79834db19"],"examFocus":{"国考 2024 副省级 行测#3":"区分调查研究在工作中的地位与了解情况的渠道，辨明亲身调研和二手资料各起什么作用。"}},"aspects":[{"title":"调查研究的地位与信息渠道","uses":[{"unit":"Q1","role":"直接考查","use":"①对调查研究的工作定位表述正确。④将优先开展亲身调研扩大为禁止使用二手材料，表述错误。全题①②③正确，选B。","evidence":"通过二手材料了解情况是必要的，但不能代替亲身调研。","qids":["国考 2024 副省级 行测#3","国考 2024 地市级 行测#3"]}]}]},"k-23bc4fd817ffd1b4":{"review":{"definition":"题中部分科学家的论证把可证伪性视为理论称得上“真正意义上的科学”的必要条件。可证伪性指原则上存在可能与理论相冲突、足以否定该理论的观察结果。","explanation":"这些科学家以多重宇宙理论无法被证伪为理由，认为它称不上“真正意义上的科学”。B项补出这个推断所需的前提。A项所说的“至今未获证实”只涉及目前的证据状况，无法提供可证伪性与科学性之间的联系。","references":[],"evidence":"只有能被证伪的理论，才能称得上是“真正意义上的科学”","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-0d7a3f0f51ff23d7":{"review":{"definition":"冯教授团队主张尊重原有自然环境和传统景观，在新增设施时避让需要保留的景物，在修缮古建筑时延续原有外观。","explanation":"通往村头停车场的道路采用环形走向，绕开两棵百年老树。清池村保留了原始的“清池八景”，古建筑外观修旧如旧。这些做法分别体现了设施建设中的自然风貌保护和既有景观、建筑的风貌延续，共同对应本题“保留原有面貌”的要点。","references":[],"evidence":"清池村仍然保留着原始的“清池八景”，古建筑的外观也已修旧如旧","disposition":"题内说明","basis":"据原题和解析编释。","title":"保留乡村原有风貌","related":[],"examFocus":{"国考 2024 地市级 申论#1":"从给定资料1中清池村道路规划、景观和建筑更新的段落，提取冯教授团队处理原有村貌的具体做法。","国考 2024 行政执法 申论#1":"在给定材料1中找清池村道路选线、景观处理和古建筑改造的细节，归纳团队如何对待村庄原有风貌。"}},"readings":[{"origin":"k-0d7a3f0f51ff23d7","title":"保留乡村原有风貌","qs":["国考 2024 地市级 申论#1"],"definition":"冯教授团队主张尊重原有自然环境和传统景观，在新增设施时避让需要保留的景物，在修缮古建筑时延续原有外观。","explanation":"通往村头停车场的道路采用环形走向，绕开两棵百年老树。清池村保留了原始的“清池八景”，古建筑外观修旧如旧。这些做法分别体现了设施建设中的自然风貌保护和既有景观、建筑的风貌延续，共同对应本题“保留原有面貌”的要点。","evidence":"清池村仍然保留着原始的“清池八景”，古建筑的外观也已修旧如旧","doubt":"","references":[]},{"origin":"k-64a772c5b9859226","title":"保留乡村原有风貌","qs":["国考 2024 行政执法 申论#1"],"definition":"清池村在设施建设和古建筑修缮中保留原有自然景观及古建筑外观。","explanation":"通往村头停车场的道路绕开两棵百年老树，体现了设施建设对原有自然风貌的尊重。保留“清池八景”和使古建筑外观修旧如旧，分别对应原始景观保护和古建筑风貌延续。这些做法构成本题“保留原有面貌”的作答要点。","evidence":"保留原始景观，对古建筑修旧如旧","doubt":"","references":[]}]},"k-915c93cd4044bc56":{"review":{"definition":"冯教授认为，艺术家可以和村民一起从乡村生活中发现美、创造美，让村民在熟悉的生活环境中展现艺术才能。","explanation":"清池时装秀把村里主干道用作舞台，把当地非遗元素融入服饰，并把农具和家中旧物用作道具。村民在专业模特的带领下亲自走秀。乡村生活为活动提供场地和素材，村民亲身参与展演，这两点共同说明团队怎样与村民共创艺术价值。","references":[],"evidence":"以自然为舞台、以生活为剧本","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-5b99a18c9905b72e":{"review":{"definition":"材料所述J省的建设目标，是使基层医疗卫生人才的规模、结构和能力与基层群众健康需求相适应。","explanation":"江平县有的乡镇卫生院一度只有两三名临床医师，麻醉和影像医师尤其紧缺，分别反映了人员规模和专业结构的问题。当地组织医师进修，帮助基层团队独立开展腹腔镜手术，体现了能力建设。本题应把三方面与群众需求相适应写入Y市实施意见的“基本目标”。","references":[],"evidence":"基层医疗卫生人才规模、结构和能力与基层群众健康需求相适应","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-670f28d58cd750d1":{"review":{"definition":"参考答案建议由S市统一规划公共文化空间建设，协调各区的建设项目与服务功能，使各区空间功能互补。","explanation":"材料4中，各区主要按本区需求建设。首家民办美术馆开办后，其他地方纷纷效仿，全市近10家具备一定规模和档次的民办美术馆中，有不少勉强维持。本题据此把重复建设归入建设规划问题，并提出在市级层面协调各区的空间功能。","references":[],"evidence":"其他地方看到我们这么火爆，就纷纷效仿。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-1aafb5b9a33adff9":{"review":{"definition":"参考答案建议S市优化公共文化空间布局，同时考虑场所规模、分布和居民到访的便利程度。","explanation":"材料4中，黄馆长指出成熟空间偏小且分散，一些较大的新建空间离市区远，前往费时费力。城区畅雅艺术空间就在居民家门口，居民买菜后也能顺路到访。本题据此提出适当撤并部分空间、扩大成熟载体规模并使其在市区相对集中。","references":[],"evidence":"但离市区较\n远，去一趟费时费力。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-da8e6aeb3f61dd57":{"review":{"definition":"参考答案建议S市把本地历史文化遗存融入空间建设，形成主题明确、具有创意的公共文化空间。","explanation":"材料4中，黄馆长指出S市有较多历史文化遗存，这些遗存对现有空间的带动有限，市内也缺少主题型和创意创新类空间。本题把地方文化资源利用不足与空间类型欠缺一并纳入建设问题，并以历史文化遗存作为形成空间主题和特色的依托。","references":[],"evidence":"我们也缺少主题型和创意创新类的公共文化空间。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-cd74eea6017ae199":{"review":{"definition":"市艺术学院李院长认为，民营公共文化空间要运营得好，创始人的人文情怀和经营管理能力都很重要。","explanation":"材料4以畅雅艺术空间为例，指出创始人麦老师既是文化名家，也善于经营。部分民营空间创始人具备行业经验和人文底蕴，经营管理能力仍可能不足。本题据此把能力短板归入运营问题，并提出开展经营管理培训。","references":[],"evidence":"与创始人麦老师不仅是文化名家还善于经营密\n不可分。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-f62e7adfc1e4413b":{"review":{"definition":"参考答案建议公共文化空间面向不同年龄段的观众定制活动和课程，以拓展使用群体、提高空间利用率。","explanation":"材料4中，社区书院平时少有人使用，现有使用者以社区儿童为主。市博物馆则面向不同年龄段开设研学、非遗表演和专题讲座。本题借鉴博物馆的做法，为社区书院一类场所提出运营对策，同时回应活动少、受众单一和利用率低的问题。","references":[],"evidence":"目前以社区的儿童为主，以后多搞些活动，也许来的人就多了。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-b19364eff96a1fda":{"review":{"definition":"市博物馆公共服务部常主任认为，博物馆通过提供场所向公众传递文化价值，从而发挥教育功能。","explanation":"材料4中，市美术馆虽然吸引了许多年轻访客，馆长却发现不少人只拍照打卡，忽略了空间的文化内涵、价值观念和特色功能。市博物馆举办非遗表演等活动，让观众通过到访接触具体的文化内容。本题据此提出，运营者应引导访客深入理解空间的文化价值。","references":[],"evidence":"忽视了空间本身的文化\n内涵、价值观念、特色功能","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-7ea3a26af032268a":{"review":{"definition":"参考答案建议公共文化空间营造有区别的场景，并形成各自有特色的服务。","explanation":"材料4中的综合型书店改造后，读者可以买书、阅读和喝咖啡，起初效果良好，两年后经营情况又变差。受访读者指出，大型实体书店的设计、设施和服务相似，多来几次便会失去新鲜感。本题据此从场景和服务两个方面提出改进运营的建议。","references":[],"evidence":"特别在服务上，缺乏个性特点和差异化。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-267de37121ff0147":{"review":{"definition":"材料5认为，社会中的个体和组织在各自领域持续尽责，共同维护稳定而有温度的日常生活秩序。","explanation":"王师傅长期维修桌椅、参与图书馆的木工后勤工作，图书馆由此得以维持日常运转，师生也能更方便地使用设施。范文用这一岗位与公共服务之间的关系展开立意，说明题干所说的默默付出怎样转化为他人每天都能感受到的便利。","references":[],"evidence":"维持图书馆正常运转、提升师生的使用体验","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-1fa06faff62d6b15":{"review":{"definition":"范文主张，劳动者应在本职领域持续学习、精进本领，并运用所学解决服务对象遇到的具体问题。","explanation":"材料5中，王师傅按古籍部的尺寸和功能需求定制木箱，还用小装置限制窗户开启角度，避免磕碰过路人。这些细节具体说明了题干中的“打磨”和“修补”如何提升岗位服务价值，也为范文关于深耕岗位、回应需求的分论点提供了依据。","references":[],"evidence":"为古籍部定制特殊尺寸和功能的木箱","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-ea6ddbd873c226cd":{"review":{"definition":"范文主张，社会应看见并尊重普通劳动者的贡献，政府和组织应改善岗位条件，为劳动者提供成长机会。","explanation":"范文从普通劳动者容易被忽视、可能受到偏见且面临琐碎工作写起，提出通过宣传让贡献得到看见，并通过待遇、工作环境、培训和晋升机会提供实际支持。这一分论点回应了怎样为材料5中王师傅这类劳动者的长期付出创造条件。","references":[],"evidence":"改善工作环境，提供培训和晋升机会，让每个人都有所发展、有所成就。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-93e2e9fead4e76c0":{"review":{"definition":"习近平在中国共产党与世界政党高层对话会上指出，衡量现代化既要看指标数据，更要看人民的幸福安康。","explanation":"讲话把实现人自由而全面的发展作为现代化的最终目标，因此评价成效要看发展给人民生活带来的实际改善。第③项保留了讲话对指标数据和人民福祉的评价侧重。","references":[],"evidence":"现代化不仅要看纸面上的指标数据，更要看人民的幸福安康","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2b5a82c0d03a90ff":{"review":{"definition":"习近平在中国共产党与世界政党高层对话会上指出，政党要锚定人民对美好生活的向往，让现代化更好回应人民各方面诉求和多层次需要。","explanation":"讲话以物质富裕、政治清明、精神富足、社会安定、生态宜人说明美好生活涉及多个方面，并提出兼顾当代人福祉和子孙后代权益。第④项概括了政党推动现代化的目标及其应回应的需求范围。","references":[],"evidence":"政党要锚定人民对美好生活的向往，让现代化更好回应人民各方面诉求和多层次需要","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e36e9018d4f167ea":{"review":{"definition":"习近平在2023年3月看望参加政协会议的民建工商联界委员时提出，民营企业要践行新发展理念，转变发展方式、调整产业结构、转换增长动力，坚守主业、做强实业。","explanation":"讲话把发展方式、产业结构和增长动力的调整，与坚守主业、做强实业一起列为民营企业走高质量发展路子的要求。①完整保留了这两层要求，属于正确组合。","references":[],"evidence":"践行新发展理念，转变发展方式、调整产业结构、转换增长动力，坚守主业、做强实业","disposition":"独立词条","basis":"据原题和解析编释。","title":"民营企业践行新发展理念","related":[],"examFocus":{"国考 2024 副省级 行测#2":"区分推动民营经济高质量发展的相关部署中，哪些要求针对企业自身发展，哪些涉及民间资本投向或资本监管。"}},"readings":[{"origin":"k-e36e9018d4f167ea","title":"民营企业践行新发展理念","qs":["国考 2024 地市级 行测#5"],"definition":"习近平在2023年3月看望参加政协会议的民建工商联界委员时提出，民营企业要践行新发展理念，转变发展方式、调整产业结构、转换增长动力，坚守主业、做强实业。","explanation":"讲话把发展方式、产业结构和增长动力的调整，与坚守主业、做强实业一起列为民营企业走高质量发展路子的要求。①完整保留了这两层要求，属于正确组合。","evidence":"践行新发展理念，转变发展方式、调整产业结构、转换增长动力，坚守主业、做强实业","doubt":"","references":[]},{"origin":"k-fea7bcf29a7d1438","title":"民营企业践行新发展理念","qs":["国考 2024 副省级 行测#2"],"definition":"推动民营经济高质量发展，民营企业要践行新发展理念，转变发展方式、调整产业结构、转换增长动力，坚守主业、做强实业。","explanation":"2023年3月，习近平在看望参加政协会议的民建工商联界委员时，把发展方式、产业结构和增长动力的调整，与坚守主业、做强实业一并列为民营企业走高质量发展道路的要求。本题①完整保留了这些要求。","evidence":"转变发展方式、调整产业结构、转换增长动力，坚守主业、做强实业，自觉走高质量发展路子","doubt":"","references":[]}]},"k-cf5535bb92f2b070":{"review":{"definition":"习近平在2023年3月看望参加政协会议的民建工商联界委员时提出，有能力、有条件的民营企业要加强自主创新，在推进科技自立自强和科技成果转化中发挥更大作用。","explanation":"②保留了“有能力、有条件”的主体限定，并同时写明科技自立自强和科技成果转化两个着力点，符合讲话内容。③涉及另一项民间投资要求，讲话具体指向国家重大工程、重点产业链供应链项目建设。","references":[],"evidence":"有能力、有条件的民营企业要加强自主创新，在推进科技自立自强和科技成果转化中发挥更大作用","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-18dd31aee5c61d10":{"review":{"definition":"习近平在2023年3月看望参加政协会议的民建工商联界委员时提出，要依法规范和引导各类资本健康发展，有效防范化解系统性金融风险，为各类所有制企业创造公平竞争、竞相发展的环境。","explanation":"④写明了两个不同的适用对象。“各类资本”是依法规范和引导的对象，“各类所有制企业”是公平竞争环境所覆盖的主体，金融风险防范化解也是这项要求的一部分。","references":[],"evidence":"要依法规范和引导各类资本健康发展，有效防范化解系统性金融风险，为各类所有制企业创造公平竞争、竞相发展的环境","disposition":"独立词条","basis":"据原题和解析编释。","title":"依法规范和引导各类资本健康发展","related":[],"examFocus":{"国考 2024 副省级 行测#2":"核对民间资本的政策鼓励投向，并区分资本监管、风险防范和公平竞争环境各自涉及的对象。"}},"readings":[{"origin":"k-18dd31aee5c61d10","title":"依法规范和引导各类资本健康发展","qs":["国考 2024 地市级 行测#5"],"definition":"习近平在2023年3月看望参加政协会议的民建工商联界委员时提出，要依法规范和引导各类资本健康发展，有效防范化解系统性金融风险，为各类所有制企业创造公平竞争、竞相发展的环境。","explanation":"④写明了两个不同的适用对象。“各类资本”是依法规范和引导的对象，“各类所有制企业”是公平竞争环境所覆盖的主体，金融风险防范化解也是这项要求的一部分。","evidence":"要依法规范和引导各类资本健康发展，有效防范化解系统性金融风险，为各类所有制企业创造公平竞争、竞相发展的环境","doubt":"","references":[]},{"origin":"k-18dfaf1b6fd6b74d","title":"依法规范和引导各类资本健康发展","qs":["国考 2024 副省级 行测#2"],"definition":"要依法规范和引导各类资本健康发展，有效防范化解系统性金融风险，为各类所有制企业创造公平竞争、竞相发展的环境。","explanation":"本题④保留了讲话中的两个范围，依法规范和引导的对象是各类资本，公平竞争环境面向各类所有制企业。同一讲话还提出鼓励和吸引更多民间资本参与国家重大工程、重点产业链供应链项目建设，③将这一投向换成了互联网投资和境外投资。","evidence":"有效防范化解系统性金融风险，为各类所有制企业创造公平竞争、竞相发展的环境","doubt":"","references":[]}]},"k-f73568a0d814b351":{"review":{"definition":"题中部分科学家的论证把可证伪性视为理论称得上“真正意义上的科学”的必要条件。可证伪性指原则上存在能够反驳该理论的观测或检验结果。","explanation":"题干把“多重宇宙理论无法被证伪”作为论据。B项补出必要条件，使这部分科学家能够据此推出该理论称不上“真正意义上的科学”。A项的“至今未获证实”描述现有证据的状态，无法回答原则上是否存在可反驳该理论的检验。本题判断的是这段论证所依赖的前提。","references":[],"evidence":"只有能被证伪的理论，才能称得上是“真正意义上的科学”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-81ee46821e579981":{"review":{"definition":"清池范式是冯教授团队在清池村探索的艺术乡建思路。它以尊重乡村主体和地方文化特色为前提，通过艺术实践引导村民重新认识乡村价值，参与家园建设。","explanation":"冯教授认为，乡村价值既体现在山水、民居等可见风貌中，也体现在道德、伦理、信仰等深层文化中。本题用这一范式概括团队当好“运营官”的总体做法，共同改造、保留风貌、复原习俗和共创艺术是这一思路的具体体现。","references":[],"evidence":"通过艺术介入乡建，逐渐影响村民对于乡村价值的判断，引导村民回归家园、共建家园。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-73af3dfb196bd7e5":{"review":{"definition":"冯教授认为，艺术家与村民一起从乡村生活中发现美、创造美，就是共创价值。村民可以在自己熟悉的环境中展现日常技能和艺术才能。","explanation":"清池时装秀把村主干道变为舞台，让村民参与走秀，在服饰中融入当地非遗元素，并用农具和旧物作道具。本题用这个事例说明团队怎样以乡村生活为素材，让村民参与艺术创作。","references":[],"evidence":"艺术家来到村庄，如果能和村民一起发现美、创造美，那便是共创价值。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-ccaa22104463ae9e":{"review":{"definition":"材料3中的国家级非遗项目代表性传承人指出，非遗法实施后，他的保护传承工作获得了各级政府支持，并建议社会各界进一步提供资金和场地保障。","explanation":"市文旅集团下属单位提供工作室，国家级和市级扶持资金连续给予资助，这些是报告可列举的实施成效。传承人以保护传承工作复杂、工作量大为由，提出进一步保障资金和场地，属于改进建议。","references":[],"evidence":"需要社会各界给予更多关注，在资金、场地上进一步提供保障","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-46193cdb17edb9e5":{"review":{"definition":"材料3中的律师认为，非遗是共同遗产，体现创作者独特个性的再创作成果应另行考虑其知识产权。家族传承中的不外传约定等情形也使实践中的认定较为复杂。","explanation":"律师以家族项目的不外传规定和翻唱者可辨识的个人声音为例，说明认定时涉及传承约定以及再创作中的个人贡献。报告据此将认定复杂列为实施不足。材料中的翻唱例子体现律师的观点，具体权利归属仍取决于个案事实和适用规则。","references":[],"evidence":"关于非遗传承的知识产权认定仍然比较复杂","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-7aba68b5e065012d":{"review":{"definition":"材料3中的文化部门负责人主张维护非遗自身的结构与秩序，并整体保护其生存环境。艺术研究院研究员主张礼敬传统，通过持续实践维护非遗的原真性。","explanation":"祭祀礼仪的程序和药材炮制技艺的结构属于项目本身。庙会的寺庙空间、民间组织及管理者与组织者的常态互动属于生存环境。报告将维护项目完整性、保护生存环境和礼敬传统归入改进建议。教授提出的适度延展则针对利用与活化环节。","references":[],"evidence":"保留非遗完整结构与秩序，重视非遗生存环境的整体性保护，确保原真性。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-8b0c3c8f8ca79697":{"review":{"definition":"材料3中的国家级非遗项目代表性传承人建议严格考核传承人，使带徒授艺规范有序，落实后继人才培养。","explanation":"严格考核关注传承人取得资格后如何开展传承活动。协会负责人提出的严把“入口关”关注传承人如何遴选。参考报告把严格考核列为改进建议，材料未给出具体考核指标或程序。","references":[],"evidence":"对传承人进行严格考核，保证带徒授艺规范有序。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-386ce3913640401f":{"review":{"definition":"材料3中的大学教授主张，利用与活化非遗应先深入了解项目，再依照文化演化规律作适当延展，选择有利于保护和传承的方式。","explanation":"教授认为，非遗形成于历史并传承于当下，保护工作应为适当的发展变化留出空间。他同时指出，部分地方借活化之名过度开发。报告可据此把深入了解项目、依据文化演化规律选择活化方式列为改进建议。","references":[],"evidence":"在对非遗本身进行细致深入了解之后，选择更","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-6a99c6b799e68322":{"review":{"definition":"参考答案将材料中的就业困难归纳为岗位选择少。求职渠道有限、岗位信息单一，增加了人岗匹配的难度，技能培训不足也限制了缺乏专业技能的退休人员的选择。","explanation":"小丁母亲持有执业药师证，却因找到的岗位每月只休四天、有时还要上夜班而放弃。一位缺少专业技能的退休网友则只能找到保洁、保姆类工作。两例分别说明合适岗位难找和可选岗位范围窄，共同支撑本题的“就业选择少”。","references":[],"evidence":"求职渠道少，岗位信息单一，难以匹配到合适工作","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-1b96ee901f44a040":{"review":{"definition":"参考答案建议搭建老年人再就业求职平台，鼓励企业发布对口岗位，并组织专项技能培训，帮助退休人员获得更多就业选择。","explanation":"集中发布对口岗位回应小丁找工作时遇到的渠道少、信息单一问题。专项培训回应缺乏专业技能的退休人员求职多局限于低门槛行业的问题。两项建议分别改善岗位信息获取和求职者的技能条件。","references":[],"evidence":"探索搭建老年人再就业求职平台，鼓励企业发布对口岗位","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-5db92c4a4ce2af79":{"review":{"definition":"参考答案把子女对隔代照护的期待以及部分网友对岗位竞争和老人体力的顾虑，概括为退休人员再就业面临的“社会不理解”。","explanation":"一位退休网友帮女儿带了两年孩子，想重新安排自己的生活时遭到女儿反对。另有网友以担心“抢饭碗”和老人体力较弱为由质疑再就业的必要性。这些说法在题中体现的是家庭态度和社会评价，实际岗位竞争情况并无材料数据可供判断。","references":[],"evidence":"年轻人担心被抢饭碗，认为老人体力差，没必要再就业","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-733417aca82582f4":{"review":{"definition":"参考答案建议家人理解退休人员从工作中获得的价值感，尊重其选择，并向社会说明退休人员与年轻人的就业需求有形成互补的可能。","explanation":"小丁母亲看重工作带来的被需要感，父亲希望运用原有技能发挥余热。参考答案以这些诉求回应子女对退休生活的安排和网友的“抢饭碗”质疑，提出尊重选择、说明岗位互补可能性的建议。","references":[],"evidence":"让家人理解老人追求的价值感，尊重老人选择","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-7ddacc9ce961c4a9":{"review":{"definition":"参考答案建议从制度上完善退休再就业人员的合同和保险保障，并在制度完善前推广雇主险、意外伤害险等商业保险，以分担用工风险。","explanation":"小丁父亲求职时，电力公司顾虑工作意外引发的赔偿责任，双方经协商购买了雇主险和意外伤害险。参考答案据此提出过渡性建议，并把完善合同和保险安排作为长期对策。个案中商业保险发挥的保障作用取决于保单约定。","references":[],"evidence":"法律正式出台前，推广雇主险、意外伤害险等商业险","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-f773092eb52962fa":{"review":{"definition":"参考文章将行政执法中的“力”理解为适当的执法力度，主张执法机关依法履行监管职责，并约束权力行使、纠正滥用职权。","explanation":"材料中，钟处长一方面提出严肃问责监管不力、执法不到位，另一方面提出纠正以罚增收、以罚代管和逐利执法。倪局长还指出，简单粗暴、以权压人会损害公信力和营商环境。两人的发言为文章从履职和用权两个方面论述“力”提供依据。","references":[],"evidence":"执法者是法律的捍卫者和执行者，有权不能滥用。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-4848d111468ef4ae":{"review":{"definition":"材料中，M市税务局游局长主张把释法明理贯穿执法全过程，以证据认定事实，说明裁量理由，依法作出决定，并向当事人讲清事理、法理、情理。","explanation":"福兴公司认为其利息收入应按“统借统还”业务处理。税务稽查人员出示核查到的登记信息，说明证据、认定理由和政策依据，企业负责人表示愿意接受处理。该案为文章论述“理”提供了例证，体现了事实认定、处理依据与当事人沟通如何相互衔接。","references":[],"evidence":"认定讲证据、裁量讲道理、决定讲法律","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8b474f6d84c52725":{"review":{"definition":"材料中的马老师主张在推进执法全过程记录的同时扩大公众参与、接受社会监督。参考文章把执法公开透明和公众参与作为维护公众权益的途径。","explanation":"税务局游局长把信息公开、过程可追溯与约束行政自由裁量权联系起来，马老师进一步强调让群众看得见执法并能参与监督。文章以此展开对“利”的论述，说明执法记录便于回溯，信息公开和公众参与为社会监督提供条件。","references":[],"evidence":"以‘老百姓看得见’的执法方式，促进全过程阳光执法，提高政府公信力。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-772da113f533852a":{"review":{"definition":"习近平在中国共产党与世界政党高层对话会上提出，坚持以人民为中心是现代化道路能否走得通、行得稳的关键。","explanation":"讲话把人民视为推进现代化最坚实的根基、最深厚的力量，并把实现人的自由而全面的发展作为现代化的最终目标。第①项表述了人民在推进现代化中的作用，第②项据此强调现代化道路必须坚持的人民立场，两项均符合讲话。","references":[],"evidence":"现代化道路最终能否走得通、行得稳，关键要看是否坚持以人民为中心","disposition":"独立词条","basis":"据原题和解析编释。","title":"现代化道路坚持以人民为中心","related":[],"examFocus":{"国考 2024 地市级 行测#1":"围绕现代化方向的人民性，逐项核对人民的作用、道路能否走稳的条件、成效的衡量标准和政党的责任。"}},"readings":[{"origin":"k-772da113f533852a","title":"现代化道路坚持以人民为中心","qs":["国考 2024 行政执法 行测#3"],"definition":"习近平在中国共产党与世界政党高层对话会上提出，坚持以人民为中心是现代化道路能否走得通、行得稳的关键。","explanation":"讲话把人民视为推进现代化最坚实的根基、最深厚的力量，并把实现人的自由而全面的发展作为现代化的最终目标。第①项表述了人民在推进现代化中的作用，第②项据此强调现代化道路必须坚持的人民立场，两项均符合讲话。","evidence":"现代化道路最终能否走得通、行得稳，关键要看是否坚持以人民为中心","doubt":"","references":[]},{"origin":"k-fb932e5b05dc7cfa","title":"现代化道路坚持以人民为中心","qs":["国考 2024 地市级 行测#1"],"definition":"习近平在中国共产党与世界政党高层对话会上指出，坚持以人民为中心是现代化道路走得通、行得稳的关键。","explanation":"讲话把人民视为推进现代化最坚实的根基、最深厚的力量，把实现人自由而全面的发展作为现代化的最终目标。第②项准确表述了判断现代化道路能否走得通、行得稳的关键条件。","evidence":"现代化道路最终能否走得通、行得稳，关键要看是否坚持以人民为中心","doubt":"","references":[]}]},"k-79b8e8da0ee77af0":{"review":{"definition":"习近平在中国共产党与世界政党高层对话会上提出，评价现代化既要看指标数据，更要看人民的幸福安康。","explanation":"讲话将实现人的自由而全面的发展作为现代化的最终目标，因此评价成效时，更要看人民在生活中获得的实际福祉。第③项中的“更要看”准确体现了讲话对人民幸福安康的强调，应计入正确项。","references":[],"evidence":"现代化不仅要看纸面上的指标数据，更要看人民的幸福安康","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-17e511a4a9a20279":{"review":{"definition":"习近平在中国共产党与世界政党高层对话会上提出，政党要锚定人民对美好生活的向往，让现代化更好回应人民各方面诉求和多层次需要。","explanation":"讲话把人民需要落实到物质富裕、政治清明、精神富足、社会安定、生态宜人等方面，并指出要兼顾当代人福祉与子孙后代权益。第④项准确指出政党是推动者，也保留了回应人民各方面诉求和多层次需要的要求，因此表述正确。","references":[],"evidence":"政党要锚定人民对美好生活的向往，让现代化更好回应人民各方面诉求和多层次需要","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4d4d0209343e6f86":{"review":{"definition":"习近平在2023年6月文化传承发展座谈会上指出，中华文明突出的创新性，从根本上决定了中华民族守正不守旧、尊古不复古的进取精神，决定了中华民族不惧新挑战、勇于接受新事物的无畏品格。","explanation":"第5题②对应对待传统的进取精神，③对应面对新挑战、新事物的无畏品格，两项均属讲话对创新性的阐释，因此选B。","references":[],"evidence":"守正不守旧、尊古不复古的进取精神","disposition":"独立词条","basis":"据原题和解析编释。","title":"中华文明的创新性","related":[],"examFocus":{"国考 2024 地市级 行测#6":"辨析中华文明的创新性与包容性，核对题中各项精神品格和历史取向分别对应哪种特性。"}},"readings":[{"origin":"k-4d4d0209343e6f86","title":"中华文明的创新性","qs":["国考 2024 行政执法 行测#5"],"definition":"习近平在2023年6月文化传承发展座谈会上指出，中华文明突出的创新性，从根本上决定了中华民族守正不守旧、尊古不复古的进取精神，决定了中华民族不惧新挑战、勇于接受新事物的无畏品格。","explanation":"第5题②对应对待传统的进取精神，③对应面对新挑战、新事物的无畏品格，两项均属讲话对创新性的阐释，因此选B。","evidence":"守正不守旧、尊古不复古的进取精神","doubt":"","references":[]},{"origin":"k-f2107c52e1239dca","title":"中华文明的创新性","qs":["国考 2024 地市级 行测#6"],"definition":"在2023年6月文化传承发展座谈会讲话中，中华文明突出的创新性体现为中华民族守正不守旧、尊古不复古的进取精神，以及不惧新挑战、勇于接受新事物的无畏品格。","explanation":"②对应传承中的进取精神，③对应面对新挑战和新事物的无畏品格，两项均归于创新性。①的兼收并蓄和④的交往交流交融在同一讲话中归于包容性，因此选②③。","evidence":"从根本上决定了中华民族守正不守旧、尊古不复古的进取精神","doubt":"","references":[]}]},"k-1fbe14fd83874569":{"review":{"definition":"习近平在2023年6月文化传承发展座谈会上指出，中华文明突出的包容性，从根本上决定了中华民族交往交流交融的历史取向，决定了中国各宗教信仰多元并存的和谐格局，也决定了中华文化对世界文明兼收并蓄的开放胸怀。","explanation":"第5题①的「兼收并蓄」指向中华文化对世界文明的开放胸怀，④的「交往交流交融」指向中华民族的历史取向。讲话将两者归于包容性，所以问创新性的本题应排除①④。","references":[],"evidence":"中华民族交往交流交融的历史取向","disposition":"独立词条","basis":"据原题和解析编释。","title":"中华文明的包容性","related":[],"examFocus":{"国考 2024 地市级 行测#6":"辨析中华文明的创新性与包容性分别对应哪些精神品格、文化胸怀和历史取向。"}},"readings":[{"origin":"k-1fbe14fd83874569","title":"中华文明的包容性","qs":["国考 2024 行政执法 行测#5"],"definition":"习近平在2023年6月文化传承发展座谈会上指出，中华文明突出的包容性，从根本上决定了中华民族交往交流交融的历史取向，决定了中国各宗教信仰多元并存的和谐格局，也决定了中华文化对世界文明兼收并蓄的开放胸怀。","explanation":"第5题①的「兼收并蓄」指向中华文化对世界文明的开放胸怀，④的「交往交流交融」指向中华民族的历史取向。讲话将两者归于包容性，所以问创新性的本题应排除①④。","evidence":"中华民族交往交流交融的历史取向","doubt":"","references":[]},{"origin":"k-61e17238191459f8","title":"中华文明的包容性","qs":["国考 2024 地市级 行测#6"],"definition":"2023年6月文化传承发展座谈会讲话将中华民族交往交流交融的历史取向、中国各宗教信仰多元并存的和谐格局，以及中华文化对世界文明兼收并蓄的开放胸怀，归于中华文明突出的包容性。","explanation":"①的“兼收并蓄”对应开放胸怀，④的“交往交流交融”对应历史取向。两项是讲话对包容性的表述，题干问的是创新性，因此排除①④。","evidence":"决定了中华文化\n对世界文明兼收并蓄的开放胸怀","doubt":"","references":[]}]},"k-6417d73219b9a82d":{"review":{"definition":"徐庄改造项目组主张先培育地方特色和游憩体验，让文旅业态随场所成熟逐步形成，避免急于追求短期收益。","explanation":"李主任用网红打卡地迅速走红又迅速沉寂说明短期热度难以持久。赵教授以“竟是山园”为例，说明小小一处土山也能因涵养性情、寄托情怀而成为人们愿意重游的风景。划线句中的“不是产业”指起步时不急于把改造项目产业化，“竟是产业”指地方风貌和游憩体验经长期沉淀后，有望形成具有持久吸引力的文旅产业。","references":[],"evidence":"不必急于把项目第一时间变成文旅产业","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-ece304dce6ef2741":{"review":{"definition":"材料提出，徐庄可依托鹜岛建设生态智城，在改造中统筹生态环境、居民生活和产业发展。","explanation":"材料中的环水空间和生态公园体现生态基础，休闲码头及诗意栖居的目标体现生活需求，照明产业园的同步规划与升级体现生产安排。作答时，这一思路说明徐庄文旅的长期培育如何落在整体改造中。","references":[],"evidence":"强调生态、生活、生产“三生相融”，可以打造“生态智城”","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-79bc1073a495a0c6":{"review":{"definition":"徐庄改造项目负责人李主任提出，在鹜岛设置多个主题游憩空间，让音乐欣赏、儿童游乐、光影游艺和山野田园等内容各得其所，并随时间逐渐成熟。","explanation":"改造蓝图中的“乐之山”“趣之山”“蔬之山”“光之山”等主题，将“竟是山园”寄情于景的思路转化为可体验的游憩内容。题中可据此说明“慢慢发展”有具体的空间安排，游憩体验的积累仍需要时间。","references":[],"evidence":"让音乐欣赏、儿童游乐、光影游艺、山野田园等各种文旅内容各得其所","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-857868aab1288480":{"review":{"definition":"徐庄改造项目负责人李主任主张，把新特色、新风貌根植于当地文化底蕴，统筹历史风貌保护、生态修复和业态更新，逐步推进改造。","explanation":"方案以“十字街”为骨架，保留老屋、老街和古桥，并规划引入书店、茶馆等业态。材料以河流修复还需长期涵养为例，说明环境治理也要纳入整体方案。作答时可用这些安排解释“慢慢发展、慢慢成熟”在改造实施中的含义。","references":[],"evidence":"要考虑新特色、新风貌如何根植于这里的文化底蕴。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-8835ba9e1a20736c":{"review":{"definition":"今州粮仓改造的设计师主张保留粮仓原有的朴素风貌。项目组据此保存了建筑基本架构及有代表性的材料和构件，使新用途仍保有老粮仓的历史质感。","explanation":"项目组放弃在屋顶增设云廊，保留并突出青瓦、红瓦。仓内保留桁条、立柱和瓜皮帽灯罩，并换装低耗灯泡。展板可用这些细节说明“今生”如何延续粮仓的原貌，同时满足新的使用需求。","references":[],"evidence":"粮仓才是整个项目的主题和背景，应该保留原来那些朴素的东西。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-8c5ca989da14eda0":{"review":{"definition":"祥云公司总经理于波涛认为，企业要实现长期稳定经营，需要主动开拓市场，形成自主获取订单的能力。","explanation":"祥云公司早期受益于地方政府支持、公益就业项目和互联网大公司的帮扶订单，较少主动寻找客户。于波涛到H市多方拜访仍未拿到订单，体现了主动获客的现实困难。本题可将对帮扶订单的依赖归入订单来源问题，并对应提出深耕细分市场、拓展客户的建议。","references":[],"evidence":"我们无需主动去市场上‘觅食’","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-9725c6721d9e37e8":{"review":{"definition":"材料4认为，数据标注业务向专业化、场景化、精细化和定制化发展，可能提高对从业者专业知识和技能的要求。","explanation":"2023年，一家大型AI公司自建标注基地，所招标注员均为本科及以上学历，材料将这家企业的招聘条件视为行业门槛提高的信号。蜂鸟公司挑选的5名本科员工仍觉得智能制造标注的模拟任务太难，说明高学历员工也需要积累领域知识和实操技能。本题应据此同时提出引进人才和加强细分领域培训的建议。","references":[],"evidence":"这些标注业务对技术专业度要求很高","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-2230ec1178e64627":{"review":{"definition":"蜂鸟数据公司总经理任倩指出，数据标注业务重视团队协作，优质项目往往还要求企业组织起足够规模的团队。","explanation":"任倩所说的多数优质项目要求团队至少有50人。青溪县一些小企业接不到优质订单，就难以维持足够的员工规模，之后又更难承接优质订单，只能接多层分包、利润微薄的业务。本题可据此归纳“承接能力不足”，并提出推动本地企业协作、共同承接项目的建议。","references":[],"evidence":"标注业务非常注重团队协作，大多优质项目要求人数不低于50人。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-7013b36069e79d07":{"review":{"definition":"祥云公司总经理于波涛提出，让青溪县及邻县的数据标注企业开展跨县协作，形成片区化产业带，以增强整体承接能力和竞争力。","explanation":"据于波涛介绍，青溪县和邻县已有60多家数据标注企业，具备连片协作的基础。他认为仅靠个人力量难以推动这项设想。本题可据此提出由政府统筹，扶持龙头企业，探索建设数据标注基地，带动片区企业协作争取优质项目。","references":[],"evidence":"打造一个片区化数据标注产业带，抱团取暖，形成合力，更容易形成竞争优势。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-4bdac88a6e383f13":{"review":{"definition":"徐庄改造项目组主张立足当地的历史街区和生态资源，通过逐步治理和精细运营培育长远发展价值。","explanation":"项目组担心网红打卡的热度很快消退，因此主张放缓文旅变现，保留十字街肌理及老屋、古桥，同时推进河道生态修复并规划书店、茶馆等多元业态。这些改造安排为申论文章中“保持战略定力”的分论点提供论据，说明长期价值如何通过具体行动逐步形成。","references":[],"evidence":"考虑新特色、新风貌如何根植于这里的文化底蕴","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-e5aa2a0b6887fd46":{"review":{"definition":"今州粮仓改造项目组主张保留老粮仓的基本架构和历史风貌，并通过更新使用功能延续地方粮食文化。","explanation":"项目组采纳设计师的建议，放弃加建屋顶云廊，保留青瓦、红瓦和斑驳墙面，同时把部分旧粮仓改成剧场、展馆等空间，举办爱粮节粮主题活动。在本题中，旧建筑保存了地方记忆，新用途让公众有机会接触这些记忆，两者共同支撑“守正创新”的分论点。","references":[],"evidence":"外部依旧沧桑感十足，内部却蝶变重生","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-e3faccb760a805c4":{"review":{"definition":"申论范文主张，面临危机时，可以通过主动调整和攻克瓶颈，为新的发展创造条件。","explanation":"范文以华为面临技术封锁后攻克难题、发展鸿蒙系统为例，把外部压力、应对行动和新发展路径联系起来。这一段用来说明题干中的主观能动性怎样发挥作用，转化的可能性来自应对行动及其形成的条件。","references":[],"evidence":"也有可能是认知重构、生命重塑的起点","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-6e6c0fdb34803aab":{"review":{"definition":"长青市试点中，林农可以凭林票向县农商银行申请“金林贷”。受访农户反映，办理耗时较长，可办理的银行也只有一家。","explanation":"夏成贤用16张林票贷得30万元，体现了林票满足资金需求的成效。他反映办理时间比该行一般性贷款长，对应简化审批、加快放款的建议。万名忠反映其他银行办不了这项贷款，对应鼓励更多银行开办业务、增加农户选择的建议。","references":[],"evidence":"我用手上的\n16张林票贷款30万元。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-ba9067e2b7addd84":{"review":{"definition":"兴庄国有林场谢场长指出，专业人员老龄化和后续人才断档给林场发展带来困难。参考答案据此提出引进年轻人才，并以“传帮带”促进岗位经验传承。","explanation":"谢场长将招人困难与现有政策、福利吸引力不足以及社会对林业专业的认识偏差联系起来。专项人才政策、改善待遇和加强林业宣传回应招人难，安排有经验的人员带教则帮助新进人员掌握专业工作，回应人才接续问题。","references":[],"evidence":"当前林场专业人员老龄化和断档现象严重","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-4905af339451bd95":{"review":{"definition":"大桥镇林业站方站长认为，制发林票前应明确集体林资源的资产价值，为按份额制发林票提供评估依据。","explanation":"林地、林木等资源需要先经调查，评估才有基础。方站长提到当地先进设备少、调查技术落后、专业人员不足，因此本题提出补充调查设备、提升技术、引入专业人才，以加快评估确权，为社会资本参与提供清晰的资产价值依据。","references":[],"evidence":"林票的制发应当建立在明晰的集体林资\n源资产价值评估基础上","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-6bbea51545fdc470":{"review":{"definition":"参考答案提出探索政府、国有林业单位与社会资本合作，由各方发挥政策支持、专业经营和资金方面的优势，降低社会资本参与林票经营的门槛。","explanation":"方站长指出，现有实践依赖政府和国有林业单位的政策、资金支持，同时对专业经营能力要求较高，导致社会资本参与度低。建议由政府提供政策支持，国有林业单位承担专业经营，社会资本发挥资金优势，以分工回应现有进入门槛。这是本题提出的深化改革方向。","references":[],"evidence":"社会资本进入的门槛高、参与度低","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-19dced786d2e67ed":{"review":{"definition":"针对长青市林票流通范围有限和凭证遗失风险，参考答案提出建设专业化市场交易平台、发放电子化资产凭证，并增设挂失服务。","explanation":"冯教授指出，现有林票未形成电子化资产凭证，只能在农户间流转，也无法挂失。交易平台为扩大市场流通提供场所，电子化凭证为林票标准化提供基础，挂失服务针对凭证遗失带来的风险。这些建议共同回应社会资本参与受限的问题。","references":[],"evidence":"只能在农户间流转，属于非标准化金融产品","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-a4244d8de187d316":{"review":{"definition":"材料中丁主张建立涵盖科普多种功能的评价体系，以提高科学家参与科普的积极性。参考答案据此建议把科普工作作为科研人员考核和激励的重要指标。","explanation":"丁指出，科学家做科普可能被视为“不务正业”，甚至被认为是科研没有成果。把科普贡献纳入评价，可以让这项工作获得制度上的认可。这是提案中完善科普体制机制的一项具体建议。","references":[],"evidence":"将科普工作作为激励、考核的重要指标","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-ec829103d0d2cec7":{"review":{"definition":"材料中己主张由科学家提供一手专业解读，由科普工作者协助转化和传播，使科普内容兼顾科学准确性与通俗性。","explanation":"己指出，科普工作者有时难以独立把握专业内容。乙以爱因斯坦和擅长科普写作的物理学家英费尔德合作为例，说明一线科研经验与科普写作能力可以互补。提案据此把提升科学家自身的科普表达能力和加强协作列入队伍建设建议。","references":[],"evidence":"还要有科普工作者作为“二传手”","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-593bbcc98a00861d":{"review":{"definition":"参考答案建议由科学家协助审核本领域的科普内容，由网络平台关注热点话题，及时处置发现的虚假或错误科普信息。","explanation":"材料中己指出，热点话题经多次转传可能失真，伪科学等不良信息在网上传播快、影响大。提案据此安排两项工作，由科学家把关专业内容的准确性，由平台及时处置传播中发现的失实信息，防止进一步扩散。","references":[],"evidence":"发现虚假错误科普信息时，应立即采取措施，防止信息扩散。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-ff739bdd99e5fa49":{"review":{"definition":"范文主张，人类依赖自然提供生存和生产条件，应在遵循自然规律的基础上利用资源、保护生态，实现绿色发展。","explanation":"材料1中，宣化城北的土壤和柳川河水为葡萄生长提供有利条件。果农因地制宜采用漏斗架栽培，葡萄冠层形成阴凉湿润的小环境，漏斗架结构还有助于保护水土。这个案例可用于论证，自然条件影响生产方式，适应当地条件的生产方式也能发挥生态作用。","references":[],"evidence":"宣化城市传统葡萄园反映了漫长历史时期人与自然相互适应的过程","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-17c9413137624a01":{"review":{"definition":"材料2借新杭市治水实践说明，政府可以通过明确治理需求、购买服务和协调论证，引入企业的专业能力，提高河道治理效能。","explanation":"埠西区政府购买污染源排查服务，虑远科技为治理决策提供一手数据。治理万仑河时，企业综合专家意见提出雨污分流建议，区政府组织论证后决定实施改造。两项实践可作为作文论据，说明政府提供治理任务与协调条件，企业则以专业调查和技术建议支持政府决策。","references":[],"evidence":"开创了双方合力进行科技治水的新模式","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-334d441845326335":{"review":{"definition":"范文主张，金融可通过资金支持帮助实业盘活资源、推进转型，稳健经营的实业也可为金融提供投资渠道和获取回报的机会。","explanation":"范文以部分传统制造业、农林业盈利周期长、经营压力大为背景，先说明融资如何缓解经营压力、支持转型，再以实业稳健经营为条件，说明金融资金如何获得投资机会。两条作用链构成作文中金融与实业互补的分论点，实际回报取决于项目经营和风险。","references":[],"evidence":"金融为实业提供资金支持，盘活资源，助力转型","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e29364ffa996fa8b":{"review":{"definition":"材料4中的论坛发言者辛认为，科研与科普虽会在时间分配上产生冲突，仍能相互促进。科研为科普提供前沿成果和科学依据，科普则帮助公众了解成果，并把公众的问题和需求带回科研。","explanation":"材料中的“元科普”由一线科研领军人物或团队阐释科学前沿、梳理知识来源，体现科研如何为科普提供依据。发言者庚介绍，公众在科普交流中提出的困惑曾启发团队研究，体现反馈也能为科研提供线索。作文可用这两个方向论证科研与科普的互补。","references":[],"evidence":"科研和科普是一种正向的相互促进关系","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-b0009f035ababd61":{"review":{"definition":"习近平总书记强调，中国人的饭碗任何时候都要牢牢端在自己手中。题目解析据此把粮食安全的自主保障作为判断开放举措的依据。","explanation":"解析肯定利用国内国际两个市场、两种资源。④将开放具体写成逐步提高国外优质种业资源和海外粮食产品在我国的市场占有率，本题正是据此判④错误。解析的判断针对④设定的市场份额目标。","references":[],"evidence":"中国人的饭碗任何时候都要牢牢端在自己手中","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-531277ad5af5ca86":{"review":{"definition":"参考提纲建议西瑞药业定期维护宣传橱窗、更新和丰富宣传材料，并加强节约粮食和垃圾分类宣传。","explanation":"申论第4题中，食堂门口的宣传橱窗只张贴了一份文件，玻璃蒙尘，对应维护橱窗、更新材料。员工把剩饭菜与牛奶盒、饮料瓶一起丢弃，对应增加节约粮食和垃圾分类内容。提纲据此把宣传设施和食堂行为两处发现落实为具体建议。","references":[],"evidence":"强化节约粮食、垃圾分类等知识的传播。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-705cf10485a8579a":{"review":{"definition":"错时办理是把部分服务安排在常规工作时间之外，方便工作日难以到场的群众。C市医保局通过双休日轮岗延长了窗口服务时间。","explanation":"申论第5题中，工作日上班时间与窗口服务时间重叠，双休日轮岗让群众可以在休息日到窗口办医保业务。周末不能现场办结的业务，工作人员先收材料、留联系方式，再于工作日电话跟进，减少群众再次到场的需要。这为论证“为群众办好事”提供了服务时间和后续衔接两方面的例证。","references":[],"evidence":"“上班没空办、下班没处办”的痛点、难点问题","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-205a85372085deff":{"review":{"definition":"网点下沉将服务布设到街道、社区等群众更易到达的地方。一站式办理把相关服务集中到同一网点或渠道，减少往返和重复办理。","explanation":"申论第5题中，C市税务部门与银行、社区、园区、商超等共建网点，将服务延伸到偏远地区和需求集中地区。材料中的奶茶店店主在街道税费服务驿站十几分钟办完业务，具体体现了就近可达和流程集中带来的便利，可用于论证“让群众感到好办事”。","references":[],"evidence":"一站式办理流程，全程只需十几分钟。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-74435fcd01909ae1":{"review":{"definition":"雨霞区政务服务中心王主任认为，“办不成事”窗口通过受理群众疑难诉求、协调责任单位办理并跟进结果，推动解决群众的实际问题。","explanation":"申论第5题中，窗口回访查明逸云路路灯因项目未移交而无法正常通电管养，政务服务中心随即督促相关单位处理并派人到现场督查，三天后32盏路灯全部亮起。这组事实把“把群众的事办好”落在查明症结、推动办理和见到实际结果上。","references":[],"evidence":"三天后，逸云路32盏路灯全部亮起。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-53f77fa78bf475e8":{"review":{"definition":"习近平总书记强调，中国人的饭碗任何时候都要牢牢端在自己手中。按本题解析，深化农业对外开放可以利用国内国际两个市场、两种资源，同时要保持粮食供给的自主性。","explanation":"解析以粮食对社会稳定、经济运行和应对国际变局的重要性说明供给自主性的必要性。第6题④的问题在于把逐步提高国外种业资源和海外粮食产品在我国市场的占有率列为保障粮食安全的举措，因而不计入正确项。","references":[],"evidence":"中国人的饭碗任何时候都要牢牢端在自己手中","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-5ae28eed2e92a8f0":{"review":{"definition":"习近平在2023年新时代推动东北全面振兴座谈会上提出，东北要主动对接国家战略需求，整合和优化科教创新资源，加大研发投入，掌握更多关键核心技术。","explanation":"讲话将对接国家战略需求、优化科教资源和掌握关键核心技术放在以科技创新推动产业创新的部署中。第11题①准确概括了其中的资源配置举措，计入正确项。","references":[],"evidence":"主动对接国家战略需求，整合和优化科教创新资源，加大研发投入，掌握更多关键核心技术。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-dcf59a146ca89fcb":{"review":{"definition":"习近平在2023年新时代推动东北全面振兴座谈会上提出，积极培育产业园区，加强对口合作，加快科研成果落地转化。","explanation":"在讲话关于以科技创新推动产业创新的部署中，培育产业园区和加强对口合作都指向科研成果落地转化。第11题②保留了这两项举措及其目的，计入正确项。","references":[],"evidence":"积极培育产业园区，加强对口合作，加快科研成果落地转化。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-608aa453f5c4bbe0":{"review":{"definition":"习近平在2023年新时代推动东北全面振兴座谈会上提出，加快发展风电、光电、核电等清洁能源，建设风光火核储一体化能源基地。","explanation":"讲话将发展清洁能源和建设一体化能源基地列入东北现代化产业体系的部署。第11题④准确复述了基地建设方向，计入正确项。","references":[],"evidence":"建设风光火核储一体化能源基地","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-07eada3e2e628462":{"review":{"definition":"习近平在2023年新时代推动东北全面振兴座谈会上提出，创新央地合作模式，促进央地融合发展，以更好带动地方经济发展。","explanation":"讲话将深化央地融合与带动地方经济发展联系起来。第11题⑤提出“逐步弱化央地合作”，与讲话的部署相反，因此只有①至④正确，共4项。","references":[],"evidence":"创新央地合作模式，促进央地融合发展，更好带动地方经济发展。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-23e7308f0d15a46c":{"review":{"definition":"外卖骑手负责将餐食等订单商品送达客户。材料一中，骑手小宋认为，这项服务还能为基本物资供应、城市运行和社会稳定提供支持。","explanation":"疫情防控期间，配送需求骤增，已任站点负责人的小宋重返一线，为医院和隔离点送餐。概括时可据此从日常送餐提炼出应急保供和支持城市运行的作用。","references":[],"evidence":"能在基础物资保障、城市发展，甚至社会稳定方面发挥重要作用。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-8a09110ce76dd50c":{"review":{"definition":"网络监督师通过线上服务与客户制定计划、跟进任务完成情况，帮助客户管理时间、培养自律习惯。","explanation":"小叶备考时受拖延和手机使用困扰，监督师每天在线询问学习任务的完成情况。她体验两周后复习效率明显提高，材料二以此说明外部督促可以帮助有类似困扰的人把时间用回学习。","references":[],"evidence":"体验了两周后，复习效率明显提高了。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-02afaf07114ea3ce":{"review":{"definition":"网上导购师在线为客户提供购物建议，帮助客户选购符合实际需求的商品，并以合理价格达成交易。","explanation":"材料二以“双十一”期间的冲动购物为背景。概括时可把按需推荐和协助取得合理价格归纳为促进理性消费，体现消费者对商品是否适合自己、价格是否合理的判断。","references":[],"evidence":"客户以最合理的价格达成交易，还会根据客户的需求提出合理购物建议","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-cd151706d0b1dd4e":{"review":{"definition":"社群管理师为企业运营线上社群，维护群内秩序、回应成员需求，并通过日常互动维持社群活跃度、增强用户黏性。","explanation":"材料二中的小徐制止群内小广告、及时回复群友，还会提醒用户到店领取优惠。前一项体现规范管理，后两项体现持续服务和互动，共同支撑材料所说的维持群活跃度、增强用户黏性。","references":[],"evidence":"帮助企业维持群的活跃度、增强用户粘性。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-bb3deeff30e7c6f4":{"review":{"definition":"制冰师为冰上训练和比赛制作符合使用要求的冰面，为冰雪运动提供场地条件。","explanation":"材料三以国家速滑馆“冰丝带”为例，赛事冰面的质量得到参赛选手认可，中方团队也曾独立完成训练道制冰。概括时可据此写出专业制冰保障赛事和训练用冰、支撑冰上场地建设与使用的作用。","references":[],"evidence":"高质量的冰面赢得国内外选手一致点赞。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-6bad75bb30c8e016":{"review":{"definition":"材料三中的社区助老员为居家老人提供生活照料、日常陪伴和必要的就医协助，支持老人在社区中生活。","explanation":"黄女士平时陪空巢老人柯奶奶聊天、帮她整理房间，老人摔伤后又协助送医和办理住院手续。这些事例可概括为回应社区老人的照料与陪伴需求、促进老有所养，并体现材料所说的敬老助老美德。","references":[],"evidence":"黄女士时常会来陪她聊天，帮她整理房间。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-782aeaaaaa443a6a":{"review":{"definition":"材料4中，陈教授主张，面对新职业带来的择业观念变化，社会成员应增进彼此理解，政府也应给予适当引导。","explanation":"老胡把打游戏视为不务正业，小胡则在专业学习和夏令营助教实践中认识到，职业电竞需要训练、沟通和团队协作，也有赛事运营等相关岗位。父子的分歧说明为什么需要相互理解，材料5中的职业名录更新和职称改革则说明政府可以怎样引导。","references":[],"evidence":"互相理解与政府的适当引导往往是最好的调色剂","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-c40d603a5a00414f":{"review":{"definition":"材料5认为，陆续发布新职业、新工种，既反映了就业方向的变化，也体现了政府职业分类服务随产业和就业形态的发展而调整。","explanation":"材料列举电子竞技员、电子竞技运营师等新职业，把材料4中小胡一家对电竞能否成为职业的分歧，与政府如何回应就业变化联系起来。答题时可据此说明题干所说的“适当引导”如何落实在职业分类上。","references":[],"evidence":"映着就业方向的重大变化，也体现着政府服务的与时俱进。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-f9b2349587006493":{"review":{"definition":"材料5中，G省人社厅相关负责人认为，拓宽新兴职业的职称评价渠道有助于企业和行业吸引人才、建设队伍，使人才发展与产业发展相互促进。","explanation":"科学传播从业者获评研究馆员的案例说明，新设专业职称可以为既有专业成果提供评价渠道。答题时可据此说明政府适当引导的预期作用，即让相关人才获得专业认可，并为行业吸引人才创造条件。","references":[],"evidence":"有利于吸引更多优秀人才，带动行","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-4fe46080c7e55321":{"review":{"definition":"材料七主张，政府应在新业态发展中加强管理、拓宽服务，既规范用工等行为，也为从业者提供就业和权益保障支持。","explanation":"疫情期间，云办公助力复工复产，云消费拓宽市场，网约车司机、骑手等群体的劳务报酬纠纷也带来了维权难题。题干所说的“试金石”，指政府能否顺应新业态创造的就业机会，并及时回应随之出现的治理需求。参考文章据此提出更新职业名录、完善职称评价、强化权益保障三方面对策。","references":[],"evidence":"加强管理力度，拓宽服务宽度","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-50995c87839c73f4":{"review":{"definition":"参考文章主张，通过更新权威职业名录和宣传新职业的社会价值，提高公众对新职业、新工种的认识和认可。","explanation":"材料五列举了互联网营销师作为新职业、直播销售员作为新工种被收录的事例。公布名录让公众了解这些新岗位在职业分类中的位置，宣传其社会贡献和发展前景则帮助公众理解这些岗位的价值。参考文章据此把名录更新与职业宣传配合起来，回应传统就业观念影响新职业接受度的问题。","references":[],"evidence":"引导社会成员转变传统就业观念，提高新职业的社会认可度。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-69b8d0ced018c1c5":{"review":{"definition":"材料七提出完善多渠道灵活就业的社会保障制度，维护快递员、外卖配送员等劳动者的合法权益。参考文章据此建议，政府应完善社会保障、规范新业态用工并加强权益维护服务。","explanation":"材料七以南宁设立灵活就业人员合法权益保障中心为例，具体回应劳务报酬纠纷“难办、难认、难等”的问题。参考文章进一步把劳务报酬、社会保险、工时休假列为建议规范的用工事项，使文章的权益保障对策落到具体问题上。","references":[],"evidence":"完善多渠道灵活就业的社会保障制度","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-a36e11d3f49e4516":{"review":{"definition":"材料六介绍了W市总工会扩大新就业形态劳动者组织覆盖的做法，包括面向快递员、网约车司机等群体组建工会，提供线上入会渠道和普惠服务。","explanation":"W市部分灵活就业人员对工会职能了解有限。线上申请便利了入会，政策咨询、技能培训和劳动权益维护让从业者了解工会能提供哪些帮助。服务驿站则回应了配送途中休息、饮水和充电的需求。这些工会实践为作文提出贴近从业者需求的服务对策提供了实例。","references":[],"evidence":"广泛开展政策咨询、技能培训、劳动权益维护等普惠服务","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-fe2d51938f83c0fa":{"review":{"definition":"国家林草局亚洲象研究中心的于主任提出，处置象群北移事件时，应以同时保障公众和象群安全为底线，并努力让象群南返。","explanation":"据于主任解释，象群越往北越可能面临气温降低、食物匮乏的问题，沿途公众也更缺少接触象群的经验。有关部门和地方政府加强监测预警，保障象群南返。材料用《孟子》关于节制利用自然资源的论述引出儒家生态理想，本题据此概括保障象群南返、促进人与自然和谐相处的治理实践。","references":[],"evidence":"无论如何，一定要保障人象两平安，这是我们一切工作的底线！","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-ac32422dae3cc44a":{"review":{"definition":"材料中的季院长认为，“天下为公”“先集体后个人”的文化自觉，在应对公共卫生危机和构建人类命运共同体时具有积极意义。","explanation":"材料以各地调派人员、物资和设备驰援疫情发生地，说明团结互助传统在跨地区支援和有序保障医疗资源中的体现。我国在自身防控仍有压力时向国际社会提供援助，则体现了这种理念在国际合作中的延伸。本题概括时应同时写到国内调度和国际援助。","references":[],"evidence":"在最短时间内实现医疗资源和物资供应的有序保障。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-766859ad844f9fc7":{"review":{"definition":"参考答案认为，子女和晚辈作事业与生活选择时，应优先考虑长辈晚年对陪伴和照护的实际需要。","explanation":"小万发现独居爷爷缺少陪伴，经过考虑辞职回家，并帮他实现去北京的心愿。爷爷因孙女陪伴而感到幸福，也希望她规划好事业和生活。本题用这一事例说明亲身陪伴是当代尽孝的一种方式，具体安排还要兼顾晚辈自身的发展。","references":[],"evidence":"有了孙女的陪伴，每天都很幸福。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-548ff775420876b4":{"review":{"definition":"材料借黄旭华的经历说明，在重大国家任务及其保密要求与家庭陪伴难以兼顾时，可以优先履行国家责任。","explanation":"黄旭华承担国家重大任务后长期坚守岗位，因保密无法向家人说明工作，父亲去世时也未能回家。母亲后来从公开报道中得知实情，理解了他的选择。材料中“对国家的忠”可以体现孝敬的说法，针对的是这一特殊处境。本题可据此说明当代尽孝需要结合国家责任和家庭处境作出取舍。","references":[],"evidence":"他强忍痛苦，继续坚守在岗位上。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-4c70dcf7b63bf67a":{"review":{"definition":"周先生的事例表明，家乡有适合发挥所长的工作机会时，返乡就业可以兼顾事业发展、服务家乡和陪伴长辈。","explanation":"周先生在统一分配时主动要求回乡，后来成为市级骨干教师并走上领导岗位，也陪伴母亲安度晚年。本题用他的具体选择说明，可以把长辈养老需求纳入职业规划，在工作机会与家庭需要能够兼顾时做到忠孝两全。","references":[],"evidence":"为国、为家乡尽忠，为老人尽孝，我心安无愧。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-3bfc4880c490ec1b":{"review":{"definition":"本题参考启事认为，廉文化可以通过讲述廉洁故事，引导公众思考廉洁自律，为建设廉洁政府、实现政治清明提供精神支持。","explanation":"材料中的《棋局人生 勿忘初心》用棋局表现党员干部受贿后陷入困境、继而纠正偏差的过程，使观众从故事中体会纪律和廉洁的意义。启事开头据此交代举办“清风廉韵”大赛的缘由，作品要求也应体现廉洁主题和教育意义。","references":[],"evidence":"这个视频虽短，但发人深省，教育意义很大！","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-d140f1fabb3ea8c2":{"review":{"definition":"材料8把中华优秀传统文化比作当代中国文化自信的“源头活水”，强调其中具有当代价值的文化精神能为今天的社会发展和文明建设提供精神动力与借鉴。","explanation":"材料援引习近平总书记考察殷墟时关于学习理解中华文明、古为今用的讲话，将历史文化资源同建设中华民族现代文明联系起来。作文可据此论证青年为何要学传统文化，并用范文中的“以和为贵”说明传统理念怎样进入今天的人际交往。","references":[],"evidence":"中华民族灿若星河的优秀传统文化是当代中国文化自信的“源头活水”。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8525110d13eab7a8":{"review":{"definition":"材料8主张，青年应从中华优秀传统文化中汲取成长养分、厚植家国情怀。范文进一步把这一主张落实为在实际行动中把个人成长同国家和社会需要结合起来。","explanation":"范文以黄文秀一心为民、倾力扶贫为例，把家国情怀落到服务群众的行动上。这样可把作文主题中的“汲取营养”与“绽放青春”连起来，说明青年如何将所认同的价值落实到人生选择和担当中。","references":[],"evidence":"以优秀传统文化厚植\n家国情怀","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-acf1d205758edcbf":{"review":{"definition":"材料7主张以有文化底蕴、适合青年接受和参与的方式传播传统文化。纪录片的新技术和博物馆的互动体验，都是材料所举的创造性转化、创新性发展的例子。","explanation":"《本草中华》第二季借助超高速摄影等手法呈现本草世界，同时挖掘其中的“天人合一”思想。荆楚金石博物馆将历史剧情与拓片艺术结合，让参观者在角色扮演中亲身体验。两例可支撑范文关于创新传播载体、缩短青年与传统文化距离的分论点。","references":[],"evidence":"用年轻人喜欢的语言和方式推广“非遗”品牌，讲好中国故事。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-18baf6615b34b254":{"review":{"definition":"党的二十大报告指出，国家安全是民族复兴的根基，社会稳定是国家强盛的前提，并提出以新安全格局保障新发展格局。","explanation":"C项同时对应报告第十一部分关于国家安全地位和安全与发展关系的两处表述。题干问的是“新观点”，完善国家安全战略和政策、以人民安全为宗旨、兼顾传统与非传统安全等内容，在此前的报告或讲话中已有表述。","references":[],"evidence":"国家安全是民族复兴的根基，要以新安全格局保障新发展格局","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c7a667a5f81e0fb5":{"review":{"definition":"L县禁捕办负责人认为，退捕后应落实社会保障，并根据渔民的年龄、教育程度等个人条件安排转产就业，保障长远生计。","explanation":"材料记载，漾湖退捕劳动力获得养老、医疗、社保和住房保障。老夏通过考试成为护渔员，刘大叔一家在农技指导下发展稻虾共养，分别体现了岗位安置和自主创业两种路径。本题可由此归纳出，执法调整影响群众原有生计时，要同步落实生活保障和分类就业帮扶。","references":[],"evidence":"做好转产就业工作是保障渔民上了岸、稳得住的关键。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-3fbdd8d9a1b8357f":{"review":{"definition":"材料6认为，行政执法把法律规范落实到具体治理活动中，是实现良法善治的重要方式。","explanation":"顾警官在五条道路交会的路口拦停越过停车线的骑行人，并带他辨认信号灯、讲解通行规则。这个事例可用来说明作文中“纸上的法治”如何变为“行动中的法治”，并引出执法者怎样通过现场沟通让当事人理解规则。","references":[],"evidence":"法把“纸上的法治”变为“行动中的法治”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-65dd613f2206a82e":{"review":{"definition":"范文主张在行政执法过程中开展普法教育，帮助当事人理解规则、认识过错，从而促进自觉守法。","explanation":"材料6中的骑行人解释，两条路的信号灯离得太近，自己看不清。顾警官带他绕路口辨认信号灯并逐一讲解，他随后承认过错并表示下次会注意。这一细节可用于论证现场普法如何回应具体误解，并帮助当事人今后按规则通行。","references":[],"evidence":"边走边讲解，最后该男子认识到了自己的过错，表示下次一定会注意。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-2fa9639608e93c18":{"review":{"definition":"材料3中，B市市场监管部门负责人主张，对轻微违法采取适当的柔性监管措施，在引导企业纠正行为的同时，兼顾企业经营和营商环境。","explanation":"材料以宣传用语不准确、台账记录不完整等经营问题说明，处罚和失信影响可能给抗风险能力较弱的企业带来较重负担。作文可用B市负责人的说法论证执法如何兼顾纠偏和服务。材料引述的清单涉及不予实施行政强制措施，文中另提到不予处罚决定，两者应按各自的表述引用。","references":[],"evidence":"对轻微违\n法实行“柔性监管”，相当于变“一刀修”为“边修边扶”","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-056c2a7b789c883b":{"review":{"definition":"材料5中，Y区市场监管局认为，经组织的外卖配送员可以借助日常接触餐饮商家的机会，及时发现并上报食品安全隐患，补充监管力量。","explanation":"Y区执法人员面对的餐饮单位量多面广，配送员可在取餐时发现后厨问题，经“食安宝”提供图文线索，再由处置分队处理。作文可用这项分工论证社会成员如何从理解、配合执法进一步走向主动参与治理。","references":[],"evidence":"完全可以成为食品安全监管的补充力量。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e7db779ad8ea255f":{"review":{"definition":"习近平在党的二十大报告中指出，国家安全是民族复兴的根基，并提出以新安全格局保障新发展格局。","explanation":"报告把国家安全置于民族复兴的基础位置，要求统筹维护和塑造国家安全，夯实国家安全和社会稳定的基层基础。题目问的是二十大报告提出的新观点，C项同时对应这一定位和要求。A项的完善国家安全战略和政策见于十九大报告，B项和D项的相关提法也早于二十大。","references":[],"evidence":"国家安全是民族复兴的根基，要以新安全格局保障新发展格局","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-bffc139321230ea6":{"review":{"definition":"毛泽东在1945年的《论联合政府》中提出，新民主主义的政权组织应采取民主集中制，由各级人民代表大会决定大政方针、选举政府。","explanation":"这篇著作明确说明了由哪个机关决定大政方针、产生政府，具体回答了新民主主义政权如何组织的问题，因此①属于题目所问的制度构想。","references":[],"evidence":"由各级人民代表大会决定大政方针，选举政府","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-9382f8684d89daec":{"review":{"definition":"毛泽东在1940年的《新民主主义论》中提出，建立从全国到乡的各级人民代表大会系统，并由各级代表大会选举政府。","explanation":"文章从政权机关应能代表国家出发，列出了全国、省、县、区、乡的代表大会层级，并说明政府由各级代表大会选举产生。因此③与①同属题目所问的制度构想。","references":[],"evidence":"《新民主主义论》中明确提出“人民代表大会”的构想","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-4f3dad7ca7a325b2":{"review":{"definition":"小沈认为，乡村产业发展能够带来更多经营和合作机会，吸引人才回乡创业，缓解乡村和产业“空心化”。","explanation":"小沈牵头成立的联合社串联地方特色产业，并与农户、企业和创业青年建立合作，为返乡创业提供了可以对接的产业基础。第2题据此把产业发展作为基层政府引才返乡创业的着力点。","references":[],"evidence":"产业发展了，将会产生虹吸效应，吸引更多的人才回乡创业。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-d888a8b1f0ce0f44":{"review":{"definition":"第2题参考答案提出，基层政府可推动地方特色产业向精深加工和配套服务延伸，并以统一品牌组织分散经营主体共同发展。","explanation":"联合社推动本地油茶由卖果、外地代加工发展到本地精炼，并整合种植企业共用“青谷驿”品牌。精炼延伸了加工链条，统一品牌推动经营主体抱团发展。第2题将这两项做法归入做强地方特色产业。","references":[],"evidence":"统一品牌，抱团发展，产业迅速壮大。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-efe28993c57101aa":{"review":{"definition":"第2题参考答案提出，基层政府可提供创业支持，并推动返乡创业项目与地方主导产业深度合作，使创业者、农户和村集体获得增收机会。","explanation":"材料中，小沈已为创业青年黄峰提供土地和大棚并免租五年，体现了降低创业成本的扶持做法。小沈还计划与部分农户在农村金融、统购统销等方面深化合作，并推动村企共建。第2题综合已实施的扶持和拟开展的合作，提出建立利益共享机制。","references":[],"evidence":"在农村金融、产品统购统销等方面深度合作","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-9990eb236615097c":{"review":{"definition":"小沈主张建立稳固的农产品供应链，让农产品对接不同市场，并把市场标准传导到生产和加工环节，以提升农副产品附加值。","explanation":"小沈计划对接外地商会、城市消费市场、机关和学校等渠道，把市场销路与质量要求一并纳入供应链建设。第2题据此提出建立稳固供应链的启示，既要拓宽销路，也要用市场标准推动提质增值。","references":[],"evidence":"让农产品充分对接市场，同时增强农副产品附加值","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-cc5ad6170acc4ada":{"review":{"definition":"第2题参考答案提出，基层可依托本地培训平台开展常态化培训，并与高校合作，定期选送乡土人才深造。","explanation":"小沈的创客中心通过各类活动培训乡土人才，并与华中农业大学乡村振兴研究院合作成立书院，每年从村支书、返乡创业青年和农村党员中选送学员到高校学习。第2题据此提出同时提供本地培训和高校深造机会。","references":[],"evidence":"挑选50人送到华中农业大学去学习","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-856cf9f6bc9bcc84":{"review":{"definition":"参考答案建议绿园社区提前通过社区广播、公告栏、微信公众号等渠道发布第二届集市的时间、地点和活动内容，并让有意报名的居民及时获知招募信息。","explanation":"首届集市的甜点摊主小马直到报名快结束才在公告栏看到招募信息，差点错过。第二届应把招募信息的发布时间往前提，通过线上和线下渠道扩大覆盖，让居民有时间了解活动和报名。","references":[],"evidence":"这次集\n市的报名都快结束了，我才从小区公告栏上看到招募信息，差点就错过了。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-1340c15689b6d56a":{"review":{"definition":"参考答案建议绿园社区教居民使用“友邻有伴”提前发布闲置物品交换信息，并开设面向不同年龄段居民的共享区。","explanation":"首届集市已有家长提前发布交换信息，一名孩子在开市前看中玩具，到现场成功换得。王爷爷也想拿家里的老物件参加，希望增设“老邻居”区。第二届可沿用线上预发布的做法，并把共享区的参与机会扩展到老年居民等群体。","references":[],"evidence":"什么时候\n集市也能有个‘老邻居’区，让我也来体验一把。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-beb9c16f5ed0628c":{"review":{"definition":"参考答案建议绿园社区根据居民反馈保留和丰富特色服务，延续传统便民服务，并按需求调整志愿者人数和服务方式。","explanation":"首届集市的修伞、修鞋等服务解决了居民的日常修补难题。义剪区一上午服务了18人，只有一位志愿者，居民反映排队时间长，还有居民替卧床老人提出上门义剪需求。第二届可增加义剪志愿者，并针对行动不便者安排上门服务。","references":[],"evidence":"只是只有一位师傅，如果以后能多来几位就好了，也省得我们排长队。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-fdfd9f28c52e6107":{"review":{"definition":"参考答案建议绿园社区培训负责民政政策答疑的社工，增加现场咨询人员，并根据首届发放情况估算第二届宣传手册的需求量。","explanation":"首届居民集中咨询困境儿童家庭求助、区社会福利院入住申请等事项，带来的50本手册很快发完。培训对应答疑质量，增配人员和估算手册用量分别回应现场咨询与资料领取的需求。","references":[],"evidence":"我们带来的50本宣传手册一会儿就发完了。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-75d75e6de6b6dc26":{"review":{"definition":"参考答案建议绿园社区保留微心愿公益捐款专区，继续收集困难居民的心愿，公示捐款的具体用途，并邀请居民代表监督捐款使用。","explanation":"首届集市前，社区摸排收集了50多个困难居民的微心愿。马大姐捐款后想知道钱花在了哪里，第二届据此可通过公示让捐款人了解资金去向，并让居民代表监督实际使用情况。","references":[],"evidence":"捐一块钱不是啥大事，但用在了哪里，我们也不知道啊！","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-c65fe05a5d36adb1":{"review":{"definition":"驻村第一书记小高将泉石村的人才工作概括为坚持党建引领，通过培养乡土人才、吸引外出能人返乡和建设创业平台，推动人才成长与产业发展相互带动。","explanation":"材料中，青年创业党支部书记小王带领年轻人组建合作社、成立农创园，园区又为小刘等青年提供创业机会。发言稿可用这一来一往的关系说明，基层组织怎样让青年参与产业发展，并借助产业平台为更多青年创造机会。","references":[],"evidence":"开创了产才融合的泉石村人才工作新格局。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-dbf38603f83f9ff9":{"review":{"definition":"参考发言稿把老干部带领青年走访群众、让青年参与村级事务，作为泉石村培养青年干部的经验。","explanation":"返乡的小叶跟随老支书万书记走田头、访农户、解民忧，逐步熟悉村情并得到村民认可。她于2020年当选村委会主任，后来承担产业项目相关手续的协调工作。发言稿可据此说明青年如何从跟随老干部学习走向承担村务。","references":[],"evidence":"跟着万书记走田\n头、访农户、解民忧","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-ffbae083cd5c9682":{"review":{"definition":"参考发言稿建议用泉石村的实践说明，村两委可以把青年的专业特长与村务需要对接，让青年在适合的岗位上发挥作用。","explanation":"乡村振兴专员小于起初不熟悉村情民情。村两委发挥他的计算机专长，安排他到村数字服务中心工作。2022年9月，泉石村社会治理现代化综合平台上线，老年人补贴发放和低保人员统计可在线处理。这一事例为发言稿中的搭平台、量才而用提供了具体成效。","references":[],"evidence":"发挥他计算机专业的特长，安排\n他投入到村数字服务中心的工作中。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-48466581c707c33c":{"review":{"definition":"参考发言稿将整合资源列为泉石村扶持青年创业的经验。材料中的农创园提供低成本场地和技术协调，乡村振兴综合体内的电商项目另有工位和补贴安排。","explanation":"小刘原先面临建棚投入至少十几万元和经验不足的问题，入驻农创园后以每年1万元租用大棚，由村青年创业党支部协调解决技术难题。小杨团队则计划向有创业意愿的大学毕业生免费提供工位，特别困难者可获1万元补贴。发言稿可用两个事例说明不同平台如何回应创业初期的困难。","references":[],"evidence":"一个大棚一年租金只需1万元，还有村青年创业党支部协调解决技术难题。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-da0e423a9d233834":{"review":{"definition":"材料1中的视障研究生小梁认为，公众更多了解阅读障碍者的特殊需求，有助于相关服务和设施获得支持，增加残障人士参与文化生活和融入社会的机会。","explanation":"材料以《马拉喀什条约》生效实施后的经历呈现这类收获。阿克苏盲童在杭州图书馆的视障阅览室找到了喜欢的书，也参加了文化体验和交流。归纳时可写出需求得到更多关注、读者获得无障碍资源并享受阅读、文化参与促进社会融入这几层收获。","references":[],"evidence":"文化体验和交流活动","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-32f76bad4e062125":{"review":{"definition":"参考答案所说的阅读跨界延伸，指公众通过实地参观文博场馆和数字化体验接触历史文化，从场馆及其展示内容中获得文化滋养。","explanation":"本题要求对应群体、方式和收获。此处的群体是关注文博场馆的公众，方式是实地参观和数字化体验，收获是加深对历史文化的体验，满足文化滋养需求。","references":[],"evidence":"参观和数字化体验历史文化，实现了阅读的跨界延伸","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-556cded86ddda45b":{"review":{"definition":"申论材料三以盐城龙冈镇的有声图书馆和扬州的城市书房为例，说明扫码听书和家门口阅读如何让居民更方便地使用公共阅读服务。","explanation":"龙冈镇居民用手机扫码即可在线收听，缓解了老年人借书不便、看书费力的问题。扬州市民小倪就近使用城市书房，书目常更新，志愿者也会收集需求，她逐渐养成了每天学习两小时的习惯。这两例对应本题对老年人和社区居民阅读方式及收获的归纳。","references":[{"source":"web-8e074b52c538f532","location":"第2页，材料三第1段","quote":"无需下载任何软件"},{"source":"web-8e074b52c538f532","location":"第2页，材料三第3段","quote":"家门口的城市书房"}],"evidence":"享受便捷舒适阅读服务，提升阅读新鲜感和吸引力，改变日常生活","disposition":"题内说明","basis":"据原题与所列资料编释。"}},"k-18e801133ea5f58b":{"review":{"definition":"申论材料四以有声特色航班、听书APP、播客和短视频讲书为例，说明阅读和信息获取方式如何随数字媒介而拓展。","explanation":"旅客能在飞行途中听书，家长能边做家务边听书，播客听众能利用零碎时间获取新闻和话题。材料中的孙女士用读书短视频初步了解新书、判断是否值得细读，也借他人的见解加深对已读作品的理解。本题归纳时，碎片时间的利用主要对应听书和播客，短视频案例主要说明选书和理解作品的便利。","references":[{"source":"web-8e074b52c538f532","location":"第3页，材料四听书APP段","quote":"人们通过播客获取新闻热点"},{"source":"web-8e074b52c538f532","location":"第3页，材料四短视频讲书段","quote":"听听别人对作品的见解，加深理解"}],"evidence":"高效利用碎片化时间，获取新闻热点、高价值话题和信息，丰富了阅读方式，激发阅读热情","disposition":"题内说明","basis":"据原题与所列资料编释。"}},"k-6253dd617cc2760b":{"review":{"definition":"材料6中的实体书店负责人小蔚认为，直播售书一味追求低价可能扰乱图书的正常流通。她以直播渠道出现低价盗版书为例，说明其中的风险。","explanation":"题目要求归纳阅读推销涉及的问题。材料把过度低价放在直播销售模式中讨论，并举出低价盗版书这一具体例子，可用于分析促销方式和图书流通面临的问题。低价与盗版是两个判断，售价本身不足以确定图书是否侵权。","references":[],"evidence":"一味低价破坏了商品的正常流通","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-9c740739994c2e6b":{"review":{"definition":"本题参考答案主张，公益性阅读推广可以借鉴图书营销扩大活动影响，图书推销应重视选书质量和图书的文化内涵。","explanation":"这一建议对应题目要求分析的两类问题。阅读推广可借鉴直播、短视频等传播形式，让更多人接触活动。图书推销可借鉴董主播介绍《苏东坡传》的做法，通过讲述苏轼的经历帮助读者了解作品，再引导购书。","references":[],"evidence":"阅读推销也应注重图书质量与文化内涵","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-b7eb41738f0894fb":{"review":{"definition":"材料7中，J省文旅厅机关党委陈书记认为，党员干部带头读书形成的示范效应，是引领全民阅读的重要力量。","explanation":"陈书记提到文旅厅每年组织“书香支部 品质阅读”活动，并通过评选阅读案例、发布书单展示读书成果。点评紫金图书馆案例时，可以据此说明支部读书活动具有带动他人阅读的价值。材料中的示范作用指向系列活动，单次主题党日的群众触达情况仍需依据该案例判断。","references":[],"evidence":"已成为引领全民阅读的重要力量","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-23ca9982fb801827":{"review":{"definition":"针对紫金图书馆主题党日案例，参考答案建议通过跨部门联办和动员全体工作人员扩大参与范围，借助融媒体扩大活动成果的传播范围。","explanation":"材料7明确写明全体党员干部参加活动，诗词品评由青年党员代表分享。参考答案中“参与主体仅有青年人”与整场活动的人员范围冲突。点评时可围绕拓宽分享人员和部门范围提出联办建议，并建议通过融媒体将活动成果传播到更多读者。","references":[],"evidence":"并利用融媒体积极推广活动成果","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-0f94b35ea73dc683":{"review":{"definition":"习近平总书记在致首届全民阅读大会的贺信中，希望广大党员、干部带头读书学习，修身养志、增长才干，希望孩子们养成阅读习惯、快乐阅读、健康成长，希望全社会共同参与，形成爱读书、读好书、善读书的浓厚氛围。","explanation":"材料8的贺信是题干指定的立论依据。党员、干部带头读书体现示范作用，孩子养成阅读习惯体现阅读对成长的价值，全社会共同参与则把个人阅读拓展为社会风尚。这三层倡导把题设中的“拓展人生”和“引领未来”联系起来。","references":[],"evidence":"形成爱读书、读好书、善读书的浓厚氛围","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-adb11b1be2d2966e":{"review":{"definition":"参考文章认为，坚持阅读能够积累知识、涵养品格、增长才干，使人更好地认识世界、理解人生。","explanation":"这一分论点回应“诗书满腹拓展人生”。范文用“书犹药也，善读之可以医愚”说明阅读可以增长见识，再借材料8中党员、干部读书学习以“修身养志，增长才干”的倡导，把论证推进到品格和能力的提升。","references":[],"evidence":"阅读塑造个体精神风貌，提升国民综合素质。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-c4b7f218db8900c1":{"review":{"definition":"参考文章认为，广泛而深入的阅读有助于人们理解本土文化的内涵和价值，进而增进文化认同、坚定文化自信。","explanation":"这一分论点回应“全民阅读引领未来”。范文先说明阅读如何促成理解，再说明理解如何转化为认同感和自豪感，最后把民众文化认同的积累联系到国家文化软实力。其论证呼应了材料8关于读书氛围愈发浓厚、文化自信更加坚定的表述。","references":[],"evidence":"从而在内心深处生发出对本土文化的强烈认同感和自豪感","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-dabbc9a560df0b63":{"review":{"definition":"人口规模巨大是中国式现代化的显著特征。习近平总书记在《中国式现代化是强国建设、民族复兴的康庄大道》中指出，中国14亿多人口整体迈入现代化，是人类历史上规模最大、难度最大的现代化。","explanation":"人口规模影响现代化的具体任务、艰巨程度和推进方式。题干承认各国现代化有共同特征，①却由此断言任务相同，忽略了人口规模带来的任务差异。②对应原文关于推进难度的判断。","references":[],"evidence":"人口规模不同，现代化的任务就不同","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-fb1ce1e7a6289679":{"review":{"title":"中国式现代化的独立自主与和平发展","type":"观点与论证","definition":"中国式现代化坚持从本国国情出发，自主选择发展道路，并在维护世界和平与发展中谋求自身发展。","explanation":"党的二十大报告将走和平发展道路列为中国式现代化的中国特色之一。题解所引《中国式现代化是强国建设、民族复兴的康庄大道》进一步说明，中国式现代化依靠自身力量发展，将激发内生动力与和平利用外部资源相结合，并以自身发展促进世界和平与发展。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"中国式现代化的中国特色、独立自主"}],"related":["k-1654a31f6370d6b4"],"examFocus":{"江苏 2024 A类 行测#1":"辨析现代化的共同特征与具体任务之间的关系，并分别核对有关推进难度、发展道路和文明意义的表述。"}},"readings":[{"origin":"k-fb1ce1e7a6289679","title":"中国式现代化的独立自主与和平发展","qs":["江苏 2024 A类 行测#1","江苏 2024 C类 行测#1"],"definition":"中国式现代化坚持从本国国情出发，自主选择发展道路，并在维护世界和平与发展中谋求自身发展。","explanation":"党的二十大报告将走和平发展道路列为中国式现代化的中国特色之一。题解所引《中国式现代化是强国建设、民族复兴的康庄大道》进一步说明，中国式现代化依靠自身力量发展，将激发内生动力与和平利用外部资源相结合，并以自身发展促进世界和平与发展。","evidence":"","doubt":"","references":[{"source":"twenty","location":"中国式现代化的中国特色、独立自主"}]},{"origin":"k-ba9d12de5007079c","title":"中国式现代化的独立自主与和平发展","qs":["江苏 2024 B类 行测#1"],"definition":"中国式现代化坚持独立自主、自力更生，依靠人民的劳动和创新增强内生动力，并通过和平利用外部资源实现发展。","explanation":"独立自主说明发展的立足点，和平发展说明谋求自身发展的道路。解析指出，中国在维护世界和平与发展中谋求自身发展，并以自身发展促进世界和平与发展，因此两者可以同时成立，③正确。","evidence":"是独立自主、和平发展的现代化","doubt":"","references":[]}],"aspects":[{"title":"独立自主与和平发展的判断","uses":[{"unit":"Q1","role":"直接考查","use":"③同时概括独立自主和走和平发展道路，表述正确。题解以人口规模说明现代化任务因国情而异，判①错误、②正确。④对应党的二十大报告提出的创造人类文明新形态，故选②③④（D）。","evidence":"是独立自主、和平发展的现代化","qids":["江苏 2024 A类 行测#1","江苏 2024 C类 行测#1"]}]}]},"k-6e072ace017bc8e0":{"review":{"definition":"魏源认为，强求人去做能力所不及的事，事情难以办成。以法令禁止人们必然会做的事，法令也难以施行。","explanation":"魏源用“所不能”和“所必犯”指出法令能否施行取决于它是否顾及人的实际能力和行为。A项强调法律应当顾及天理人情，与这一主张最接近。B项讲法律如何塑造习惯，C项讲国家强制力如何保障法律实施，D项讲法律效力对合法事物的支撑。","references":[],"evidence":"强人之所不能，事必不立；禁人之所必犯，法必不行。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-3fe7f02eab88ce74":{"review":{"definition":"材料5中，市交通运输局法制科秦科长主张，执法人员即使面对处罚规定笼统、情节分档指引不足等困难，也应从严约束自身用权。","explanation":"秦科长指出，有的文件给出的处罚幅度过宽，有的以“情节严重”分档却缺少判定指引。老韩案则显示，规则缝隙可能被经办人利用来加重处罚。本题可据此说明“紧箍咒”也包括执法人员的自我约束，作出裁量时应以案情和适用规则为依据。","references":[],"evidence":"我们首先应该刀刃向内，从严要求自己","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-315c405c1171788a":{"review":{"definition":"参考倡议书主张，网络主播应诚信经营、遵循公序良俗，利用网络直播传递社会主义核心价值观。","explanation":"材料6中的行业专家指出，消费者在直播中处于被动接受的地位，主播借自身影响力进行虚假宣传可能误导消费者、造成损失，还可能违背公序良俗。参考答案据此在依法经营和从业自律之外，提出“传播正确价值观念”的倡议。","references":[],"evidence":"网络主播应诚信经营，遵循公序良俗，传递社会主义核心价值观。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-2faed307aa6ebc0e":{"review":{"definition":"材料7认为，健全行政执法机构运行规范、提升执法人员全面素质，是发挥科技和创新作用、提高行政执法效能的基础。","explanation":"范文用明确执法细则和处罚幅度说明规范如何为执法提供依据，用分级分类培训、持证上岗和畅通投诉渠道说明如何提升履职能力、加强监督。这一层论证回答了题句中的“加分”和“乘效”建立在什么基础上。","references":[],"evidence":"进一步提升执法人员全面素质的基础上","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-5eaf18f960b8c1c2":{"review":{"definition":"材料7主张将科技手段用于巡查、监管和案情研判，提高发现问题、掌握情况和研判线索的能力，进而提升行政执法效能和监管水平。","explanation":"这对应题句中的“用智慧给执法‘加分’”。范文以南京交通执法部门在高淳区部署无人机机场为例，说明科技手段能帮助执法人员及时掌握航道动态、发现违法行为。","references":[],"evidence":"以科技赋能提升执法工作效能和监管水平","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-8d95dd8e7a7c64c6":{"review":{"definition":"范文将“以创新促执法‘乘效’”理解为同步推进执法理念、体制、协作和监督等方面的改革，共同提升执法质量和效能。","explanation":"清理交叉重复的执法事项可以减少职责重叠，推进乡镇和街道赋权可以调整基层执法权限，完善执法协作和监督可以改善衔接与约束。范文用这些举措说明“乘效”所指的多方面改革协同作用。","references":[],"evidence":"提升执法质量及效能，需要全方位、多层次、多领域的创新","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-989683f65e31ef0d":{"review":{"definition":"本题采用D项的法理观点，即法律价值以人的利益为基础，秩序是法律通过规范行为、分配责任来保障人的利益的一种工具性价值。","explanation":"题干把特定事故情形下原先由有过失的行人负全责，改为无过错的机动车一方也分担部分责任。这体现了法律通过明确事故责任来维持交通秩序，并在责任分配中考虑对行人利益的保护。C项同时强调约束和限制公共权力，题干没有涉及公共权力的行使，因此D项与题设最贴合。","references":[],"evidence":"法律价值的基础是人，秩序是法律的工具性价值","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-2ad200a078c2b16d":{"review":{"definition":"在参考发言稿中，小范认为，村干部应准确理解农村政策，把政策要求落实到村里的具体工作中。","explanation":"H市委党校任教授解读时事政策、展望农村发展趋势，让小范对乡村发展更有信心。薛教授围绕发展壮大新型农村经济作专题讲解，加深了他对农村政策的理解。发言稿据此把学懂政策、坚定发展信心作为带头人的第一项培训体会，并提出通过研讨会、专家讲座等方式继续学习。","references":[],"evidence":"准确领会政策精神，才能善于用政策推动工作。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-2c8bf686cee3476d":{"review":{"definition":"小范从M村的经验中提出，村干部可以根据本村的资源条件选择产业，再结合产品销售需要培养本村电商人才、拓展销路。","explanation":"M村耕地少、林业资源丰富，宋书记因此把林下种植和养殖作为产业突破口，再通过培养本村电商人才、直播带货解决销售问题。K村条件相似，小范在发言稿中借这一案例反思以往发展产业时的畏难，提出按本村条件选产业、尝试新的销售方式。","references":[],"evidence":"宋书记通过多种方式培养了一批本村的电商人才，甚至亲自上阵直播带货。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-668d770e706f2449":{"review":{"definition":"小范提出，K村可以利用本村已有的吊瓜种植基础，与有意向外拓展种植基地的Q村商谈合作，争取接入吊瓜产业链。","explanation":"Q村已组织种植户与食品公司、合作社联盟，把种植、加工和展销连成一条产业链。K村也产吊瓜，正好可以对接Q村拓展种植基地的需求。发言稿用这两项条件把P村钟书记提出的优势互补、抱团发展落成一项可在联席会上商议的设想。","references":[],"evidence":"我们村可以与Q村合作，优势互补，互通有无，抱团发展","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-c6bbe8d821b669bc":{"review":{"definition":"S村贾书记主张，美丽乡村建设应因地制宜，发掘各村独特的传统文化资源，形成各具特色的乡村风貌。","explanation":"各村的传统文化资源有差异，从本村独有的资源出发，才能体现贾书记所说的“千村千貌”。参考发言稿把这一观点用于K村的发展设想，提出发掘本地传统文化资源，避免形成雷同的项目或风貌。","references":[],"evidence":"挖掘本地独特的传统文化资源，因地制宜，避免同质化发展。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-00cc3e449f4f01cb":{"review":{"definition":"小范在参考发言稿中提出，村级组织可以借助新媒体创新活动，吸引优秀青年参与，并通过培训提升青年和村“两委”干部做群众工作的能力。","explanation":"引才的建议来自R村林书记，他认为结合新媒体开展活动能吸引青年、增强组织活力。育才的建议来自小范在沟通课上的角色扮演体验，他发现同一件事的不同说法会引起群众不同的反应。发言稿据此提出在培训中重视语言沟通，把吸引人才和提升人才能力落实到基层组织建设中。","references":[],"evidence":"年轻人、村两委干部做群众工作的能力，尤其要注重语言沟通","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-249172c9fdc77571":{"review":{"definition":"习近平在《中国式现代化是强国建设、民族复兴的康庄大道》中指出，人口规模巨大是中国式现代化的显著特征，人口规模会影响现代化的任务、难度和推进方式。","explanation":"文章以中国14亿多人口整体迈入现代化、规模超过当时发达国家人口总和为依据，指出这是人类历史上规模最大、难度最大的现代化。题干说各国现代化具有共同特征，①却由此表述为任务相同，因而错误。②符合文章对难度的判断，与正确的③④组成D项。","references":[],"evidence":"人口规模不同，现代化的任务就不同","disposition":"独立词条","basis":"据原题和解析编释。","title":"人口规模巨大的现代化","related":[],"examFocus":{"江苏 2024 B类 行测#1":"辨析现代化的共同特征与具体任务之间的关系，并核对有关中国式现代化难度、发展道路和文明形态的表述。"}},"readings":[{"origin":"k-249172c9fdc77571","title":"人口规模巨大的现代化","qs":["江苏 2024 C类 行测#1"],"definition":"习近平在《中国式现代化是强国建设、民族复兴的康庄大道》中指出，人口规模巨大是中国式现代化的显著特征，人口规模会影响现代化的任务、难度和推进方式。","explanation":"文章以中国14亿多人口整体迈入现代化、规模超过当时发达国家人口总和为依据，指出这是人类历史上规模最大、难度最大的现代化。题干说各国现代化具有共同特征，①却由此表述为任务相同，因而错误。②符合文章对难度的判断，与正确的③④组成D项。","evidence":"人口规模不同，现代化的任务就不同","doubt":"","references":[]},{"origin":"k-8b2ecc540685a36d","title":"人口规模巨大的现代化","qs":["江苏 2024 B类 行测#1"],"definition":"人口规模巨大是中国式现代化的显著特征。超大规模人口整体迈入现代化，使发展任务、艰巨程度和推进方式具有自身特点。","explanation":"解析引述习近平总书记的文章，以中国人口整体迈入现代化所涉及的规模说明其复杂性和艰巨性，并以“也是难度最大的现代化”支持②。题干说各国现代化有共同特征，①却将这一点延伸为现代化任务相同，而解析明确指出人口规模不同，现代化的任务也不同。","evidence":"规模最大的现代化，也是难度最大的现代化","doubt":"","references":[]}]},"k-90aac7b0cf5638bf":{"review":{"definition":"习近平在2023年全国生态环境保护大会讲话中提出，从生态系统整体出发，统筹山、水、林、田、湖、草、沙等相互联系的生态要素，协同开展保护和治理。","explanation":"讲话在总结新时代生态文明建设成就时，把这项统筹工作列为治理水平提高的具体实践，支持本题将②纳入正确组合。②的“实现了”比原文更强。讲话用“实现”表述的是从重点整治到系统治理的重大转变，并在部署后续工作时再次要求坚持一体化保护和系统治理。","references":[{"source":"web-263b22cbd31c8c79","location":"第一部分，新时代生态文明建设成就","quote":"实现由重点整治到系统治理的重大转变"},{"source":"web-263b22cbd31c8c79","location":"第一部分，重点整治向系统治理转变段","quote":"统筹山水林田湖草沙一体化保护和系统治理"}],"evidence":"要坚持山水林田湖草沙一体化保护和系统治理","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"k-38d0c7ebefab41b7":{"review":{"definition":"题目解析在总结浙江“千村示范、万村整治”工程实施20年的经验时，将该工程视为建设美丽中国的实践源头和先行先试样板。","explanation":"浙江将农村人居环境整治与生态文明建设结合，并以美丽乡村建设行动计划提升“千万工程”。①所说的“实践源头和样板”具体指这条从村庄环境整治发展到美丽乡村建设的先行路径。","references":[],"evidence":"“千万工程”成为建设美丽中国的实践源头。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-42c6e29baecc817a":{"review":{"definition":"题目解析认为，浙江“千万工程”通过改善农村人居环境、促进生态农业和低碳乡村发展，推动“绿水青山就是金山银山”理念落地。","explanation":"改善人居环境体现生态保护，发展生态农业和低碳乡村体现把生态要求落实到乡村发展中。③所说的“从理念变为现实”指这些乡村实践，由此可以判断③正确。","references":[],"evidence":"持续改善农村人居环境，促进生态农\n业、低碳乡村发展","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-499a82f88d123ffd":{"review":{"definition":"题目解析认为，浙江“千万工程”通过统筹村庄整治与经营转变农村发展方式，并通过城市基础设施和公共服务向农村延伸，推动形成城乡融合发展新机制。","explanation":"发展方式转变体现在把改善村容村貌同发展生产、增加农民收入结合起来，城乡融合体现在城市基础设施向农村延伸、公共服务向农村覆盖。这两方面共同支持④。②所称实现全体人民共同富裕超出了这些成效，题中援引的党的二十大报告将共同富裕视为长期历史过程。","references":[],"evidence":"把改善村容村貌与发展生产、富裕农民结合起来","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-cfe14056117fab02":{"review":{"definition":"材料5中，B城所在省的文旅厅负责人认为，冰雪是B城吸引游客的独特资源，文旅项目和服务应随游客需求和反馈及时调整。","explanation":"B城为冰雪游提前准备了一年，按游客需求增设人造月亮等体验，发现游客长时间排队后退票并连夜整改。第2题可将这些做法归纳为依托地方特色提前策划、持续丰富体验、及时解决服务问题，用来说明城市怎样把短期关注转化为较稳定的旅游吸引力。","references":[],"evidence":"哪里不满意我们就调整哪里，需要什么我们就上什么。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-093f5d7950aff988":{"review":{"definition":"材料5中的行业专家认为，烧烤的消费形式相对单一，游客的好奇心得到满足后，消费热情难以持续。第2题参考答案据此主张丰富消费形式。","explanation":"Z城烧烤凭独特吃法走红，烧烤专列等服务承接了初期客流。一年后，走访团队发现不少商家改卖类似的网红小吃，新开的网红店客流已很少。第2题可肯定创意和服务对吸引客流的作用，再用同质化现象说明持续更新消费体验的必要性。","references":[],"evidence":"消费形式相对单一，当人\n们的好奇心得到满足后，很难持续保持热情。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-591c9a3f5e669854":{"review":{"definition":"第2题参考答案根据H南站走红后的情况提出，城市利用个人IP带动文旅时，应规划直播及相关活动的时段和地点，兼顾居民生活与周边学校的教学、考试环境。","explanation":"H城连夜修路并安排志愿者服务来访者。随后，主播集中到附近有学校和居民小区的H南站，给居民生活带来困扰。当地文旅部门为保障集中考试期间的学习、生活和考试环境，公告H南站停止举办文娱活动。第2题可据此说明，现场服务之外还需事先考虑客流聚集对周边的影响。","references":[],"evidence":"合理规划个人IP的直播时间、地点，兼顾好群众生活","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-14904db90fed24d2":{"review":{"definition":"范文主张，通过政策支持和知识产权等公共服务改善文创企业的发展环境，为人才、资金等创新要素集聚创造条件。","explanation":"范文借扬州广陵区打造“大运河青年文创”品牌、构建“运河青创”生态体系和发布版权服务平台的做法，论证产业扶持与权益保障如何支持持续创新。材料6记载了这些具体做法及产业集聚态势，资金集聚是范文据此阐述的预期作用。","references":[],"evidence":"文化创新创造需要政策扶持和服务保障，从而实现人才、资金等要素的集聚","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-323c69b0fbf04c9f":{"review":{"definition":"材料7提出，文化创新有助于把全社会的智慧和力量凝聚到创新发展上来，为全面建设社会主义现代化国家、全面推进中华民族伟大复兴提供精神力量。","explanation":"材料以习近平总书记“要着力激发全民族文化创新创造活力”的指示引出文化使命，并指出创新是新质生产力的主要特征和内在要求。申论第4题可沿着凝聚社会创新力量这一思路，将文化创新对经济发展的作用与文化创造助力奋进新征程联系起来。","references":[],"evidence":"为全面建设社会主义现代化国家、全面推进中华民族伟大复兴提供强大精神力量","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-57505e0285e71637":{"review":{"title":"习近平新时代中国特色社会主义思想的历史地位","type":"观点与论证","definition":"2022年修改的《中国共产党章程》总纲将习近平新时代中国特色社会主义思想定位为当代中国马克思主义、二十一世纪马克思主义，是中华文化和中国精神的时代精华，是全党全国人民为实现中华民族伟大复兴而奋斗的行动指南。","explanation":"这一思想继承和发展了马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观。“两个结合”是指把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合。","basis":"据关联原题及所列出处编释。","references":[{"source":"charter","location":"总纲"}],"examFocus":{"江苏 2025 A类 行测#1":"区分习近平新时代中国特色社会主义思想的理论来源、历史定位与行动指导作用，并核对改革举措的时代归属。"}},"aspects":[{"title":"理论继承、时代精华与行动指南","uses":[{"unit":"Q1","role":"直接考查","use":"①考查理论继承和发展，②考查“两个结合”与时代精华的定位，④考查行动指南的定位。③把社会主义市场经济体制改革目标和基本构架的确立归到这一思想名下，故排除③，选B（①②④）。","evidence":"开辟了马克思主义中国化时代化的新境界","qids":["江苏 2025 A类 行测#1","江苏 2025 B类 行测#1"]}]}]},"k-7fd05bb3df5eefd0":{"review":{"title":"文化典籍与中华文明连续性","type":"观点与论证","definition":"题解援引的《习近平总书记这样谈中华文明的连续性》认为，代代相传的文化典籍记载并传承中华文明，是中华文明连续性的载体。","explanation":"典籍保存前人的思想和知识，后世可以通过研读接续传承。题解以四书五经长期作为儒家学子的研学之书为例，说明这种传承如何延续。","basis":"据关联原题和解析编释。","references":[],"related":["k-48600709a9e1da31"],"domain":"文化","examFocus":{"江苏 2025 A类 行测#4":"辨析文化典籍、文化主体性、地理环境和文化价值诉求与中华文明连续性的关系。"}},"readings":[{"origin":"k-7fd05bb3df5eefd0","title":"文化典籍与中华文明连续性","qs":["江苏 2025 A类 行测#4","江苏 2025 B类 行测#4"],"definition":"题解援引的《习近平总书记这样谈中华文明的连续性》认为，代代相传的文化典籍记载并传承中华文明，是中华文明连续性的载体。","explanation":"典籍保存前人的思想和知识，后世可以通过研读接续传承。题解以四书五经长期作为儒家学子的研学之书为例，说明这种传承如何延续。","evidence":"","doubt":"","references":[]},{"origin":"k-a57327d399b8d97b","title":"文化典籍与中华文明连续性","qs":["江苏 2025 C类 行测#4"],"definition":"材料《习近平总书记这样谈中华文明的连续性》指出，代代相传的文化典籍记载并传承中华文明。题中②据此把文化典籍概括为中华文明连续性的天然载体。","explanation":"材料以四书五经为例，说明儒家典籍在历代学子的研读中持续传播。典籍保存文化内容，世代研读使这些内容得以传承，两者共同解释了②所说的载体作用。","evidence":"中华文明在这些代代相传的典籍中得以记载和传承","doubt":"","references":[]}],"aspects":[{"title":"典籍的记载与传承作用","uses":[{"unit":"Q1","role":"直接考查","use":"本题考查文化典籍在解释中华文明连续性时承担的作用。判断②将典籍定位为传承载体，列入正确组合②③④，答案为D。","evidence":"浩如烟海的文化典籍成为中华文明连续性的天然载体","qids":["江苏 2025 A类 行测#4","江苏 2025 B类 行测#4"]}]}]},"k-48600709a9e1da31":{"review":{"title":"地理环境与中华文明连续性","type":"观点与论证","definition":"题解援引的《连续性：中华文明的首要特性》将独特而稳定的地理环境视为中华文明得以长期延续的自然基础。","explanation":"这一观点从地理、气候等自然条件解释文明持续发展的依托。题解还从文化典籍的传承作用和“中和”的价值诉求解释中华文明的连续性。","basis":"据关联原题和解析编释。","references":[],"related":["k-7fd05bb3df5eefd0"],"domain":"文化","examFocus":{"江苏 2025 A类 行测#4":"区分地理环境、典籍和文化价值在中华文明延续中的不同作用。"}},"aspects":[{"title":"地理环境提供自然基础","uses":[{"unit":"Q1","role":"直接考查","use":"本题考查独特而稳定的地理环境在中华文明延续中的作用。判断③将其归为自然基础，列入正确组合②③④，答案为D。","evidence":"独特又稳定的地理环境，筑牢了中华文明连续性的自然基础","qids":["江苏 2025 A类 行测#4","江苏 2025 B类 行测#4","江苏 2025 C类 行测#4"]}]}]},"k-f795fba68c6b4a1f":{"review":{"definition":"《连续性：中华文明的首要特性》认为，“中和”强调把握适当限度，使事物双方相辅相成、共生共存。这种价值诉求奠定了中华文明源远流长的价值底蕴。","explanation":"该文以“贵和持中、自强不息”概括这一价值取向所塑造的文明品格。题中④据此把“中和”归入文明延续的价值因素，②的典籍和③的地理环境则分别对应传承载体和自然基础。","references":[],"evidence":"中华文化“中和”的文化价值诉求奠定了中华文明连续性的价值底蕴","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8d04c887403a48a9":{"review":{"definition":"习近平在《促进高质量充分就业》中指出，高质量充分就业是一项高要求，需要循序渐进，必须尽力而为、量力而行。","explanation":"文章把充分的就业机会、公平的就业环境等列为宏观要求，把工作稳定、收入合理等列为劳动者层面的表现。推进这一目标要立足现实条件，同时调动人民群众的积极性、主动性、创造性，引导大家依靠努力奋斗创造幸福生活。题中③对应这一推进要求，②则把微观层面的表述主体由“劳动者”换成了“每个公民”，超出原文的主体范围。","references":[],"evidence":"高质量充分就业是一个很高的要求，也是一个循序渐进的过程，必须尽力而为、量力而行","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c14a40d8475a7a29":{"review":{"definition":"最高人民法院在2024年2月27日的新闻发布会上指出，人民法院案例库有助于促进法律正确、统一适用，深化诉源治理，优化司法公开并提升法官司法能力。","explanation":"典型参考案例为法官处理类似案件提供可参照的裁判思路，帮助提升司法能力、统一法律适用，也让公众可以查阅并了解裁判依据，对应②③④。①“强化司法权威”没有列入题中解析援引的发布会表述，本题据此选D。","references":[],"evidence":"建设人民法院案例库是提升法官司法能力的有效途径。","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c1f2385351b04611":{"review":{"definition":"“两个结合”是把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合。党的创新理论在这一过程中汲取中华优秀传统文化的思想资源，体现中华文化和中国精神的时代精华。","explanation":"第1题②以马克思主义为魂脉、中华优秀传统文化为根脉，说明二者贯通能够推动中华文化创造性转化、创新性发展，并用这一关系说明习近平新时代中国特色社会主义思想的历史地位。因此②入选。","references":[],"evidence":"使马克思主义这个魂脉和中华优秀传统文化这个根脉内在贯通、相互成就","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c9892a395b5fe585":{"review":{"definition":"习近平新时代中国特色社会主义思想是全党全国各族人民为实现中华民族伟大复兴而奋斗的行动指南，是新时代党和国家事业发展的根本遵循。","explanation":"第1题④所说的行动指南指向实现中华民族伟大复兴这一奋斗目标，根本遵循指这一思想对新时代党和国家事业的指导作用。题干列举的建设社会主义现代化强国、建设长期执政的马克思主义政党，就是这一思想所回答的重大时代课题，④入选。","references":[],"evidence":"是全党全国各族人民为实现中华民族伟大复兴而奋斗的行动指南","disposition":"独立词条","basis":"据原题和解析编释。","title":"习近平新时代中国特色社会主义思想的指导地位","related":[],"examFocus":{"江苏 2025 A类 行测#1":"辨析习近平新时代中国特色社会主义思想在理论发展、文化传承和治国理政中的定位，并核对各项改革部署的历史归属。"}},"readings":[{"origin":"k-c9892a395b5fe585","title":"习近平新时代中国特色社会主义思想的指导地位","qs":["江苏 2025 B类 行测#1"],"definition":"习近平新时代中国特色社会主义思想是全党全国各族人民为实现中华民族伟大复兴而奋斗的行动指南，是新时代党和国家事业发展的根本遵循。","explanation":"第1题④所说的行动指南指向实现中华民族伟大复兴这一奋斗目标，根本遵循指这一思想对新时代党和国家事业的指导作用。题干列举的建设社会主义现代化强国、建设长期执政的马克思主义政党，就是这一思想所回答的重大时代课题，④入选。","evidence":"是全党全国各族人民为实现中华民族伟大复兴而奋斗的行动指南","doubt":"","references":[]},{"origin":"k-dc9ec4790edea344","title":"习近平新时代中国特色社会主义思想的指导地位","qs":["江苏 2025 A类 行测#1"],"definition":"习近平新时代中国特色社会主义思想是全党全国各族人民为实现中华民族伟大复兴而奋斗的行动指南，是新时代党和国家发展事业的根本遵循。","explanation":"行测第1题的④用“行动指南”和“根本遵循”概括这一思想对民族复兴实践和新时代党和国家事业的指导地位，因此正确。③把社会主义市场经济体制改革目标和基本构架的最初确立归到这一思想名下，混淆了不同历史阶段的贡献。正确组合为①②④，选B。","evidence":"为实现中华民族伟大复兴而奋斗的行动指南，是新时代党和国家发展事业的根本遵循","doubt":"","references":[]}]},"k-114c26de8ce46fdd":{"review":{"definition":"《连续性：中华文明的首要特性》认为，“中和”强调把握适当限度、促进事物双方相辅相成与共生共存，这种价值取向为中华文明的延续奠定了价值底蕴。","explanation":"第4题④对应材料所说的贵和持中，解释的是文明延续背后的价值取向。②的文化典籍承担记载和传承的功能，③的地理环境提供自然条件。三项分别说明价值底蕴、传承载体和自然基础。","references":[],"evidence":"中华文化“中和”的文化价值诉求奠定了中华文明连续性的价值底蕴","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-8c2a0d7d6f10b357":{"review":{"definition":"王学斌在《中华文明源远流长的连续性》中认为，厚重的文化积累是中华文明突出连续性的内在支撑。历代思想文化积淀塑造了核心文化基因，这些基本文化因素在传承中不断更新。","explanation":"文章以先秦子学、两汉经学、宋明理学等思想传统的积累说明内在支撑如何形成。题中①以“强大的文化主体性”替换了该文所说的“厚重的文化积累”，据此按解析口径排除①，选含②③④的D项。这个判断限于本题所据文章的归因。","references":[{"source":"web-29d209c9a1718b3d","location":"“厚重的文化积累是中华文明突出连续性的内在支撑”一节","quote":"凭借的是漫长文明演进中思想文化的积累"}],"evidence":"厚重的文化积累是中华文明突出连续性的内在支撑。","disposition":"题内说明","basis":"据原题与所列资料编释。","title":"中华文明连续性的内在支撑","related":[],"examFocus":{"江苏 2025 A类 行测#4":"辨析题中各因素与中华文明连续性的内在支撑、传承载体、自然基础和价值底蕴之间的对应关系。"}},"readings":[{"origin":"k-8c2a0d7d6f10b357","title":"中华文明连续性的内在支撑","qs":["江苏 2025 B类 行测#4"],"definition":"王学斌在《中华文明源远流长的连续性》中认为，厚重的文化积累是中华文明突出连续性的内在支撑。历代思想文化积淀塑造了核心文化基因，这些基本文化因素在传承中不断更新。","explanation":"文章以先秦子学、两汉经学、宋明理学等思想传统的积累说明内在支撑如何形成。题中①以“强大的文化主体性”替换了该文所说的“厚重的文化积累”，据此按解析口径排除①，选含②③④的D项。这个判断限于本题所据文章的归因。","evidence":"厚重的文化积累是中华文明突出连续性的内在支撑。","doubt":"","references":[{"source":"web-29d209c9a1718b3d","location":"“厚重的文化积累是中华文明突出连续性的内在支撑”一节","quote":"凭借的是漫长文明演进中思想文化的积累"}]},{"origin":"k-901bcb92be52db37","title":"中华文明连续性的内在支撑","qs":["江苏 2025 A类 行测#4"],"definition":"《中华文明源远流长的连续性》将厚重的文化积累视为中华文明突出连续性的内在支撑，强调既有文化的长期积淀和世代传承。","explanation":"该文用国家文化基因的世代传承解释文明何以历久弥新。题中①将“内在支撑”归于“强大的文化主体性”，解析依据所引文章对这一关系的具体表述排除①。这个判断限于本题对“内在支撑”的归因。","evidence":"厚重的文化积累是中华文明突出连续性的内在支撑","doubt":"","references":[]}]},"k-d6294a0ffb2093c2":{"review":{"definition":"习近平在《促进高质量充分就业》中指出，实现高质量充分就业要求很高，需要循序渐进，必须尽力而为、量力而行，并充分调动人民群众的积极性主动性创造性。","explanation":"尽力而为、量力而行要求积极推进就业工作，同时考虑现实条件。调动群众积极性主动性创造性，强调引导大家依靠努力奋斗创造幸福生活。这两层要求都见于③。②将原文微观层面的主体“劳动者”换成“每个公民”，扩大了适用范围，因此应选①③④。","references":[],"evidence":"必须尽力而为、量力而行；必须充分调动人民群众的积极性主动性创造性","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-af230d4900e709b4":{"review":{"definition":"《论我国政治协商制度的中华优秀传统文化根脉》将人民政协所体现的传统文化理念概括为“天下为公”的大同理想、“民惟邦本”的民本思想和“兼容并包、求同存异”的政治智慧。","explanation":"三项理念分别体现公共利益取向、以人民为根本的立场，以及在保留差异的同时寻求共识的协商方式。文章列出的三个核心理念对应①③④，②“明于庶物、察于人伦”未列入这一概括。","references":[],"evidence":"“民惟邦本、本固邦宁”的民本思想；（三）“兼容并包、求同存异”的政治智慧","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-c6b0fbd26a7179ff":{"review":{"definition":"题中专家认为，采集并在地图上标注乡村地名、推进命名管理和地名标志设置维护，有助于传承中华民族的历史文化。C项为这一主张补充了理由，指出地名在长期传承中不断积累文化含义，成为中华文明的载体。","explanation":"如果地名承载了长期积累的历史文化信息，采集、标注和维护地名就有助于保存这些信息并让人们继续识别和了解它们。A项也能提供支持，但只提到价值取向和文化思想观念，C项直接交代了地名与中华文明长期传承的联系，因此更贴合专家的论断。","references":[],"evidence":"在中华民族千百年的传承中被赋予更多含义，成为中华文明的独特载体","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-d6ba9ee8f3eeb096":{"review":{"definition":"题中专家主张尽快开展“海底种草”生态修复。题干给出的理由是海草床能够高效固碳，却正面临严峻退化。","explanation":"按题设将A项视为真，排放所致的全球变暖正在加剧，保住海草床的固碳能力因而更紧迫。B项说明固碳过程，C项和D项分别说明防侵蚀和水质净化效益，A项最直接补上了固碳价值与修复紧迫性之间的联系。“碳化合物”沿用A项在本题中的表述。","references":[],"evidence":"人类生产生活排放的碳化合物是变暖的主要元凶","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-7c2506a3f1a6ed3d":{"review":{"definition":"水秀社区干部认为，社区应当回应每位居民的服务需求，也应当依靠居民的经验、建议和行动开展治理。","explanation":"作为服务对象，居民提出的停车位紧张、房屋渗水等问题需要社区回应。作为治理主体，居民和商户可以提出规划改造意见，一些合理建议得到采纳。本题用这两类事实分别解释“服务的对象”和“依靠的力量”。","references":[],"evidence":"居民在社区治理中兼具服务对象与治理主体的双重身份","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-e568b5d3a53d68e7":{"review":{"definition":"本题参考请示以实际解决问题的成效和群众认可为依据，主张在全镇推广单圩村和中关村的治理经验。","explanation":"单圩村通过公开办理和回访回应村民诉求，得到村民好评。中关村通过“宅基议事会”解决五十多项问题，获得村民支持。请示以两村的具体成效和群众反馈，论证于12月下旬在单圩村召开现场交流会、向镇辖18个村推广经验的理由。","references":[],"evidence":"成效显著，受到群众广泛好评，具有示范推广价值。","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-9b00ee5a077b63a2":{"review":{"definition":"材料7认为，兴化可以通过传承和展示稻作文化扩大粮食市场影响力，并借地方文化增强居民的认同感和归属感。","explanation":"兴化建立稻米文化展览馆，让公众了解当地稻米种植和加工的历史。宣传稿可用展馆交代产业与文化结合的做法，用品牌入选百强榜体现品牌影响力，再点出材料所说的居民认同和归属感。","references":[],"evidence":"展示稻米种植加工的历史和文化，提升粮食市场影响力","disposition":"题内说明","basis":"据原题和解析编释。"}},"k-aba9b0bb1ebd7ca6":{"review":{"definition":"题干②将习近平新时代中国特色社会主义思想定位为中华文化和中国精神的时代精华，并将这一定位同马克思主义基本原理与中国具体实际、中华优秀传统文化的结合联系起来。","explanation":"②中的“魂脉”指马克思主义，“根脉”指中华优秀传统文化。解析以二者在坚持马克思主义基本原理、吸收中华优秀传统文化养分的过程中相互成就，说明题干为何将这一思想表述为中华民族文化主体性最有力的体现。②应选。","references":[],"evidence":"是中华文化和中国精神的时代精华","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-ec05507ffa8b9ea8":{"review":{"definition":"《连续性：中华文明的首要特性》认为，“中和”的文化价值诉求奠定了中华文明源远流长的价值底蕴。","explanation":"文章把“中”解释为把握适当限度，使言行合乎标准，并以相辅相成、共生共存说明“中和”。题中④采用的是这篇文章从价值取向解释文明延续的观点，②和③则分别着眼于典籍传承和地理环境。","references":[],"evidence":"“中和”的文化价值诉求奠定了中华文明连续性的价值底蕴","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-eaf22b02c2f7ce42":{"review":{"definition":"习近平总书记提出树立大抓基层的鲜明导向，要求各级重视基层、关心基层、支持基层，推动改革举措在基层落实。","explanation":"本题①讲的是工作力量和改革举措向哪里发力。推动改革举措落到基层、整治形式主义为基层减负，都是让基层有条件落实工作、增强治理能力的具体做法。","references":[],"evidence":"要树立大抓基层的鲜明导向，推动改革举措落到基层，使基层真正强起来","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-e33f4974decb7998":{"review":{"definition":"习近平总书记关于基层治理的重要论述体现了以人民为中心的价值取向，把持续保障和改善民生、让群众得实惠作为治理的出发点和落脚点。","explanation":"本题②讲的是推进基层治理现代化为了谁。材料用“创新社会治理，最终是为了让群众得实惠”说明治理创新要落到群众实际受益上，用持续保障和改善民生说明这一要求贯穿治理过程。","references":[],"evidence":"创新社会治理，最终是为了让群众得实惠","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-f3eb913fe07f8ee8":{"review":{"definition":"习近平总书记指出，基层是党的执政之基、力量之源，也是一切工作的落脚点。建强基层党组织、巩固基层政权，是夯实国家治理基础的重要支撑。","explanation":"本题③讲的是基层治理在国家治理体系中起什么作用。材料把基层党组织建设、基层政权巩固和城乡社区基础联系起来，说明国家治理的根基需要在基层筑牢。","references":[],"evidence":"基层是党的执政之基、力量之源","disposition":"独立词条","basis":"据原题和解析编释。"}},"k-0aad4e0b6fa666a7":{"sources":[{"id":"9e894341679ad7f0","label":"社会主义的产生和发展 · 社会主义制度对人类历史发展的巨大贡献","topic":"科学社会主义","category":"非时政","text":"三、社会主义制度对人类历史发展的巨大贡献\n1.社会主义开始作为一种新的社会制度发挥出历史作用。\n2.社会主义国家的存在及其在经济、政治、外交、军事上的影响，改变了世界的政治格\n局，在很大程度上遏制了资本主义和霸权主义在全世界的扩张。\n3.社会主义力量坚定地支持被压迫民族和被压迫人民，推动着世界和平与发展的时代潮\n流。\n4.社会主义在当代引导着世界人民的前进方向。","source":{"doc":"3ccc56f4000d1642c2d1","first":11,"last":12,"page":11,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-f9a4bb9f75a094fc":{"sources":[{"id":"e74b6f6eccbb2cb5","label":"科学社会主义的基本原则 · 正确把握科学社会主义的基本原则","topic":"科学社会主义","category":"非时政","text":"二、正确把握科学社会主义的基本原则\n1.作为无产阶级政党理论与实践的基本准则，科学社会主义基本原则指出了社会主义的\n发展方向和本质规定，任何时候都不能违背。\n2.科学社会主义基本原则揭示了未来社会的发展过程、发展方向的一般特征，在实践中\n不能僵化地教条地对待它。","source":{"doc":"3ccc56f4000d1642c2d1","first":12,"last":13,"page":12,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-94b3f1e82578fa61":{"sources":[{"id":"5cf247789ac94b5b","label":"在实践中探索社会主义发展的一般规律 · 社会主义发展道路的多样性","topic":"科学社会主义","category":"非时政","text":"一、社会主义发展道路的多样性\n1.各个国家的生产力发展状况和社会发展阶段决定了社会主义发展道路具有不同的特\n点。\n2.历史文化传统的差异性是造成社会主义发展道路多样性的重要条件。\n3.时代和实践的不断发展，是造成社会主义发展道路多样性的现实原因。","source":{"doc":"3ccc56f4000d1642c2d1","first":13,"last":13,"page":13,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-832c5bc5f2ff60e1":{"sources":[{"id":"302f10aea9c05f59","label":"在实践中探索社会主义发展的一般规律 · 社会主义在实践探索中曲折前进","topic":"科学社会主义","category":"非时政","text":"二、社会主义在实践探索中曲折前进\n1.社会主义作为新生事物，其成长不会一帆风顺。\n2.社会主义社会的基本矛盾推动社会发展，是作为一个过程而展开的，人们对它的认识\n也有一个逐渐发展的过程。\n3.经济全球化对于社会主义的发展既有机遇又有挑战。","source":{"doc":"3ccc56f4000d1642c2d1","first":13,"last":13,"page":13,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-892a5acd6ef8dc63":{"sources":[{"id":"a0c146865ffe032b","label":"十个明确","topic":"新时代中国特色社会主义思想","category":"非时政","text":"1.明确中国特色社会主义最本质的特征是中国共产党领导，中国特色社会主义制度的最\n大优势是中国共产党领导，中国共产党是最高政治领导力量，全党必须增强“四个意识”、\n坚定“四个自信”、做到“两个维护”；\n◎粉笔拓展\n“四个意识”是指政治意识、大局意识、核心意识、看齐意识；“四个自信”即中国特\n色社会主义道路自信、理论自信、制度自信、文化自信；“两个维护”是中国共产党的最高\n政治原则和根本政治规矩，是指坚决维护习近平总书记党中央的核心、全党的核心地位，坚\n决维护以习近平同志为核心的党中央权威和集中统一领导。\n2.明确坚持和发展中国特色社会主义，总任务是实现社会主义现代化和中华民族伟大复\n兴，在全面建成小康社会的基础上，分两步走在本世纪中叶建成富强民主文明和谐美丽的社\n会主义现代化强国，以中国式现代化推进中华民族伟大复兴；\n3.明确新时代我国社会主要矛盾是人民日益增长的美好生活需要和不平衡不充分的发\n展之间的矛盾，必须坚持以人民为中心的发展思想，发展全过程人民民主，推动人的全面发\n展、全体人民共同富裕取得更为明显的实质性进展；\n4.明确中国特色社会主义事业总体布局是经济建设、政治建设、文化建设、社会建设、\n生态文明建设五位一体，战略布局是全面建设社会主义现代化国家、全面深化改革、全面依\n法治国、全面从严治党四个全面；\n5.明确全面深化改革总目标是完善和发展中国特色社会主义制度、推进国家治理体系和\n治理能力现代化；\n6.明确全面推进依法治国总目标是建设中国特色社会主义法治体系、建设社会主义法治\n国家；\n7.明确必须坚持和完善社会主义基本经济制度，使市场在资源配置中起决定性作用，更\n好发挥政府作用，把握新发展阶段，贯彻创新、协调、绿色、开放、共享的新发展理念，加\n快构建以国内大循环为主体、国内国际双循环相互促进的新发展格局，推动高质量发展，统\n筹发展和安全；\n8.明确党在新时代的强军目标是建设一支听党指挥、能打胜仗、作风优良的人民军队，\n把人民军队建设成为世界一流军队；\n9.明确中国特色大国外交要服务民族复兴、促进人类进步，推动建设新型国际关系，推\n动构建人类命运共同体；\n10.明确全面从严治党的战略方针，提出新时代党的建设总要求，全面推进党的政治建\n设、思想建设、组织建设、作风建设、纪律建设，把制度建设贯穿其中，深入推进反腐败斗\n争，落实管党治党政治责任，以伟大自我革命引领伟大社会革命。","source":{"doc":"3ccc56f4000d1642c2d1","first":14,"last":16,"page":14,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-a31a4da1a5c0ccfe":{"sources":[{"id":"b15007b5024adbae","label":"十四个坚持","topic":"新时代中国特色社会主义思想","category":"非时政","text":"1.坚持党对一切工作的领导。党政军民学，东西南北中，党是领导一切的。\n2.坚持以人民为中心。人民是历史的创造者，是决定党和国家前途命运的根本力量。\n3.坚持全面深化改革。只有社会主义才能救中国，只有改革开放才能发展中国、发展社\n会主义、发展马克思主义。\n4.坚持新发展理念。发展是解决我国一切问题的基础和关键，发展必须是科学发展，必\n须坚定不移贯彻创新、协调、绿色、开放、共享的发展理念。\n5.坚持人民当家作主。坚持党的领导、人民当家作主、依法治国有机统一是社会主义政\n治发展的必然要求。\n6.坚持全面依法治国。全面依法治国是中国特色社会主义的本质要求和重要保障。\n7.坚持社会主义核心价值体系。文化自信是一个国家、一个民族发展中更基本、更深沉、\n更持久的力量。\n8.坚持在发展中保障和改善民生。增进民生福祉是发展的根本目的。\n9.坚持人与自然和谐共生。建设生态文明是中华民族永续发展的千年大计。\n10.坚持总体国家安全观。统筹发展和安全，增强忧患意识，做到居安思危，是我们党\n治国理政的一个重大原则。\n11.坚持党对人民军队的绝对领导。建设一支听党指挥、能打胜仗、作风优良的人民军\n队，是实现“两个一百年”奋斗目标、实现中华民族伟大复兴的战略支撑。\n12.坚持“一国两制”和推进祖国统一。保持香港、澳门长期繁荣稳定，实现祖国完全\n统一，是实现中华民族伟大复兴的必然要求。\n13.坚持推动构建人类命运共同体。中国人民的梦想同各国人民的梦想息息相通，实现\n中国梦离不开和平的国际环境和稳定的国际秩序。\n14.坚持全面从严治党。勇于自我革命，从严管党治党，是我们党最鲜明的品格。","source":{"doc":"3ccc56f4000d1642c2d1","first":16,"last":17,"page":16,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-3969d72b4006daee":{"sources":[{"id":"b1e90e5af2babd00","label":"六个必须坚持","topic":"新时代中国特色社会主义思想","category":"非时政","text":"必须坚持人民至上，必须坚持自信自立，必须坚持守正创新，必须坚持问题导向，必须\n坚持系统观念，必须坚持胸怀天下。","source":{"doc":"3ccc56f4000d1642c2d1","first":17,"last":17,"page":17,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-56e6fe3b4bdc8264":{"sources":[{"id":"42a47d5d5bab1be1","label":"中国式现代化理论体系","topic":"新时代中国特色社会主义思想","category":"非时政","text":"1.中国式现代化 5 个方面的中国特色：\n第一，人口规模巨大的现代化。这是中国式现代化的显著特征。\n第二，全体人民共同富裕的现代化。这是中国式现代化的本质特征，也是区别于西方现\n代化的显著标志。\n第三，物质文明和精神文明相协调的现代化。既要物质富足、也要精神富有，是中国式\n现代化的崇高追求。\n第四，人与自然和谐共生的现代化。尊重自然、顺应自然、保护自然，促进人与自然和\n谐共生，是中国式现代化的鲜明特点。\n第五，走和平发展道路的现代化。坚持和平发展，在坚定维护世界和平与发展中谋求自\n身发展，又以自身发展更好维护世界和平与发展，推动构建人类命运共同体，是中国式现代\n化的突出特征。\n2.推进中国式现代化需要处理好若干重大关系\n一是顶层设计与实践探索的关系。二是战略与策略的关系。三是守正与创新的关系。四\n是效率与公平的关系。五是活力与秩序的关系。六是自立自强与对外开放的关系。","source":{"doc":"3ccc56f4000d1642c2d1","first":17,"last":18,"page":17,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-118295d3a63ccf84":{"sources":[{"id":"f207988023f76a97","label":"经济思想","topic":"新时代中国特色社会主义思想","category":"非时政","text":"2022 年 6 月，由中共中央宣传部、国家发展和改革委员会组织编写的《习近平经济思\n想学习纲要》，将习近平经济思想基本内容梳理归纳为十三个方面：\n（1）加强党对经济工作的全面领导是我国经济发展的根本保证；\n（2）坚持以人民为中心的发展思想是我国经济发展的根本立场；\n（3）进入新发展阶段是我国经济发展的历史方位；\n（4）坚持新发展理念是我国经济发展的指导原则；\n◎粉笔拓展\n新发展理念包括：创新、协调、绿色、开放、共享。其中，创新是引领发展的第一动力。\n协调是持续健康发展的内在要求。绿色是永续发展的必要条件和人民对美好生活追求的重要\n体现。开放是国家繁荣发展的必由之路。共享是中国特色社会主义的本质要求。\n（5）构建新发展格局是我国经济发展的路径选择；\n（6）推动高质量发展是我国经济发展的鲜明主题；\n（7）坚持和完善社会主义基本经济制度是我国经济发展的制度基础；\n（8）坚持问题导向部署实施国家重大发展战略是我国经济发展的战略举措；\n（9）坚持创新驱动发展是我国经济发展的第一动力；\n（10）大力发展制造业和实体经济是我国经济发展的主要着力点；\n（11）坚定不移全面扩大开放是我国经济发展的重要法宝；\n（12）统筹发展和安全是我国经济发展的重要保障；\n（13）坚持正确工作策略和方法是做好经济工作的方法论。","source":{"doc":"3ccc56f4000d1642c2d1","first":19,"last":20,"page":19,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-f967adabfcf3a099":{"sources":[{"id":"1910afb83c30fe28","label":"法治思想","topic":"新时代中国特色社会主义思想","category":"非时政","text":"2020 年 11 月 16 日至 17 日，中央全面依法治国工作会议首次提出并用“十一个坚持”\n系统阐述了习近平法治思想。即：\n（1）坚持党对全面依法治国的领导。党的领导是推进全面依法治国的根本保证。\n（2）坚持以人民为中心。全面依法治国最广泛、最深厚的基础是人民，必须坚持为了\n人民、依靠人民。\n（3）坚持中国特色社会主义法治道路。中国特色社会主义法治道路本质上是中国特色\n社会主义道路在法治领域的具体体现。\n（4）坚持依宪治国、依宪执政。党领导人民制定宪法法律，领导人民实施宪法法律，\n党自身要在宪法法律范围内活动。\n（5）坚持在法治轨道上推进国家治理体系和治理能力现代化。法治是国家治理体系和\n治理能力的重要依托。\n（6）坚持建设中国特色社会主义法治体系。中国特色社会主义法治体系是推进全面依\n法治国的总抓手。\n（7）坚持依法治国、依法执政、依法行政共同推进，法治国家、法治政府、法治社会\n一体建设。全面依法治国是一个系统工程，要整体谋划，更加注重系统性、整体性、协同性。\n（8）坚持全面推进科学立法、严格执法、公正司法、全民守法。公平正义是司法的灵\n魂和生命。\n（9）坚持统筹推进国内法治和涉外法治。\n（10）坚持建设德才兼备的高素质法治工作队伍，\n（11）坚持抓住领导干部这个“关键少数”。","source":{"doc":"3ccc56f4000d1642c2d1","first":20,"last":20,"page":20,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-71ac15099cc6629a":{"sources":[{"id":"cf56e6f75d9f6705","label":"文化思想","topic":"新时代中国特色社会主义思想","category":"非时政","text":"1.宣传思想工作的根本任务\n2013 年 8 月 19 日至 20 日，全国宣传思想工作会议强调，意识形态工作是党的一项极\n端重要的工作，明确“两个巩固”作为宣传思想工作的根本任务，即：巩固马克思主义在意\n识形态领域的指导地位，巩固全党全国人民团结奋斗的共同思想基础。\n2.两个结合\n2021 年 7 月 1 日，在庆祝中国共产党成立 100 周年大会上，习近平总书记首次正式提\n出“两个结合”重大论断，即“坚持把马克思主义基本原理同中国具体实际相结合、同中华\n优秀传统文化相结合”。“第二个结合”\n，是我们党对马克思主义中国化时代化历史经验的深\n刻总结，是对中华文明发展规律的深刻把握。\n2023 年 6 月 2 日，习近平总书记在文化传承发展座谈会上指出，历史正反两方面的经\n验表明，“两个结合”是我们取得成功的最大法宝。\n第一，“结合”的前提是彼此契合；第二，“结合”的结果是互相成就；第三，“结合”\n筑牢了道路根基；第四，“结合”打开了创新空间；第五，\n“结合”巩固了文化主体性。\n3.新的文化使命\n2023 年 6 月 2 日，习近平总书记在文化传承发展座谈会上指出，在新的起点上继续推\n动文化繁荣、建设文化强国、建设中华民族现代文明，是我们在新时代新的文化使命。\n4.中华文明的突出特性\n2023 年 6 月 2 日，习近平总书记在文化传承发展座谈会上指出，中华文明具有突出的\n连续性（中华文明是世界上唯一绵延不断且以国家形态发展至今的伟大文明）、创新性、统\n一性、包容性、和平性。\n5.首要政治任务与七个着力\n2023 年，习近平总书记对宣传思想文化工作作出重要指示，将“用党的创新理论武装\n全党、教育人民”作为宣传思想文化工作的首要政治任务，并提出“七个着力”重要要求，\n即：（1）着力加强党对宣传思想文化工作的领导，（2）着力建设具有强大凝聚力和引领力\n的社会主义意识形态，（3）着力培育和践行社会主义核心价值观，（4）着力提升新闻舆论\n传播力引导力影响力公信力，（5）着力赓续中华文脉、推动中华优秀传统文化创造性转化\n和创新性发展，（6）着力推动文化事业和文化产业繁荣发展，（7）着力加强国际传播能力\n建设、促进文明交流互鉴。","source":{"doc":"3ccc56f4000d1642c2d1","first":21,"last":22,"page":21,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-7f4e6b43f7f8ad05":{"sources":[{"id":"fd51587340a36b0e","label":"强军思想","topic":"新时代中国特色社会主义思想","category":"非时政","text":"习近平强军思想以“强军目标”为牵引，以“十一个明确”为主干，以“五个坚持”为\n精髓，涵盖新时代军队建设、改革和军事斗争准备各领域各方面，贯通军事力量建设和运用\n全过程，形成了一个内涵丰富、结构严谨、与时俱进的思想体系。\n1.“十一个明确”\n（1）明确党对人民军队的绝对领导是人民军队建军之本、强军之魂。\n（2）明确强国必须强军，巩固国防和强大人民军队是新时代坚持和发展中国特色社会\n主义、实现中华民族伟大复兴的战略支撑，人民军队必须有效履行新时代使命任务。\n（3）明确党在新时代的强军目标是建设一支听党指挥、能打胜仗、作风优良的人民军\n队，到 2027 年实现建军一百年奋斗目标，到 2035 年基本实现国防和军队现代化，到本世\n纪中叶把人民军队建成世界一流军队。\n（4）明确军队是要准备打仗的，必须聚焦能打仗、打胜仗。\n（5）明确推进强军事业必须坚持政治建军、改革强军、科技强军、人才强军、依法治\n军，坚持边斗争、边备战、边建设。\n（6）明确改革是强军的必由之路，必须推进军队组织形态现代化，构建中国特色现代\n军事力量体系，完善中国特色社会主义军事制度。\n（7）明确科技是核心战斗力，必须坚持自主创新战略基点，推进高水平科技自立自强。\n（8）明确强军之道要在得人，必须贯彻新时代军事教育方针。\n（9）明确依法治军是我们党建军治军基本方式。\n（10）明确军民融合发展是兴国之举、强军之策，必须巩固提高一体化国家战略体系\n和能力。\n（11）明确作风优良是我军鲜明特色和政治优势，必须全面从严治党、全面从严治军。\n2.五个坚持\n即：\n（1）坚持政治引领，\n（2）坚持以武止戈，\n（3）坚持积极进取，\n（4）坚持统筹兼顾，\n（5）坚持敢打必胜。\n3.新时代政治建军方略\n明确政治建军是人民军队立军之本，明确政治工作永远是我军的生命线，明确政治整训\n要突出政治上的正本清源，明确掌握思想领导是掌握一切领导的基础，明确党的力量来自组\n织、部队凝聚力战斗力来自组织，明确枪杆子要始终掌握在对党忠诚可靠的人手中，明确严\n才能正纲纪、严才能肃军威、严才能出战斗力，明确军中绝不能有腐败分子藏身之地，明确\n作风优良才能塑造英雄部队，明确军政军民团结是我军胜利法宝。","source":{"doc":"3ccc56f4000d1642c2d1","first":23,"last":24,"page":23,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-3c751ecd149b9985":{"sources":[{"id":"11334b77ee634395","label":"外交思想","topic":"新时代中国特色社会主义思想","category":"非时政","text":"1.十个坚持\n2018 年 6 月 22 日至 23 日，中央外事工作会议确立习近平外交思想的指导地位，并用\n“十个坚持”阐释习近平外交思想的丰富内涵。即：\n（1）坚持以维护党中央权威为统领加强党对对外工作的集中统一领导；\n（2）坚持以实现中华民族伟大复兴为使命推进中国特色大国外交；\n（3）坚持以维护世界和平、促进共同发展为宗旨推动构建人类命运共同体；\n（4）坚持以中国特色社会主义为根本增强战略自信；\n（5）坚持以共商共建共享为原则推动“一带一路”建设；\n（6）坚持以相互尊重、合作共赢为基础走和平发展道路；\n（7）坚持以深化外交布局为依托打造全球伙伴关系；\n（8）坚持以公平正义为理念引领全球治理体系改革；\n（9）坚持以国家核心利益为底线维护国家主权、安全、发展利益；\n（10）坚持以对外工作优良传统和时代特征相结合为方向塑造中国外交独特风范。\n2.六个必须\n2023 年 12 月 27 日至 28 日，中央外事工作会议系统总结新时代中国特色大国外交的\n历史性成就和宝贵经验。历史性成就涵盖十个方面，排在第一的是“创立和发展了习近平外\n交思想”。\n会议将新时代外交工作的宝贵经验总结为“六个必须”，即：（1）必须做到坚持原则，\n（2）必须体现大国担当，\n（3）必须树立系统观念，\n（4）必须坚持守正创新，\n（5）必须发扬\n斗争精神，（6）必须发挥制度优势。","source":{"doc":"3ccc56f4000d1642c2d1","first":24,"last":25,"page":24,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-259adcd221f15b69":{"sources":[{"id":"36adc9013d4bb8fe","label":"关于坚持和完善人民代表大会制度的重要思想","topic":"新时代中国特色社会主义思想","category":"非时政","text":"2024 年 9 月 14 日，中共中央、全国人大常委会隆重举行庆祝全国人民代表大会成立\n70 周年大会。习近平总书记出席会议并发表重要讲话，深刻阐述人民代表大会制度具有的\n五个方面显著政治优势：（1）坚持中国共产党领导、保证党领导人民依法有效治理国家的\n显著优势，（2）践行全过程人民民主、保障人民当家作主的显著优势，（3）贯彻民主集中\n制、保证国家政治生活既充满活力又安定有序的显著优势，（4）保障全面依法治国、实现\n国家各方面工作法治化的显著优势，（5）维护国家统一、保障国家长治久安的显著优势。\n同时，习近平总书记在会上系统总结新时代人民代表大会制度理论和实践创新重大成果，\n提出“八个必须坚持”：\n（1）必须坚持中国共产党领导，\n（2）必须坚持用制度体系保障人民\n当家作主，（3）必须坚持全面依法治国，（4）必须坚持民主集中制，（5）必须坚持走中国\n特色社会主义政治发展道路，（6）必须坚持推进国家治理体系和治理能力现代化，（7）必\n须坚持充分发挥人大代表作用，（8）必须坚持按照“四个机关”要求加强各级人大建设。\n（粉笔敲黑板：“四个机关”是指人民代表大会作为政治机关、国家权力机关、工作机\n关和代表机关的四重定位，体现了其政治属性、民主属性、法治属性和人民属性。）\n◎粉笔拓展\n1.国体，即国家性质\n我国宪法规定：“中华人民共和国是工人阶级领导的，以工农联盟为基础的人民民主专\n政的社会主义国家。”这是我国国体的明确规定。\n“社会主义制度是中华人民共和国的根本制\n度。”\n2.政体，即政权组织形式\n我国宪法规定：“中华人民共和国的一切权力属于人民。人民行使国家权力的机关是全\n国人民代表大会和地方各级人民代表大会。”也即，我国的政体是人民代表大会制度。","source":{"doc":"3ccc56f4000d1642c2d1","first":25,"last":26,"page":25,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-2e2569c448e37ec6":{"sources":[{"id":"5cce5ae5c14b4273","label":"关于加强和改进人民政协工作的重要思想","topic":"新时代中国特色社会主义思想","category":"非时政","text":"2024 年 9 月 20 日，在庆祝中国人民政治协商会议成立 75 周年大会上，习近平总书记\n用“十个坚持”系统总结我们党关于加强和改进人民政协工作的重要思想，即：\n（1）坚持中国共产党对人民政协的全面领导，\n（2）坚持人民政协性质定位，\n（3）坚持\n发挥人民政协作为专门协商机构作用，（4）坚持和完善我国社会主义新型政党制度，（5）\n坚持大团结大联合，（6）坚持把加强思想政治引领、广泛凝聚共识作为中心环节，（7）坚\n持聚焦党和国家中心任务履职尽责，（8）坚持人民政协为人民，（9）坚持强化委员责任担\n当，（10）坚持以改革创新精神推进履职能力建设。","source":{"doc":"3ccc56f4000d1642c2d1","first":26,"last":26,"page":26,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-686d6949914729d1":{"sources":[{"id":"51fe3945894a24fd","label":"关于加强和改进民族工作的重要思想","topic":"新时代中国特色社会主义思想","category":"非时政","text":"2021 年 8 月召开的中央民族工作会议，用“十二个必须”提炼概括习近平总书记关于\n加强和改进民族工作的重要思想，即：\n（1）必须从中华民族伟大复兴战略高度把握新时代党的民族工作的历史方位，\n（2）必\n须把推动各民族为全面建设社会主义现代化国家共同奋斗作为新时代党的民族工作的重要\n任务，（3）必须以铸牢中华民族共同体意识为新时代党的民族工作的主线，（4）必须坚持\n正确的中华民族历史观，（5）必须坚持各民族一律平等，（6）必须高举中华民族大团结旗\n帜，（7）必须坚持和完善民族区域自治制度，（8）必须构筑中华民族共有精神家园，（9）\n必须促进各民族广泛交往交流交融，（10）必须坚持依法治理民族事务，（11）必须坚决维\n护国家主权、安全、发展利益，（12）必须坚持党对民族工作的领导。","source":{"doc":"3ccc56f4000d1642c2d1","first":27,"last":27,"page":27,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-d1070e5e1a906d75":{"sources":[{"id":"158e87308e99f225","label":"关于党的建设的重要思想","topic":"新时代中国特色社会主义思想","category":"非时政","text":"2023 年 6 月 28 日至 29 日召开的全国组织工作会议，用“十三个坚持”集中概括了习\n近平总书记关于党的建设的重要思想，即：\n（1）坚持和加强党的全面领导；\n（2）坚持以党的自我革命引领社会革命（相关论述：党的自我革命是“跳出治乱兴衰\n历史周期率的第二个答案）；\n（3）坚持以党的政治建设统领党的建设各项工作（相关论述：党的政治建设决定党的\n建设方向和效果；党的政治建设是党的根本性建设；把党的政治建设摆在首位）；\n（4）坚持江山就是人民、人民就是江山（相关论述：站稳人民立场、把握人民愿望、\n尊重人民创造、集中人民智慧）；\n（5）坚持思想建党、理论强党（相关论述：思想建设是党的基础性建设）；\n（粉笔敲黑\n板：注意党的根本性建设是政治建设，基础性建设是思想建设）\n（6）坚持严密党的组织体系；\n（7）坚持造就忠诚干净担当的高素质干部队伍（相关论述：坚持把政治标准放在首位，\n做深做实干部政治素质考察，突出把好政治关、廉洁关）；\n（8）坚持聚天下英才而用之；\n（9）坚持持之以恒正风肃纪（相关论述：作风问题本质上是党性问题）；\n（10）坚持一体推进不敢腐、不能腐、不想腐（相关论述：腐败是最彻底的自我革命）；\n（11）坚持完善党和国家监督体系（相关论述：构建党统一指挥、全面覆盖、权威高\n效的监督体系，把党内监督同国家机关监督、民主监督、司法监督、群众监督、舆论监督贯\n通起来）；\n（12）坚持制度治党、依规治党（相关论述：加强党内法规制度建设是全面从严治党\n的长远之策、根本之策）；\n（13）坚持落实全面从严治党政治责任（相关论述：明确党委（党组）全面从严治党\n主体责任，明确各级纪委的监督责任，明确党委（党组）书记第一责任人责任，明确领导班\n子成员的管党治党责任，明确党员、干部的具体责任）。","source":{"doc":"3ccc56f4000d1642c2d1","first":27,"last":28,"page":27,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"k-aea61fbf64943156":{"sources":[{"id":"72cb04e5254bdb99","label":"既“放得活”又“管得好”","topic":"发展与治理","category":"非时政","text":"2.既“放得活”又“管得好”\n2025 年 12 月召开的中央经济工作会议，将“必须做到既‘放得活’又‘管得好’”列\n入做好新形势下经济工作的新认识，以辩证思维理顺政府与市场的关系，意在实现经济活而\n不乱、活跃有序。“放”不是一放了之，“管”也不是捆住手脚。“放得活”目的在于破除\n影响生产力发展的体制机制障碍；“管得好”本质要求是建设社会主义法治经济、信用经\n济。二者并不矛盾，而是统一于高水平社会主义市场经济体制中，共同指向高质量发展这一\n首要任务。\n放，是把该放归市场的放足、放到位，充分发挥市场在资源配置中的决定性作用。管，\n是把该政府管理的管好、管到位，更好发挥政府作用。\n——中国共产党新闻网","source":{"doc":"6cbfb01fe723bba64b75","first":5,"last":5,"page":5,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-44978dc25d3eec22":{"sources":[{"id":"2b7ba85592536217","label":"投资于物和投资于人紧密结合","topic":"经济指标与宏观调控","category":"非时政","text":"3.投资于物和投资于人紧密结合\n投资于物是指对实物资产进行投资，比如基础设施、房屋建筑、机器设备等，可以为经\n济社会发展夯实物质技术基础。\n投资于人是指对全人群、全生命周期人的能力提升和潜力开发的投入，比如育幼、养\n老、健康、教育、技能培训等。\n——新华社（学习规划建议每日问答）","source":{"doc":"6cbfb01fe723bba64b75","first":5,"last":5,"page":5,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-c61a96c349af6f0e":{"sources":[{"id":"99df742877aae930","label":"全球治理倡议","topic":"发展与治理","category":"非时政","text":"全球治理倡议\n2025 年 9 月 1 日，习近平总书记在“上海合作组织+”会议上郑重提出全球治理倡议，\n这是继全球发展倡议、全球安全倡议、全球文明倡议之后，习近平总书记提出的第四个全球\n倡议，为破解“世界怎么了，我们怎么办”之问进一步贡献中国智慧、提出中国方案。\n全球治理倡议核心理念包括：\n（一）坚持主权平等。这是全球治理的首要前提。\n（二）坚持国际法治。这是全球治理的根本保障。\n（三）坚持多边主义。这是全球治理的基本路径。\n（四）坚持以人为本。这是全球治理的价值取向。\n（五）坚持力求实效。这是全球治理的重要原则。\n——中国共产党新闻网、外交部","source":{"doc":"6cbfb01fe723bba64b75","first":13,"last":13,"page":13,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-5f377175afc75157":{"sources":[{"id":"266cb54b20bf6a24","label":"社会主义核心价值观","topic":"发展与治理","category":"非时政","text":"5.社会主义核心价值观\n党的十八大提出，倡导富强、民主、文明、和谐，倡导自由、平等、公正、法治，倡导\n爱国、敬业、诚信、友善，积极培育和践行社会主义核心价值观。这与中国特色社会主义发\n展要求相契合，与中华优秀传统文化和人类文明优秀成果相承接，是我们党凝聚全党全社会\n价值共识作出的重要论断。富强、民主、文明、和谐是国家层面的价值目标，自由、平等、\n公正、法治是社会层面的价值取向，爱国、敬业、诚信、友善是公民个人层面的价值准则，\n这 24 个字是社会主义核心价值观的基本内容，为培育和践行社会主义核心价值观提供了基\n本遵循。","source":{"doc":"6cbfb01fe723bba64b75","first":19,"last":19,"page":19,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"},{"id":"1aea66b8c06cac87","label":"社会主义核心价值观","topic":"发展与治理","category":"非时政","text":"1.社会主义核心价值观\n培育和践行社会主义核心价值观，是推进中国特色社会主义伟大事业、实现中华民族伟\n大复兴中国梦的战略任务。党的十八大提出，倡导富强、民主、文明、和谐，倡导自由、平\n等、公正、法治，倡导爱国、敬业、诚信、友善，积极培育和践行社会主义核心价值观。这\n与中国特色社会主义发展要求相契合，与中华优秀传统文化和人类文明优秀成果相承接，是\n我们党凝聚全党全社会价值共识作出的重要论断。富强、民主、文明、和谐是国家层面的价\n值目标，自由、平等、公正、法治是社会层面的价值取向，爱国、敬业、诚信、友善是公民\n个人层面的价值准则，这 24 个字是社会主义核心价值观的基本内容，为培育和践行社会主\n义核心价值观提供了基本遵循。\n——《关于培育和践行社会主义核心价值观的意见》","source":{"doc":"6cbfb01fe723bba64b75","first":44,"last":44,"page":44,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-4130dfb7a972a576":{"sources":[{"id":"bc07e3e31a3a719f","label":"科学家精神","topic":"产业、科技与对外开放","category":"非时政","text":"3.科学家精神\n科学家精神是胸怀祖国、服务人民的爱国精神，勇攀高峰、敢为人先的创新精神，追\n求真理、严谨治学的求实精神，淡泊名利、潜心研究的奉献精神，集智攻关、团结协作的\n协同精神，甘为人梯、奖掖后学的育人精神。2021 年 9 月科学家精神被纳入为第一批中国\n共产党人精神谱系的伟大精神。","source":{"doc":"6cbfb01fe723bba64b75","first":27,"last":27,"page":27,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-c403f9e7a1b94eb8":{"sources":[{"id":"7e4f8c5b6fe5331b","label":"企业家精神","topic":"产业、科技与对外开放","category":"非时政","text":"4.企业家精神\n增强爱国情怀，勇于创新，诚信守法，承担社会责任，拓展国际视野。\n企业家要带领企业战胜当前的困难，走向更辉煌的未来，就要弘扬企业家精神，在爱国、\n创新、诚信、社会责任和国际视野等方面不断提升自己，努力成为新时代构建新发展格局、\n建设现代化经济体系、推动高质量发展的生力军。\n——2020 年 7 月 21 日，习近平在企业家座谈会上的讲话","source":{"doc":"6cbfb01fe723bba64b75","first":30,"last":30,"page":30,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-906908a6da20c392":{"sources":[{"id":"177047d974024efc","label":"“钉钉子精神”","topic":"发展与治理","category":"非时政","text":"5.“钉钉子精神”\n我们要有钉钉子的精神，钉钉子往往不是一锤子就能钉好的，而是要一锤一锤接着敲，\n直到把钉子钉实钉牢，钉牢一颗再钉下一颗，不断钉下去，必然大有成效。如果东一榔头西\n一棒子，结果很可能是一颗钉子都钉不上、钉不牢。\n——《习近平谈治国理政》","source":{"doc":"6cbfb01fe723bba64b75","first":36,"last":36,"page":36,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-40d64ab4ee651389":{"sources":[{"id":"1118cba9eb8a3fed","label":"健康优先发展战略","topic":"就业、社保与公共服务","category":"非时政","text":"1.健康优先发展战略\n实施健康优先发展战略，健全公共卫生体系，促进社会共治、医防协同、医防融合，强\n化监测预警、风险评估、流行病学调查、检验检测、应急处置、医疗救治等能力。\n——《中共中央关于进一步全面深化改革、推进中国式现代化的决定》","source":{"doc":"6cbfb01fe723bba64b75","first":42,"last":42,"page":42,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-62150212afb07701":{"sources":[{"id":"4c71a679cd44373a","label":"深入实施中华优秀传统文化传承发展工程","topic":"发展与治理","category":"非时政","text":"3.深入实施中华优秀传统文化传承发展工程\n主要内容：\n（1）核心思想理念。中华民族和中国人民在修齐治平、尊时守位、知常达变、开物成\n务、建功立业过程中培育和形成的基本思想理念，如革故鼎新、与时俱进的思想，脚踏实地、\n实事求是的思想，惠民利民、安民富民的思想，道法自然、天人合一的思想等，可以为人们\n认识和改造世界提供有益启迪，可以为治国理政提供有益借鉴。传承发展中华优秀传统文化，\n就要大力弘扬讲仁爱、重民本、守诚信、崇正义、尚和合、求大同等核心思想理念。\n（2）中华传统美德。中华优秀传统文化蕴含着丰富的道德理念和规范，如天下兴亡、\n匹夫有责的担当意识，精忠报国、振兴中华的爱国情怀，崇德向善、见贤思齐的社会风尚，\n孝悌忠信、礼义廉耻的荣辱观念，体现着评判是非曲直的价值标准，潜移默化地影响着中国\n人的行为方式。传承发展中华优秀传统文化，就要大力弘扬自强不息、敬业乐群、扶危济困、\n见义勇为、孝老爱亲等中华传统美德。\n（3）中华人文精神。中华优秀传统文化积淀着多样、珍贵的精神财富，如求同存异、\n和而不同的处世方法，文以载道、以文化人的教化思想，形神兼备、情景交融的美学追求，\n俭约自守、中和泰和的生活理念等，是中国人民思想观念、风俗习惯、生活方式、情感样式\n的集中表达，滋养了独特丰富的文学艺术、科学技术、人文学术，至今仍然具有深刻影响。\n传承发展中华优秀传统文化，就要大力弘扬有利于促进社会和谐、鼓励人们向上向善的思想\n文化内容。\n——《关于实施中华优秀传统文化传承发展工程的意见》","source":{"doc":"6cbfb01fe723bba64b75","first":44,"last":45,"page":44,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-0efecb3b016302c9":{"sources":[{"id":"c3da64daf8e2d7c5","label":"总体国家安全观","topic":"发展与治理","category":"非时政","text":"1.总体国家安全观\n2014 年 4 月 15 日，习近平总书记在中央国家安全委员会第一次会议上，创造性提出总\n体国家安全观。\n——《求是》杂志文章《全面贯彻总体国家安全观》\n我们要坚持以人民安全为宗旨、以政治安全为根本、以经济安全为基础、以军事科技文\n化社会安全为保障、以促进国际安全为依托，统筹外部安全和内部安全、国土安全和国民安\n全、传统安全和非传统安全、自身安全和共同安全，统筹维护和塑造国家安全，夯实国家安\n全和社会稳定基层基础，完善参与全球安全治理机制，建设更高水平的平安中国，以新安全\n格局保障新发展格局。\n——《党的二十大报告》","source":{"doc":"6cbfb01fe723bba64b75","first":49,"last":49,"page":49,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"},{"id":"b5a8ce163b7c8412","label":"总体国家安全观","topic":"发展与治理","category":"非时政","text":"1.总体国家安全观\n2014 年 4 月 15 日，习近平总书记在中央国家安全委员会第一次会议上首次提出总体国\n家安全观。\n我们要坚持以人民安全为宗旨、以政治安全为根本、以经济安全为基础、以军事科技文\n化社会安全为保障、以促进国际安全为依托，统筹外部安全和内部安全、国土安全和国民安\n全、传统安全和非传统安全、自身安全和共同安全，统筹维护和塑造国家安全，夯实国家安\n全和社会稳定基层基础，完善参与全球安全治理机制，建设更高水平的平安中国，以新安全\n格局保障新发展格局。","source":{"doc":"6cbfb01fe723bba64b75","first":19,"last":19,"page":19,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-362c159c0d3ed6cb":{"sources":[{"id":"2749f538678c62c3","label":"新时代“枫桥经验”","topic":"发展与治理","category":"非时政","text":"3.新时代“枫桥经验”\n（1）“枫桥经验”\n“枫桥经验”是指 20 世纪 60 年代初，浙江诸暨县（现诸暨市）枫桥镇干部群众创造的\n“发动和依靠群众，坚持矛盾不上交，就地解决，实现捕人少，治安好”的基层社会治理经\n验。\n1963 年，毛泽东同志亲笔批示：“要各地仿效，经过试点，推广去做。”2003 年，时\n任浙江省委书记的习近平同志明确要求充分珍惜、大力推广、不断创新“枫桥经验”。\n（2）新时代“枫桥经验”\n“枫桥经验”在实践中不断丰富、持续发展，特别是党的十八大以来，形成了特色鲜明\n的新时代“枫桥经验”。\n党的十八大以来，习近平总书记多次作出重要指示，要求在社会基层坚持和发展新时代\n“枫桥经验”。其内涵是：坚持和贯彻党的群众路线，在党的领导下，充分发动群众、组织\n群众、依靠群众解决群众自己的事情，做到“小事不出村、大事不出镇、矛盾不上交”。","source":{"doc":"6cbfb01fe723bba64b75","first":50,"last":50,"page":50,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-c713fd84bad8ce49":{"sources":[{"id":"bbd1d1c94e39bf88","label":"增强“四个意识”、坚定“四个自信”、做到“两个维护”","topic":"发展与治理","category":"非时政","text":"1.增强“四个意识”、坚定“四个自信”、做到“两个维护”\n“四个意识”：政治意识、大局意识、核心意识、看齐意识。\n“四个自信”：道路自信、理论自信、制度自信、文化自信。\n“两个维护”：坚决维护习近平总书记党中央的核心、全党的核心地位，坚决维护党中\n央权威和集中统一领导。","source":{"doc":"6cbfb01fe723bba64b75","first":50,"last":51,"page":50,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-615d371b479fd158":{"sources":[{"id":"d7ff4c02a336114a","label":"树立和践行正确政绩观","topic":"发展与治理","category":"非时政","text":"3.树立和践行正确政绩观\n经党中央同意，在全党开展树立和践行正确政绩观学习教育。学习教育以县处级以上领\n导班子和领导干部特别是“一把手”为重点，于 2026 年春节假期后启动、7 月底基本结束。\n持之以恒推进全面从严治党，以立党为公、为民造福、科学决策、真抓实干为总要求，\n以一体推进学查改为抓手，教育引导各级党组织和党员、干部坚持实事求是、求真务实，为\n人民出政绩、以实干出政绩。\n学习教育要坚持聚焦主题、简约务实，不分批次、不划阶段，认真落实学习研讨、查摆\n问题、整改整治、建章立制、开门教育等工作安排。\n——《关于在全党开展树立和践行正确政绩观学习教育的通知》","source":{"doc":"6cbfb01fe723bba64b75","first":51,"last":51,"page":51,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-d0b4d85959624802":{"sources":[{"id":"362d729a358e2954","label":"整治形式主义为基层减负","topic":"发展与治理","category":"非时政","text":"3.整治形式主义为基层减负\n形式主义、官僚主义是顽瘴痼疾，必须下大力气坚决纠治。基层是贯彻落实党中央决策\n部署的“最后一公里”，不能被形式主义、官僚主义束缚手脚。\n各地区各部门要严格执行《若干规定》，统筹为基层减负和赋能，切实把基层从形式主\n义、官僚主义束缚中解脱出来，引导广大党员、干部积极担当作为，有更多精力抓落实。中\n央层面整治形式主义为基层减负专项工作机制要定期督促检查，中央和国家机关各部门、各\n省级党委和政府在安排部署工作时要实事求是，党委（党组）要履行好主体责任，各级纪检\n监察机关要强化监督执行，确保《若干规定》落到实处。\n——《整治形式主义为基层减负若干规定》","source":{"doc":"6cbfb01fe723bba64b75","first":52,"last":52,"page":52,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-a077d2fcf061fbe5":{"sources":[{"id":"67e70b6f5b528cb8","label":"以铸牢中华民族共同体意识为主线","topic":"发展与治理","category":"非时政","text":"1.以铸牢中华民族共同体意识为主线\n（1）“十二个必须”\n党关于加强和改进民族工作的重要思想，概括起来有以下方面：\n一是必须从中华民族伟大复兴战略高度把握新时代党的民族工作的历史方位。\n二是必须把推动各民族为全面建设社会主义现代化国家共同奋斗作为新时代党的民族\n工作的重要任务。\n三是必须以铸牢中华民族共同体意识为新时代党的民族工作的主线。\n四是必须坚持正确的中华民族历史观。\n五是必须坚持各民族一律平等。\n六是必须高举中华民族大团结旗帜。\n七是必须坚持和完善民族区域自治制度。\n八是必须构筑中华民族共有精神家园。\n九是必须促进各民族广泛交往交流交融。\n十是必须坚持依法治理民族事务。\n十一是必须坚决维护国家主权、安全、发展利益。\n十二是必须坚持党对民族工作的领导。\n——《2021 年习近平在中央民族工作会议上的讲话》\n（2）“五个共同”\n中华民族是有着五千多年文明史的伟大民族。我国各民族共同开拓了祖国的辽阔疆域，\n共同缔造了统一的多民族国家，共同书写了辉煌的中国历史，共同创造了灿烂的中华文化，\n共同培育了伟大的民族精神。中华民族共同体的形成和发展是人心所向、大势所趋、历史必\n然。\n各民族血脉相融，是中华民族共同体形成和发展的历史根基。各民族信念相同，是中华\n民族缔造统一的多民族国家的内生动力。各民族文化相通，是中华民族铸就多元一体文明格\n局的文化基因。各民族经济相依，是中华民族构建统一经济体的强大力量。各民族情感相亲，\n是中华民族一家亲的坚强纽带。\n——《求是》杂志文章《中华民族共同体的形成和发展是人心所向、大势所趋、历史必\n然》","source":{"doc":"6cbfb01fe723bba64b75","first":52,"last":53,"page":52,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-8b07a2246ff7cebf":{"sources":[{"id":"3e5eac35d5287c86","label":"宗教中国化","topic":"发展与治理","category":"非时政","text":"2.宗教中国化\n要总结运用历史经验，立足我国宗教工作实际，强化系统观念，加强体制规范建设，加\n强综合治理，加强基层基础工作，系统推进我国宗教中国化，积极引导宗教与社会主义社会\n相适应。\n我国是中国共产党领导的社会主义国家，积极引导宗教与社会主义社会相适应是必然要\n求。要坚持以社会主义核心价值观为引领，引导宗教界人士和信教群众牢固树立正确的国家\n观、历史观、民族观、文化观、宗教观，不断增进“五个认同”，自觉投身中国式现代化建\n设。\n——《习近平在中共中央政治局第二十二次集体学习时的讲话》","source":{"doc":"6cbfb01fe723bba64b75","first":53,"last":53,"page":53,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-9a8a45ceb5950828":{"sources":[{"id":"0635ac740211e691","label":"习近平强军思想","topic":"发展与治理","category":"非时政","text":"1.习近平强军思想\n2017 年 10 月，党的十九大把习近平强军思想写入党章，确立习近平强军思想在国防和\n军队建设中的指导地位。\n习近平强军思想的主要内容可以概括为“十一个明确”：①明确党对人民军队的绝对领\n导是人民军队建军之本、强军之魂；②明确强国必须强军，巩固国防和强大人民军队是新时\n代坚持和发展中国特色社会主义、实现中华民族伟大复兴的战略支撑；③明确党在新时代的\n强军目标是建设一支听党指挥、能打胜仗、作风优良的人民军队，到 2027 年实现建军一百\n年奋斗目标，到 2035 年基本实现国防和军队现代化，到本世纪中叶把人民军队建成世界一\n流军队；④明确军队是要准备打仗的，必须聚焦能打仗、打胜仗，扭住强敌对手；⑤明确推\n进强军事业必须坚持政治建军、改革强军、科技强军、人才强军、依法治军；⑥明确改革是\n强军的必由之路；⑦明确科技是核心战斗力；⑧明确强军之道要在得人；⑨明确依法治军是\n我们党建军治军基本方式；⑩明确军民融合发展是兴国之举、强军之策；⑪明确作风优良是\n我军鲜明特色和政治优势。","source":{"doc":"6cbfb01fe723bba64b75","first":54,"last":54,"page":54,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-ce002f8dea9083d8":{"sources":[{"id":"1133ca42fdc4e6e1","label":"台湾问题","topic":"发展与治理","category":"非时政","text":"2.台湾问题\n（1）历史任务\n解决台湾问题、实现祖国完全统一，是党矢志不渝的历史任务，是全体中华儿女的共同\n愿望，是实现中华民族伟大复兴的必然要求。坚持贯彻新时代党解决台湾问题的总体方略，\n牢牢把握两岸关系主导权和主动权，坚定不移推进祖国统一大业。\n——《党的二十大报告》\n（2）新时代党解决台湾问题总体方略（“十个坚持”）：\n第一，坚持党中央对对台工作的集中统一领导。这是统一的根本保证。\n第二，坚持在中华民族伟大复兴进程中推进祖国统一。这是统一的历史方位。\n第三，坚持在祖国大陆发展进步基础上解决台湾问题。这是统一的战略思路。\n第四，坚持“和平统一、一国两制”基本方针。这是统一的大政方针。\n第五，坚持一个中国原则和“九二共识”。这是统一的政治基础。\n第六，坚持推动两岸关系和平发展、融合发展。这是统一的实践途径。\n第七，坚持团结台湾同胞、争取台湾民心。这是统一的根本动力。\n第八，坚持粉碎“台独”分裂图谋。这是统一的必然要求。\n第九，坚持反对外部势力干涉。这是统一的外部条件。\n第十，坚持决不承诺放弃使用武力。这是统一的战略支撑。","source":{"doc":"6cbfb01fe723bba64b75","first":55,"last":55,"page":55,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-1a461246c93f981d":{"sources":[{"id":"a156952e65e40d9c","label":"独立自主的和平外交政策","topic":"发展与治理","category":"非时政","text":"1.独立自主的和平外交政策\n中国始终坚持维护世界和平、促进共同发展的外交政策宗旨，致力于推动构建人类命运\n共同体。\n中国坚定奉行独立自主的和平外交政策，始终根据事情本身的是非曲直决定自己的立场\n和政策，维护国际关系基本准则，维护国际公平正义。\n中国坚持在和平共处五项原则基础上同各国发展友好合作，推动构建新型国际关系，深\n化拓展平等、开放、合作的全球伙伴关系，致力于扩大同各国利益的汇合点。\n中国坚持对外开放的基本国策，坚定奉行互利共赢的开放战略，不断以中国新发展为世\n界提供新机遇，推动建设开放型世界经济，更好惠及各国人民。\n中国积极参与全球治理体系改革和建设，践行共商共建共享的全球治理观，坚持真正的\n多边主义，推进国际关系民主化，推动全球治理朝着更加公正合理的方向发展。\n——《党的二十大报告》","source":{"doc":"6cbfb01fe723bba64b75","first":56,"last":56,"page":56,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-720e866ff4b2a5ef":{"sources":[{"id":"f58326ae99401036","label":"全球发展倡议、全球安全倡议、全球文明倡议、全球治理倡议","topic":"发展与治理","category":"非时政","text":"2.全球发展倡议、全球安全倡议、全球文明倡议、全球治理倡议\n当今世界，和平赤字、发展赤字、安全赤字、治理赤字有增无减。提出构建人类命运共\n同体和全球发展倡议、全球安全倡议、全球文明倡议等，就是为了破解上述赤字，推动建设\n一个更加美好的世界，为各国人民创造更加美好的生活。\n（1）全球发展倡议：坚持发展优先，坚持以人民为中心，坚持普惠包容，坚持创新驱\n动，坚持人与自然和谐共生，坚持行动导向。\n（2）全球安全倡议：坚持共同、综合、合作、可持续的安全观，坚持尊重各国主权、\n领土完整，坚持遵守联合国宪章宗旨和原则，坚持重视各国合理安全关切，坚持通过对话协\n商以和平方式解决国家间的分歧和争端，坚持统筹维护传统领域和非传统领域安全。\n（3）全球文明倡议：共同倡导尊重世界文明多样性，共同倡导弘扬全人类共同价值，\n共同倡导重视文明传承和创新，共同倡导加强国际人文交流合作。\n（4）全球治理倡议：第一，奉行主权平等。第二，遵守国际法治。第三，践行多边主\n义。第四，倡导以人为本。第五，注重行动导向。\n——《求是》杂志文章《推动落实全球发展倡议、全球安全倡议、全球文明倡议、全球\n治理倡议》","source":{"doc":"6cbfb01fe723bba64b75","first":56,"last":56,"page":56,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"k-1c8c8d910e7c6d44":{"sources":[{"id":"e21e9734f22320ba","label":"为中国人民谋幸福、为中华民族谋复兴","topic":"党政制度与理论","category":"非时政","text":"1.为中国人民谋幸福、为中华民族谋复兴\n2017 年 10 月，习近平同志在作党的十九大报告时指出，中国共产党人的初心和使\n命，就是为中国人民谋幸福、为中华民族谋复兴。\n——《中国政府网》","source":{"doc":"41195a191a57c1c36332","first":6,"last":6,"page":6,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-7a709d4cd226d71e":{"sources":[{"id":"8258c0a163851d24","label":"新时代全面从严治党宝贵经验","topic":"党政制度与理论","category":"非时政","text":"3.新时代全面从严治党宝贵经验\n在新时代全面从严治党的伟大实践中，我们党积累了丰富的管党治党、兴党强党经\n验：\n1 从制定和落实中央八项规定开局破题，从抓作风入手推进全面从严治党；\n2 明确新时代党的建设总要求，把党的政治建设摆在党的建设统领位置；\n3 强调全面从严治党，核心是加强党的领导；\n4 坚持思想建党和制度治党有机结合、同向发力；\n5 反复强调打铁必须自身硬，把严的标准、严的措施贯穿于党的建设全过程和各\n方面，持续抓思想从严、监督从严、执纪从严、治吏从严、作风从严、反腐从严；\n6 注重整体谋划、系统推进，坚持党性党风党纪一起抓、正风肃纪反腐相贯通；\n7 坚持以上率下，从领导机关和领导干部严起、抓起，通过抓“关键少数”示范\n带动“绝大多数”；\n8 把党的建设融入党和国家事业发展大局，为推进中国式现代化提供坚强保障；\n——求是网","source":{"doc":"41195a191a57c1c36332","first":9,"last":9,"page":9,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-35e86ef7d63779d5":{"sources":[{"id":"f6c7e3e05b194754","label":"指导思想","topic":"二十届五中全会","category":"时政","text":"三、指导思想\n全会指出，持之以恒推进全面从严治党，必须坚持马克思列宁主义、毛泽东思想、邓小\n平理论、“三个代表”重要思想、科学发展观，全面贯彻习近平新时代中国特色社会主义思\n想，深入学习贯彻习近平党建思想，围绕实现党的使命任务，落实新时代党的建设总要求，\n以党章为根本，坚持党的先锋队性质，坚持党的全面领导和党中央集中统一领导，着眼于提\n高党的长期执政能力、保持党的先进性和纯洁性、保持党同人民群众的血肉联系，坚持严的\n基调不动摇，健全全面从严治党体系，以党的政治建设①为统领，全面推进党的各方面建设，\n充分激发全党积极性主动性创造性，不断实现党的自我净化、自我完善、自我革新、自我提\n高②，持续增强党的政治领导力、思想引领力、群众组织力、社会号召力③，确保党始终成为\n走在时代前列、人民衷心拥护、经得起各种风浪考验、朝气蓬勃的马克思主义执政党，始终\n成为中国特色社会主义事业的坚强领导核心。","source":{"doc":"41195a191a57c1c36332","first":10,"last":10,"page":10,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"k-6fd769591b633896":{"sources":[{"id":"4a5b5b923a758beb","label":"持之以恒推进全面从严治党遵循的原则","topic":"二十届五中全会","category":"时政","text":"四、持之以恒推进全面从严治党遵循的原则\n全会强调，持之以恒推进全面从严治党遵循的原则①是：坚持服务使命任务，坚持以党\n的政治建设为统领，坚持全面从严，坚持问题导向，坚持守正创新，坚持以上率下，坚持依\n规治党。","source":{"doc":"41195a191a57c1c36332","first":12,"last":12,"page":12,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"k-ef1b2f97e9a838ee":{"sources":[{"id":"2c75834f1125c963","label":"持之以恒推进全面从严治党遵循的原则“七个坚持”：","topic":"二十届五中全会","category":"时政","text":"1.持之以恒推进全面从严治党遵循的原则“七个坚持”：\n坚持服务使命任务，就要围绕全面建成社会主义现代化强国、实现第二个百年奋斗目\n标，以更高标准、更实举措推进全面从严治党，确保党始终成为中国特色社会主义事业的\n坚强领导核心；\n坚持以党的政治建设为统领，就要保证全党服从中央，坚持党中央权威和集中统一领\n导；\n坚持全面从严，就要坚持严的基调不动摇，真管真严、敢管敢严、长管长严；\n坚持问题导向，就要奔着问题去、盯着问题改，把党的建设面临的突出问题整治好、\n解决好；\n坚持守正创新，就要守好本和源、根和魂，与时俱进、开拓进取，积极识变应变求变；\n坚持以上率下，就要一级带一级，一级做给一级看，各级领导干部自觉起示范带头作\n用；\n坚持依规治党，就要健全科学完备、有效管用的制度体系，全方位织密制度的笼子。\n“七个坚持”相互贯通、有机统一，既是认识论，又是方法论，体现了对马克思主义政\n党建设规律的深刻把握。","source":{"doc":"41195a191a57c1c36332","first":12,"last":12,"page":12,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-a772f9cb3795b177":{"sources":[{"id":"e3135023bfa8521b","label":"系统部署","topic":"二十届五中全会","category":"时政","text":"五、系统部署\n全会对持之以恒推进全面从严治党作出系统部署，①强调增强共产党人的党性，②严格\n贯彻执行民主集中制，③锻造堪当民族复兴重任的高素质干部队伍，④建设上下贯通、执行\n有力的严密组织体系，⑤驰而不息正风肃纪，⑥坚定不移一体推进不敢腐不能腐不想腐，⑦\n坚持制度治党、依规治党，⑧完善党和国家监督体系，⑨压紧压实管党治党责任。","source":{"doc":"41195a191a57c1c36332","first":12,"last":12,"page":12,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"k-fb501bd210c1cbd0":{"sources":[{"id":"7f8ebc0151f0130b","label":"增强党性①是全面从严治党的根本性任务","topic":"二十届五中全会","category":"时政","text":"（一）增强党性①是全面从严治党的根本性任务\n必须推动全体党员、干部坚持党的性质和宗旨，增强党的意识、党员意识、先锋队意识，\n把加强党性修养作为终身课题，在坚定理想信念、铸牢对党忠诚、厚植为民情怀、坚持实事\n求是、纯正道德品质、保持清正廉洁②等方面下功夫，做到忠诚干净担当，始终保持共产党\n人政治本色。要强化对党忠诚教育，坚持用党的创新理论凝心铸魂，用党的优良传统和中华\n优秀传统文化涵养党性，在实践中锤炼党性，加强党性鉴别。","source":{"doc":"41195a191a57c1c36332","first":12,"last":13,"page":12,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"k-c42e11761c223003":{"sources":[{"id":"cb655afd8c44625f","label":"坚定理想信念、铸牢对党忠诚、厚植为民情怀、坚持实事求是、纯正道德品质、保持清正廉洁","topic":"党政制度与理论","category":"非时政","text":"2.坚定理想信念、铸牢对党忠诚、厚植为民情怀、坚持实事求是、纯正道德品质、保\n持清正廉洁\n坚定理想信念：增强党性，“坚定理想信念”居于首位，要坚定马克思主义信仰，坚\n定共产主义远大理想，坚定中国特色社会主义信念。坚定理想信念，坚守共产党人精神追\n求，始终是共产党人安身立命的根本，始终是每名党员干部增强党性、炼就“金刚不坏之\n身”的关键所在。\n铸牢对党忠诚：“天下至德，莫大于忠”，对党忠诚，是共产党人最重要的政治品质。\n中国共产党一路走来，经历过无数艰险和磨难，没有被任何困难压垮，靠的就是千千万万\n党员的忠诚，忠诚于党的理想信念、忠诚于党的奋斗目标、忠诚于党的伟大事业，铁心跟\n党走，虽九死而不悔，用对党忠诚的气节和行动构筑了不屈的精神脊梁。\n厚植为民情怀：江山就是人民、人民就是江山，打江山、守江山，守的是人民的心。\n厚植为民情怀，是贯穿于我们党的性质宗旨、历史实践和面向未来的必然要求，是党永葆\n生机活力、赢得民心的关键所在。\n坚持实事求是：实事求是，是马克思主义的根本观点，是中国共产党人认识世界、改\n造世界的根本要求，是我们党的基本思想方法、工作方法、领导方法。坚持从实际出发、\n实事求是，不只是思想方法问题，也是党性强不强问题。\n纯正道德品质：涵养高尚的道德品质是我们党对党员干部的一贯要求，只有不断加强\n党性锤炼，明大德、守公德、严私德，其才方能用得其所。\n保持清正廉洁：“廉者，政之本也”。清正廉洁是共产党人的立身之本，更是不能丢\n弃的底色。保持清正廉洁的政治本色是党性修养的重要内容。","source":{"doc":"41195a191a57c1c36332","first":13,"last":14,"page":13,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-8026f07aab3cc5a0":{"sources":[{"id":"83048902814807e7","label":"建设高素质干部队伍","topic":"党政制度与理论","category":"非时政","text":"3.建设高素质干部队伍\n《决定》从 6 个方面作出部署：一是坚持正确用人导向。强调坚持党管干部原则，落\n实新时代好干部标准，大力选拔任用对党忠诚、表里如一、担当尽责、实绩突出、清正廉\n洁的干部，坚决不用那些畏难避事、庸懒无为、作风漂浮的人，坚决清除那些对党不忠、\n阳奉阴违、以权谋私的人。二是精准科学选人用人。坚持组织选人、公正用人、以事择人，\n严格执行干部选拔任用原则和程序，坚决整治用人上的不正之风。三是推动干部树立和践\n行正确政绩观。深化政绩观教育，改进推动高质量发展政绩考核，健全有效防范和纠治政\n绩观偏差工作机制，引导干部为人民出政绩、以实干出政绩。四是增强干部干事创业本\n领。加强干部思想淬炼、政治历练、实践锻炼、专业训练，增强推动高质量发展本领、服\n务群众本领、防范化解风险本领、运用法治思维和法治方式开展工作本领。五是提高培养\n选拔优秀年轻干部质量。坚持培养和管理并重，引导年轻干部走健康成长之路。六是加强\n干部管理监督。从高级干部抓起，加强干部全方位管理和经常性监督。","source":{"doc":"41195a191a57c1c36332","first":16,"last":16,"page":16,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-1cbc3ec8b58a4454":{"sources":[{"id":"42eca6d3cff14a84","label":"体系化推进各层级各领域党组织建设。","topic":"党政制度与理论","category":"非时政","text":"1.体系化推进各层级各领域党组织建设。\n严密的组织体系，是马克思主义政党的优势所在、力量所在。党的力量来自组织，党\n的全面领导、党的全部工作要靠党的坚强组织体系去实现。我们党历来高度重视组织的统\n一和巩固，伴随着革命、建设、改革的历史进程，建立起包括党的中央组织、地方组织、\n基层组织在内的严密组织体系。\n《决定》从 6 个方面作出部署：一是发挥中央和国家机关党组织表率作用。深化政治\n机关建设，把中央和国家机关建设成为讲政治、守纪律、负责任、有效率的模范机关。二\n是强化地方党委功能。强调地方党委在本地区履行把方向、管大局、作决策、保落实职责，\n把地方党委建设成为坚决听从党中央指挥、执行有力、管理严格、班子团结、风气纯正的\n坚强组织。三是统筹推进各领域基层党组织建设。强化大抓基层鲜明导向，深入推进抓党\n建促乡村全面振兴，加强城市街道、社区党建工作，深化党建引领基层治理和基层政权建\n设。四是突出抓好新兴领域党的建设。深化拓展新经济组织、新社会组织、新就业群体党\n的组织覆盖和工作覆盖，增强党在新兴领域号召力凝聚力影响力。五是加强党员队伍建\n设。坚持把政治标准放在首位，提高发展党员质量，优化党员队伍结构，强化党员教育管\n理，完善和落实党员作用发挥机制。六是完善党的各级组织贯通机制。坚持抓好本级、带\n动下级，层层抓落实，做实党委（党组）书记抓基层党建工作述职评议考核，推动党的各\n级组织全面进步、全面过硬。","source":{"doc":"41195a191a57c1c36332","first":16,"last":17,"page":16,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"k-d77ed4e956f700af":{"sources":[{"id":"eb6e958d6dec648b","label":"正风肃纪是全面从严治党的有力举措","topic":"二十届五中全会","category":"时政","text":"（五）正风肃纪是全面从严治党的有力举措。\n必须坚持党性党风党纪一起抓①、正风肃纪反腐相贯通，深化运用从抓作风入手推\n进全面从严治党经验，不断改进作风，用严明的纪律②管党治党，以良好形象凝心聚力。\n要走好新时代党的群众路线，锲而不舍落实中央八项规定精神，推进作风建设③常态化\n长效化，强化从严执纪，综合发挥纪律教育约束、保障激励作用。","source":{"doc":"41195a191a57c1c36332","first":17,"last":17,"page":17,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"k-c753dbf8d5dec887":{"sources":[{"id":"fb0f94ee065b8e4b","label":"一体推进不敢腐不能腐不想腐是全面从严治党的重要方略和反腐败斗争的基本","topic":"二十届五中全会","category":"时政","text":"（六）一体推进不敢腐不能腐不想腐是全面从严治党的重要方略和反腐败斗争的基本\n方针。\n必须牢记党除了工人阶级和最广大人民群众的利益没有自己特殊的利益、党同腐\n败水火不容，坚定走好中国特色反腐败之路①，加强党中央对反腐败工作的集中统一领\n导，更加注重标本兼治、系统施治，坚持从严惩、精准治、有效防、一体抓，将反腐\n败斗争进行到底。①要保持惩治腐败高压态势，②加强对权力运行的制约和监督，③\n夯实崇廉拒腐思想根基，④增强一体推进不敢腐不能腐不想腐②综合效能。","source":{"doc":"41195a191a57c1c36332","first":18,"last":18,"page":18,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]}}};
